function (T, out, t, p) {
  const n = Math.round(p.items);
  const scale = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21];
  const lane = T.pan(out, t, { x: -0.5, to: 0.5, dur: (n - 1) * p.gap + 0.05 });
  for (let k = 0; k < n; k++) {
    const u = n > 1 ? k / (n - 1) : 0;
    const f = p.pitch * Math.pow(2, scale[Math.round(u * p.fan * 9)] / 12);
    const last = k === n - 1;
    T.tick(lane, t + k * p.gap, {
      f: f * 3.4, q: 2, dur: 0.008, peak: 0.02, jitter: 0.5,
      blip: f, blipTo: f * 1.07, blipDur: last ? 0.17 : 0.055, blipPeak: (0.036 + 0.014 * u) * (last ? 1.15 : 1),
    });
  }
}

function (T, out, t, p) {
  const note = (at, f, level) => {
    T.osc(out, at, { f, dur: 0.1, peak: level, a: 0.002 });
    T.osc(out, at, { f: f * 2, dur: 0.05, peak: level * 0.6 * p.bright, a: 0.002 });
  };
  if (p.on >= 0.5) {
    note(t, p.pitch, 0.04);
    note(t + 0.055, p.pitch * 1.5, 0.05);
    T.noise(out, t, { filter: 'highpass', f: 4500, q: 0.7, dur: 0.01, peak: 0.01 + 0.01 * p.bright, a: 0.002 });
  } else {
    T.osc(out, t, { f: p.pitch * 1.5, to: p.pitch * 0.9, dur: 0.07, peak: 0.04, a: 0.002 });
    T.noise(out, t, { filter: 'lowpass', f: 1800, q: 0.7, dur: 0.012, peak: 0.03, a: 0.002 });
  }
}

function (T, out, t, p) {
  T.noise(out, t, { filter: 'bandpass', f: p.pitch * 1.5, to: p.pitch, q: 1.1, dur: 0.018, peak: 0.05 + 0.08 * p.snap, a: 0.002 });
  T.osc(out, t, { type: 'triangle', f: p.pitch * 0.5, to: p.pitch * 0.3, dur: 0.026, peak: 0.012 + 0.04 * p.body, a: 0.002 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch * 1.6, to: p.pitch * 0.7, dur: 0.05 + 0.1 * p.length, peak: 0.07, a: 0.003 });
  // an octave above the body, so the click still reads on small speakers that cannot play 100 Hz
  T.osc(out, t, { f: p.pitch * 3.2, to: p.pitch * 1.4, dur: 0.03 + 0.04 * p.length, peak: 0.025, a: 0.003 });
  T.noise(out, t, { filter: 'lowpass', f: 1400, to: 500, q: 0.8, dur: 0.02, peak: 0.02 + 0.1 * p.click, a: 0.002 });
}

function (T, out, t, p) {
  T.bell(out, t, {
    f: p.pitch, partials: [[1, 1, 1], [2.32, 0.4, 0.55], [3.9, 0.18 + 0.2 * p.bright, 0.3]],
    dur: 0.05 + 0.15 * p.ring, peak: 0.028, a: 0.002,
  });
  T.noise(out, t, { filter: 'highpass', f: 6500, q: 0.7, dur: 0.008, peak: 0.004 + 0.012 * p.bright, a: 0.002 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.73, dur: 0.035, peak: 0.042, a: 0.002 });
  T.noise(out, t, {
    filter: 'highpass', f: 2800 + 2400 * p.tone, to: 2200 + 1800 * p.tone, q: 0.8,
    dur: 0.022, peak: 0.011 + 0.034 * p.tone, a: 0.001,
  });
}

function (T, out, t, p) {
  // The second overtone is what reads as hollow; the fundamental droops a little like a struck block.
  T.bell(out, t, {
    f: p.pitch, partials: [[1, 1, 1], [2.35, 0.25 + 0.4 * p.hollow, 0.55], [4.1, 0.12, 0.3]],
    drift: 0.96, dur: 0.04 + 0.1 * p.ring, peak: 0.04, a: 0.002,
  });
  T.noise(out, t, { filter: 'lowpass', f: 2200, q: 0.7, dur: 0.012, peak: 0.04, a: 0.002 });
}

function (T, out, t, p) {
  T.noise(out, t, { filter: 'bandpass', f: 1200, to: 4200, q: 1.4, dur: 0.045, a: 0.012, peak: 0.03 + 0.1 * p.scoop });
  T.bell(out, t + 0.04, { f: p.pitch, partials: [[1, 1, 1], [2.76, 0.4, 0.5]], dur: 0.08 + 0.17 * p.ring, peak: 0.04, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.crunch);
  let at = t;
  for (let k = 0; k < n; k++) {
    const f = (3400 - k * 220) * T.rand(0.8, 1.2);
    T.noise(out, at, { filter: 'bandpass', f, q: 2.2, dur: T.rand(0.012, 0.022), peak: 0.1 * T.rand(0.6, 1) * (1 - 0.06 * k), a: 0.002 });
    at += T.rand(0.008, 0.024);
  }
  const land = at + 0.012;
  T.osc(out, land, { f: p.pitch * 1.4, to: p.pitch * 0.6, dur: 0.1, peak: 0.026 + 0.05 * p.weight, a: 0.003 });
  T.osc(out, land, { f: p.pitch * 2.8, to: p.pitch * 1.2, dur: 0.06, peak: 0.012 + 0.02 * p.weight, a: 0.003 });
  T.noise(out, land, { filter: 'lowpass', f: 900, q: 0.7, dur: 0.03, peak: 0.02 + 0.06 * p.weight, a: 0.002 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch * 1.5, to: p.pitch * 0.6, dur: 0.08, peak: 0.065, a: 0.003 });
  T.osc(out, t, { f: p.pitch * 3, to: p.pitch * 1.2, dur: 0.05, peak: 0.022, a: 0.003 });
  T.noise(out, t, { filter: 'lowpass', f: 1500, to: 600, q: 0.7, dur: 0.025, peak: 0.04 + 0.1 * p.snap, a: 0.002 });
  T.osc(out, t + 0.075, { f: p.pitch * 1.3, to: p.pitch * 0.6, dur: 0.05, peak: 0.028 * p.bounce, a: 0.003 });
}

function (T, out, t, p) {
  T.noise(out, t, { filter: 'highpass', f: 3500, q: 0.8, dur: 0.01, peak: 0.012, a: 0.002 });
  T.noise(out, t, { filter: 'bandpass', f: 500, to: 500 + 2200 * p.lift, q: 1, dur: 0.11, a: 0.045, peak: 0.04 + 0.1 * p.air });
  T.osc(out, t, { type: 'triangle', f: p.pitch, to: p.pitch * (1.15 + 0.6 * p.lift), dur: 0.08, peak: 0.03, a: 0.008, glide: 0.06 });
}

function (T, out, t, p) {
  if (p.drop < 0.5) {
    T.noise(out, t, { filter: 'bandpass', f: 500, to: 2400, q: 1.2, dur: 0.2, a: 0.09, peak: 0.04 + 0.08 * p.air });
    T.osc(out, t, { f: 260, to: 390, dur: 0.19, peak: 0.022, a: 0.08 });
    return;
  }
  const base = 210 - 100 * p.depth;
  T.noise(out, t, { filter: 'bandpass', f: 2200, to: 400, q: 1, dur: 0.08, a: 0.012, peak: 0.03 + 0.07 * p.air });
  const at = t + 0.06;
  T.osc(out, at, { f: base * 1.7, to: base * 0.55, dur: 0.1, peak: 0.065, a: 0.003 });
  T.noise(out, at, { filter: 'lowpass', f: 1400, to: 500, q: 0.7, dur: 0.03, peak: 0.04, a: 0.002 });
  T.bell(out, at + 0.1, { f: 880, partials: [[1, 1, 1], [2.76, 0.25, 0.5]], dur: 0.14, peak: 0.026, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.steps);
  const open = p.open >= 0.5;
  const scale = [0, 2, 4, 7, 9];
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, scale[open ? k : n - 1 - k] / 12);
    T.osc(out, t + k * p.gap, { type: 'triangle', f, to: f * 1.03, dur: 0.05, peak: open ? 0.05 : 0.04, a: 0.002 });
  }
  T.noise(out, t, { filter: 'highpass', f: 4500, q: 0.7, dur: 0.008, peak: 0.006, a: 0.002 });
}

function (T, out, t, p) {
  const open = p.open >= 0.5;
  const d = Math.round(p.depth) - 1;
  const lift = Math.pow(2, (4 * d) / 12);
  const f = p.pitch * lift;
  const len = 0.045 - 0.007 * d;
  const lo = 1300 * lift;
  const hi = 3300 * lift;
  T.noise(out, t, {
    filter: 'bandpass', f: open ? lo : hi, to: open ? hi : lo, q: 1.2,
    dur: len + 0.03, a: Math.max(0.01, len * 0.5), peak: 0.07,
  });
  const at = t + len * 0.85;
  if (open) {
    T.osc(out, at, { type: 'triangle', f, to: f * 1.04, dur: 0.055, peak: 0.04, a: 0.002 });
    T.osc(out, at, { f: f * 2, dur: 0.03, peak: 0.01, a: 0.002 });
  } else {
    T.osc(out, at, { type: 'triangle', f: f * 0.7, to: f * 0.55, dur: 0.035, peak: 0.032, a: 0.002 });
    T.noise(out, at, { filter: 'highpass', f: 3500, q: 0.8, dur: 0.01, peak: 0.008, a: 0.002 });
  }
}

function (T, out, t, p) {
  const ring = T.delay(out, t, { time: p.spread, fb: 0.34, mix: p.echo, tone: 3500 });
  T.osc(ring, t, { f: p.pitch, to: p.pitch * 1.12, dur: 0.05, peak: 0.04, a: 0.006 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.9, dur: 0.02, peak: 0.02, a: 0.002 });
  T.noise(out, t, { filter: 'highpass', f: 6000, q: 0.7, dur: 0.01, peak: 0.003 + 0.009 * p.air, a: 0.002 });
}

function (T, out, t, p) {
  const v = 1 + 0.06 * T.rand(-1, 1);
  const l = 1 + 0.12 * T.rand(-1, 1);
  const f = p.pitch * (1 - 0.3 * p.size) * v;
  T.osc(out, t, { f, to: f * 0.7, dur: 0.04 + 0.03 * p.size, peak: 0.036 * (1 + 0.4 * p.size) * l, a: 0.003 });
  T.noise(out, t, { filter: 'bandpass', f: (1200 + 2000 * p.bright) * v, q: 1.2, dur: 0.02, peak: 0.05 * l, a: 0.002 });
}

function (T, out, t, p) {
  const v = 1 + 0.04 * T.rand(-1, 1);
  const l = 1 + 0.1 * T.rand(-1, 1);
  T.bell(out, t, { f: p.pitch * v, partials: [[1, 1, 1], [2.7, 0.4, 0.6]], drift: 0.97, dur: 0.03, peak: 0.016 * p.click * l, a: 0.002 });
  T.noise(out, t, { filter: 'highpass', f: 3500, q: 0.8, dur: 0.012, peak: (0.01 + 0.024 * p.click) * l, a: 0.002 });
  const at = t + 0.014;
  T.osc(out, at, { f: 260 * v, to: 160 * v, dur: 0.045, peak: (0.016 + 0.048 * p.thock) * l, a: 0.002 });
  T.noise(out, at, { filter: 'lowpass', f: 1400, q: 0.7, dur: 0.02, peak: (0.024 + 0.048 * p.thock) * l, a: 0.002 });
  T.noise(out, t + 0.085, { filter: 'highpass', f: 3500, q: 0.8, dur: 0.01, peak: (0.006 + 0.01 * p.click) * l, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.petals);
  const open = p.open >= 0.5;
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const f = p.pitch * Math.pow(2, scale[open ? k : n - 1 - k] / 12);
    const x = (open ? -0.7 : 0.7) + (open ? 1.4 : -1.4) * (k / (n - 1));
    const ring = T.pan(out, at, { x });
    T.osc(ring, at, { type: 'triangle', f, to: f * (open ? 1.04 : 0.96), dur: 0.05, peak: open ? 0.04 : 0.032, a: 0.002 });
    T.noise(ring, at, { filter: 'highpass', f: 4500, q: 0.7, dur: 0.008, peak: 0.006, a: 0.002 });
  }
}

function (T, out, t, p) {
  const open = p.open >= 0.5;
  const len = 0.07 + 0.2 * p.size;
  const lo = 350 + 500 * p.tone;
  const hi = 1400 + 2200 * p.tone;
  T.noise(out, t, {
    filter: 'bandpass', f: open ? lo : hi, to: open ? hi : lo, q: 0.9,
    dur: len + 0.06, a: Math.max(0.01, len * (open ? 0.5 : 0.3)), peak: 0.09,
  });
  const at = t + len * 0.85;
  if (open) {
    T.osc(out, at, { f: 300 - 100 * p.size, to: 200 - 70 * p.size, dur: 0.07, peak: 0.03 + 0.03 * p.size, a: 0.004 });
  } else {
    T.osc(out, at, { f: 700, to: 450, dur: 0.03, peak: 0.03, a: 0.002 });
    T.noise(out, at, { filter: 'highpass', f: 3500, q: 0.8, dur: 0.01, peak: 0.01, a: 0.002 });
  }
}

function (T, out, t, p) {
  const len = p.length;
  T.noise(out, t, {
    filter: 'bandpass', f: 700 + 400 * p.bright, to: 2400 + 2000 * p.bright, q: 0.8,
    dur: len, a: len * 0.35, peak: 0.1,
  });
  for (let k = 0; k < 3; k++) {
    T.noise(out, t + len * (0.15 + 0.55 * T.rand()), { filter: 'highpass', f: 3500, q: 0.8, dur: 0.02, peak: 0.03 * p.rustle, a: 0.002 });
  }
  T.osc(out, t + len * 0.8, { f: 200, to: 140, dur: 0.06, peak: 0.03, a: 0.004 });
}

function (T, out, t, p) {
  const k = Math.round(p.key);
  const row = k === 0 ? 3 : Math.floor((k - 1) / 3);
  const col = k === 0 ? 1 : (k - 1) % 3;
  const shift = Math.pow(2, p.pitch / 12);
  T.osc(out, t, { f: [697, 770, 852, 941][row] * shift, dur: 0.055, peak: 0.022, a: 0.003 });
  T.osc(out, t, { f: [1209, 1336, 1477][col] * shift, dur: 0.045, peak: 0.016, a: 0.003 });
  T.osc(out, t, { f: 170, to: 110, dur: 0.035, peak: 0.004 + 0.03 * p.body, a: 0.003 });
  if (p.done >= 0.5) {
    T.bell(out, t + 0.07, { f: 1047 * shift, partials: [[1, 1, 1], [2, 0.2, 0.5]], dur: 0.09, peak: 0.034, a: 0.002 });
    T.bell(out, t + 0.125, { f: 1568 * shift, partials: [[1, 1, 1], [2, 0.2, 0.5]], dur: 0.13, peak: 0.038, a: 0.002 });
  }
}

function (T, out, t, p) {
  const gap = (60 / p.bpm) * 0.22;
  const thump = (at, f, level, len) => {
    T.osc(out, at, { f: f * 1.5, to: f, glide: 0.045, dur: len, peak: 0.05 * level, a: 0.008 });
    T.osc(out, at, { f: f * 3, to: f * 2, glide: 0.04, dur: len * 0.6, peak: 0.017 * level * (1.3 - 0.8 * p.soft), a: 0.008 });
    T.noise(out, at, { filter: 'lowpass', f: 420 - 260 * p.soft, q: 0.7, dur: 0.045, peak: 0.05 * level, a: 0.005 });
  };
  thump(t, p.pitch, 1, 0.15);
  thump(t + gap, p.pitch * 0.85, 0.7, 0.13);
}

function (T, out, t, p) {
  const rise = 1.15 + 0.6 * p.bloop;
  T.osc(out, t, { f: p.pitch, to: p.pitch * rise, dur: 0.09, peak: 0.055, a: 0.004, glide: 0.05 });
  T.osc(out, t, { f: p.pitch / 2, to: (p.pitch / 2) * rise, dur: 0.07, peak: 0.015 + 0.03 * p.round, a: 0.004, glide: 0.05 });
  T.noise(out, t, { filter: 'highpass', f: 4000, q: 0.7, dur: 0.008, peak: 0.006, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.stars);
  const scale = [0, 2, 4, 7, 9];
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const f = p.pitch * Math.pow(2, scale[k] / 12);
    const last = k === n - 1;
    T.bell(out, at, { f, partials: [[1, 1, 1], [2, 0.2, 0.5]], dur: last ? 0.12 : 0.07, peak: 0.036, a: 0.002 });
    T.noise(out, at, { filter: 'highpass', f: 5000, q: 0.7, dur: 0.007, peak: 0.005, a: 0.002 });
    if (last && n === 5) {
      T.bell(out, at + 0.02, { f: f * 3, partials: [[1, 1, 1], [2.76, 0.4, 0.5]], dur: 0.13, peak: 0.01 + 0.04 * p.glint, a: 0.002 });
    }
  }
}

function (T, out, t, p) {
  const f = p.pitch;
  if (p.on >= 0.5) {
    for (let k = 0; k < 2; k++) {
      T.osc(out, t + k * 0.09, { f, dur: 0.05, peak: 0.036, a: 0.003 });
    }
    T.osc(out, t + 0.18, { f: f * 1.5, dur: p.length, peak: 0.04, a: 0.003, s: 0.9, d: 0.01, r: p.length * 0.3 });
    T.osc(out, t + 0.18, { type: 'triangle', f: f * 3, dur: p.length * 0.7, peak: 0.008, a: 0.003 });
  } else {
    const len = p.length * 2;
    T.osc(out, t, { f: f * 1.5, to: f * 0.5, dur: len, peak: 0.04, a: 0.004, glide: len * 0.9, tail: 0.15 });
    T.osc(out, t, { type: 'triangle', f: f * 3, to: f, dur: len * 0.6, peak: 0.008, a: 0.004 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.ticks);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const v = 1 + 0.05 * T.rand(-1, 1);
    T.bell(out, at, { f: p.pitch * v, partials: [[1, 1, 1], [2.76, 0.35, 0.5]], drift: 0.97, dur: 0.022, peak: 0.02, a: 0.002 });
    T.noise(out, at, { filter: 'bandpass', f: 2400 * v, q: 4, dur: 0.008, peak: 0.07, a: 0.002 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.shakes);
  const low = p.pitch * Math.pow(2, -p.drop / 12);
  const sides = [T.pan(out, t, { x: -0.4 }), T.pan(out, t, { x: 0.4 })];
  for (let k = 0; k < n; k++) {
    const at = t + k * 0.13;
    const f = k % 2 === 0 ? p.pitch : low;
    const lane = sides[k % 2];
    T.osc(lane, at, { type: 'triangle', f: f * 1.05, to: f, glide: 0.03, dur: 0.1, peak: 0.055, a: 0.008, lp: 2400 });
    if (p.rough > 0.02) {
      T.osc(lane, at, { type: 'sawtooth', f, to: f * 0.98, dur: 0.09, peak: 0.02 * p.rough, a: 0.008, lp: 1300 });
    }
  }
}

function (T, out, t, p) {
  const open = p.open >= 0.5;
  const base = 190 - 90 * p.weight;
  const len = 0.07 + 0.05 * p.weight;
  if (open) {
    T.noise(out, t, { filter: 'bandpass', f: 250, to: 900, q: 0.8, dur: len + 0.04, a: len * 0.6, peak: 0.13 });
    const at = t + len;
    T.osc(out, at, { f: base * 1.6, to: base * 0.6, dur: 0.09, peak: 0.07, a: 0.003 });
    T.noise(out, at, { filter: 'lowpass', f: 1400, to: 500, q: 0.7, dur: 0.025, peak: 0.04, a: 0.002 });
    T.noise(out, at, { filter: 'bandpass', f: 2200, q: 2, dur: 0.006, peak: 0.05, a: 0.002 });
    T.osc(out, at + 0.075, { f: base * 1.3, to: base * 0.7, dur: 0.055, peak: 0.05 * p.rebound, a: 0.003 });
  } else {
    T.noise(out, t, { filter: 'bandpass', f: 900, to: 220, q: 0.8, dur: len * 0.7 + 0.04, a: len * 0.3, peak: 0.1 });
    const at = t + len * 0.7;
    T.osc(out, at, { f: base * 1.3, to: base * 0.6, dur: 0.07, peak: 0.045, a: 0.003 });
    T.noise(out, at, { filter: 'lowpass', f: 1000, to: 400, q: 0.7, dur: 0.02, peak: 0.025, a: 0.002 });
  }
}

function (T, out, t, p) {
  const f = p.pitch * Math.pow(2, p.pos);
  T.osc(out, t, { type: 'triangle', f, to: f * 0.8, dur: 0.03, peak: 0.037, a: 0.002 });
  T.noise(out, t, { filter: 'bandpass', f: f * 2, q: 2, dur: 0.012, peak: 0.016 + 0.066 * p.edge, a: 0.002 });
}

function (T, out, t, p) {
  const dev = 0.1 + 0.35 * p.depth;
  // f0 is the start pitch (a little above the rest note); the modulator runs at wobble x (f0 / pitch) Hz
  const voice = (mult, level) => {
    const f0 = p.pitch * mult * 1.1;
    const f1 = p.pitch * mult;
    T.fm(out, t, {
      type: 'sine', f: f0, to: f1, glide: 0.07, ratio: p.wobble / (p.pitch * mult),
      index: (p.pitch * mult * dev) / p.wobble, index1: 0, dur: p.settle, peak: level, a: 0.006, tail: 0.12,
    });
  };
  voice(1, 0.05);
  voice(2, 0.016);
  T.tick(out, t, { f: 2600, q: 1.6, dur: 0.008, peak: 0.02 });
}

function (T, out, t, p) {
  const w = p.weight;
  // the thump: a body note that sags, longer and a bit deeper with weight
  T.osc(out, t, { f: p.pitch * (1.2 - 0.25 * w), to: p.pitch * 0.4, dur: 0.1 + 0.08 * w, peak: 0.085 + 0.04 * w, a: 0.003, glide: 0.07 });
  // the block's knock, an octave and a bit above the thump, where small speakers can hear it
  T.osc(out, t, { type: 'triangle', f: p.pitch * 2.6, to: p.pitch * 1.3, dur: 0.05, peak: 0.07, a: 0.002, glide: 0.04 });
  // the slap: the flat of the pad on paper
  T.noise(out, t, { filter: 'bandpass', f: 1000, q: 0.9, dur: 0.035, peak: 0.12, a: 0.002 });
  T.tick(out, t, { f: 3600, q: 1.1, dur: 0.008, peak: 0.04 });
  // the splat: ink squeezed out sideways, a falling hiss and a small wet blip
  T.noise(out, t + 0.012, { filter: 'bandpass', f: 4200, to: 1500, q: 0.8, dur: 0.07 + 0.04 * p.ink, peak: 0.03 + 0.1 * p.ink, a: 0.006 });
  T.osc(out, t + 0.012, { f: 950, to: 320, dur: 0.04, peak: 0.02 + 0.04 * p.ink, a: 0.004, glide: 0.03 });
  // the peel: the rubber letting go of the sheet
  T.noise(out, t + 0.17, { filter: 'bandpass', f: 1800, to: 4800, q: 1.4, dur: 0.06 + 0.06 * p.ink, peak: 0.018 + 0.02 * p.ink, a: 0.02 });
}

function (T, out, t, p) {
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  const idx = Math.max(0, Math.min(7, Math.round(p.step) - 1));
  const f = p.pitch * Math.pow(2, scale[idx] / 12);
  const last = Math.round(p.step) >= Math.round(p.steps);
  // the note: a round triangle with a quiet octave, so it sits warm rather than glassy
  T.osc(out, t, { type: 'triangle', f, dur: 0.2, peak: 0.068, a: 0.008 });
  T.osc(out, t, { f: f * 2, dur: 0.08, peak: 0.014, a: 0.008 });
  // the landing: a small wooden knock under the note's start
  T.osc(out, t, { f: 170, to: 100, dur: 0.05, peak: 0.032, a: 0.003, glide: 0.04 });
  T.tick(out, t, { f: 2200, q: 1.2, dur: 0.008, peak: 0.02 });
  if (last) {
    // the finish: two bell glints, an octave and a fifth over the note
    T.bell(out, t + 0.08, { f: f * 2, dur: 0.3, peak: 0.026, a: 0.004, partials: [[1, 1, 1], [2.76, 0.12, 0.3]] });
    T.bell(out, t + 0.14, { f: f * 3, dur: 0.27, peak: 0.018, a: 0.004, partials: [[1, 1, 1], [2.76, 0.1, 0.3]] });
  }
}

function (T, out, t, p) {
  const up = p.up >= 0.5;
  const f = p.pitch;
  // the rise starts a little under the resting note and the fall a little over it, so the two
  // never begin on the same pitch and the direction reads even in 40 ms
  T.osc(out, t, {
    f: f * (up ? 0.9 : 1.1), to: f * (up ? 1.25 : 0.8), dur: 0.042, peak: 0.04, a: 0.003, glide: 0.025, s: 0.7, d: 0.01, r: 0.018,
  });
  T.noise(out, t, { filter: 'lowpass', f: 1800, q: 0.7, dur: 0.012, peak: 0.005 + 0.04 * p.pat, a: 0.002 });
}

function (T, out, t, p) {
  const f0 = 520 * Math.pow(2, p.prev);
  const f1 = 520 * Math.pow(2, p.pos);
  const len = 0.05 + 0.05 * Math.abs(p.pos - p.prev);
  T.noise(out, t, {
    filter: 'bandpass', f: f0 * 2.2, to: f1 * 2.2, q: 2.2,
    dur: len + 0.03, a: Math.max(0.01, len * 0.4), peak: 0.05 + 0.13 * p.air,
  });
  const at = t + len * 0.85;
  T.osc(out, at, { f: f1 * 2, to: f1 * 1.9, dur: 0.035, peak: 0.032, a: 0.002 });
  T.noise(out, at, { filter: 'highpass', f: 4500, q: 0.7, dur: 0.008, peak: 0.006, a: 0.002 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.62, dur: 0.05, peak: 0.05, a: 0.004 });
  T.noise(out, t, { filter: 'lowpass', f: 2600 - 1800 * p.soft, to: 500, q: 0.7, dur: 0.03, peak: 0.025 + 0.11 * p.pat, a: 0.003 });
}

function (T, out, t, p) {
  // the pen tick
  T.tick(out, t, { f: 3300, q: 1.3, dur: 0.01, peak: 0.045, blip: 1300, blipTo: 900, blipPeak: 0.03, blipDur: 0.025 });
  // the strike-through: a quick rising stroke of air, with a thin tone riding it
  T.noise(out, t + 0.03, { filter: 'bandpass', f: 1800, to: 6000, q: 1.6, dur: 0.1, peak: 0.1 * p.swipe, a: 0.03 });
  T.osc(out, t + 0.03, { f: 1500, to: 3000, dur: 0.09, peak: 0.012 * p.swipe, a: 0.03, glide: 0.08 });
  // the ding where the line ends
  T.osc(out, t + 0.12, { type: 'triangle', f: p.pitch, dur: 0.2, peak: 0.075, a: 0.006 });
  T.osc(out, t + 0.12, { f: p.pitch * 2, dur: 0.08, peak: 0.016, a: 0.006 });
  // the streak: glints climbing the pentatonic, an octave above the ding and tighter each time
  const scale = [0, 2, 4, 7, 9];
  const n = Math.round(p.streak);
  for (let k = 0; k < n; k++) {
    T.osc(out, t + 0.2 + k * 0.05, {
      f: p.pitch * 2 * Math.pow(2, scale[k] / 12), dur: 0.09, peak: 0.032, a: 0.003,
    });
  }
}

function (T, out, t, p) {
  const lo = p.pitch * 0.73;
  const up = p.on >= 0.5;
  const click = (f, at, level) => {
    T.bell(out, at, { f, partials: [[1, 1, 1], [2.76, 0.5, 0.67]], drift: 0.98, dur: 0.12, peak: level });
    T.noise(out, at, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: level * 0.6, a: 0.001 });
  };
  click(up ? lo : p.pitch, t, 0.024);
  click(up ? p.pitch : lo, t + p.gap, 0.033);
  T.osc(out, t + p.gap, { f: 420, to: 300, dur: 0.06, peak: 0.075 * p.body, a: 0.002 });
}

function (T, out, t, p) {
  T.fm(out, t, {
    f: p.pitch, to: p.pitch * (1 + 0.9 * p.rise), ratio: 1.5, index: 0.3 + 1.2 * p.shimmer, index1: 0,
    dur: 0.07, peak: 0.04, a: 0.003, glide: 0.03,
  });
  T.noise(out, t, { filter: 'highpass', f: 5000, q: 0.7, dur: 0.008, peak: 0.004, a: 0.002 });
}

function (T, out, t, p) {
  const L = p.slide;
  // the lever flick
  T.tick(out, t, { f: 1300, q: 1.2, dur: 0.012, peak: 0.05, blip: 200, blipTo: 120, blipPeak: 0.03, blipDur: 0.04 });
  // the carriage: a scrape under a run of ticks that bunch up toward the end
  T.noise(out, t + 0.02, { filter: 'bandpass', f: 1000, to: 2200, q: 1.1, dur: L, peak: 0.02, a: L * 0.5 });
  const n = Math.round(L / 0.0125);
  for (let k = 1; k <= n; k++) {
    T.tick(out, t + 0.02 + L * Math.pow(k / n, 0.85), { f: 2700, q: 2, dur: 0.006, peak: 0.032, jitter: 0.8 });
  }
  // the stop
  const stop = t + 0.02 + L;
  T.tick(out, stop, { f: 800, q: 1, dur: 0.02, peak: 0.05, blip: 170, blipTo: 95, blipPeak: 0.045, blipDur: 0.07 });
  if (p.bell > 0.02) {
    T.bell(out, stop + 0.015, {
      f: p.pitch, dur: p.ring, peak: 0.045 * p.bell, a: 0.002,
      partials: [[1, 1, 1], [1.011, 0.7, 0.95], [2.4, 0.35, 0.5], [4.1, 0.2, 0.3], [6.7, 0.08, 0.18]],
    });
  }
}

function (T, out, t, p) {
  T.osc(out, t, {
    type: 'triangle', f: p.pitch, to: p.pitch * 0.45, dur: 0.14, peak: 0.04, a: 0.006,
    s: 0.8, d: 0.01, r: 0.05, trem: { rate: p.speed, depth: 0.8 },
  });
  T.noise(out, t, { filter: 'bandpass', f: 3000, to: 900, q: 1, dur: 0.12, a: 0.01, peak: 0.04 });
  T.bell(out, t + 0.13, { f: p.pitch * 0.5, partials: [[1, 1, 1], [2.76, 0.4, 0.6]], dur: 0.08, peak: 0.005 + 0.03 * p.settle, a: 0.002 });
}

function (T, out, t, p) {
  if (p.pass >= 0.5) {
    T.osc(out, t, { type: 'triangle', f: p.pitch, dur: 0.07, peak: 0.036, a: 0.004 });
    T.osc(out, t + 0.06, { type: 'triangle', f: p.pitch * 1.26, dur: 0.1, peak: 0.036, a: 0.004 });
    T.tick(out, t, { f: 4200, q: 1.2, dur: 0.008, peak: 0.01 });
  } else {
    // a minor third down, through a lowpass so there is no edge, only a little roughness
    const lp = T.filter(out, t, { type: 'lowpass', f: 1700, q: 0.7 });
    const buzz = { rate: 40, depth: 0.6 * p.rough };
    T.osc(lp, t, { type: 'triangle', f: p.pitch, dur: 0.075, peak: 0.039, a: 0.004, trem: buzz });
    T.osc(lp, t + 0.085, { type: 'triangle', f: p.pitch * 0.84, to: p.pitch * 0.8, dur: 0.11, peak: 0.039, a: 0.004, trem: buzz });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const dir = p.dir >= 0.5 ? 1 : -1;
  const lane = T.pan(out, t, { x: -0.85 * dir, to: 0.85 * dir, dur: L });
  // a narrower band throws more noise away: lift the peak so the loudness holds as width changes
  const q = 3.4 - 2.6 * p.width;
  const lift = Math.sqrt(q / 1.4);
  T.noise(lane, t, { filter: 'bandpass', f: 520, to: 3300, q, dur: L, a: L * 0.45, peak: 0.14 * lift, tail: 0.08, fade: 0.06 });
  // the edge: a thin high shimmer that leads the body
  T.noise(lane, t, { filter: 'highpass', f: 5200, to: 8200, q: 0.8, dur: L * 0.85, a: L * 0.55, peak: 0.022 });
  if (p.tick > 0.02) {
    const end = T.pan(out, t, { x: 0.85 * dir });
    T.tick(end, t + L * 0.9, { f: 3100, q: 2.2, dur: 0.012, peak: 0.1 * p.tick, blip: 1500, blipTo: 1150, blipDur: 0.03, blipPeak: 0.045 * p.tick });
  }
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.0, mix: p.space, tone: 0.65 });
  const run = [0, 4, 7];
  for (let k = 0; k < 3; k++) {
    T.osc(room, t + k * p.gap, { type: 'triangle', f: p.pitch * Math.pow(2, run[k] / 12), dur: 0.16, peak: 0.08, a: 0.006 });
  }
  const at = t + 3 * p.gap;
  const chord = [0, 4, 7, 14];
  const level = [1, 0.9, 0.9, 0.5];   // the ninth sits highest, so it is the quietest
  const parts = [[1, 1, 1], [2, 0.18, 0.5], [3, 0.04, 0.3]];
  for (let k = 0; k < chord.length; k++) {
    T.bell(room, at, { f: p.pitch * 2 * Math.pow(2, chord[k] / 12), dur: 0.9, peak: 0.042 * level[k], a: 0.006, partials: parts });
  }
  const glint = [0, 4, 7, 12];
  for (let k = 0; k < glint.length; k++) {
    T.osc(room, at + 0.05 + k * 0.07 + T.rand(0, 0.03), {
      f: p.pitch * 4 * Math.pow(2, glint[k] / 12), dur: 0.1, peak: 0.012 * p.sparkle, a: 0.004,
    });
  }
}

function (T, out, t, p) {
  const rounds = Math.round(p.rounds);
  const lp = T.filter(out, t, { type: 'lowpass', f: 2600, q: 0.7 });
  for (let r = 0; r < rounds; r++) {
    const lift = 1 - 0.6 * p.swell * (rounds - 1 - r) / (rounds - 1);
    for (let k = 0; k < 2; k++) {
      const f = p.pitch * (k ? 1.5 : 1);
      const at = t + r * 0.6 + k * p.pace;
      T.osc(lp, at, { type: 'triangle', f, dur: 0.15, peak: 0.1 * lift, a: 0.02 });
      T.osc(lp, at, { f: f * 2, dur: 0.1, peak: 0.02 * lift, a: 0.02 });
    }
  }
}

function (T, out, t, p) {
  const scale = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21];
  const f = p.pitch * Math.pow(2, scale[Math.max(0, Math.min(9, Math.round(p.count) - 1))] / 12);
  // seeded variation under 1% in pitch, so a run of badges is not one stamped blip
  const j = 1 + T.rand(-0.006, 0.006);
  T.osc(out, t, { f: f * j * (1 - 0.3 * p.bubble), to: f * j, glide: 0.03, dur: 0.1, peak: 0.046, a: 0.004 });
  T.osc(out, t, { f: f * j * 2, dur: 0.04, peak: 0.01, a: 0.004 });
  // the settle: the same note again, small and short
  T.osc(out, t + 0.065, { f: f * j * (1 - 0.15 * p.bubble), to: f * j, glide: 0.02, dur: 0.07, peak: 0.016, a: 0.004 });
}

function (T, out, t, p) {
  const tone = Math.round(p.tone);
  if (p.open >= 0.5) {
    const slide = 0.12 + 0.08 * p.weight;                 // the longer, the heavier it feels
    const at = t + slide;
    // the slide: air falling with a low body that drops under it
    T.noise(out, t, { filter: 'bandpass', f: 2200, to: 500, q: 0.8, dur: slide + 0.02, peak: 0.08, a: slide * 0.45 });
    T.osc(out, t, { f: 260, to: 150, dur: slide + 0.02, peak: 0.035, a: slide * 0.4, glide: slide });
    // the landing thud: a body note that sags, deeper and longer with weight, and a dull knock
    const body = 150 - 50 * p.weight;
    T.osc(out, at, { f: body * 1.5, to: body * 0.55, dur: 0.1 + 0.08 * p.weight, peak: 0.085, a: 0.004, glide: 0.06 });
    // a higher knock over the body, so a small speaker still hears the landing
    T.osc(out, at, { type: 'triangle', f: body * 3.2, to: body * 1.4, dur: 0.05, peak: 0.04, a: 0.003, glide: 0.04 });
    T.tick(out, at, { filter: 'lowpass', f: 1600, q: 0.7, dur: 0.015, peak: 0.07 });
    if (tone === 1) {
      // alert: a low bong that sags a semitone, two soft partials above it
      T.bell(out, at + 0.05, { f: 247, drift: 0.94, dur: 0.32, peak: 0.07, a: 0.006, partials: [[1, 1, 1], [2, 0.3, 0.5], [3, 0.1, 0.3]] });
    } else if (tone === 2) {
      // all-clear: a rising fourth, then a glint above the second note
      T.osc(out, at + 0.06, { type: 'triangle', f: 523, dur: 0.12, peak: 0.075, a: 0.008 });
      T.osc(out, at + 0.15, { type: 'triangle', f: 698, dur: 0.22, peak: 0.075, a: 0.008 });
      T.osc(out, at + 0.15, { f: 1397, dur: 0.1, peak: 0.02, a: 0.006 });
    }
  } else {
    // pulling out: the slide rises, lighter, and a small latch tick at the top
    const slide = 0.1 + 0.05 * p.weight;
    T.noise(out, t, { filter: 'bandpass', f: 500, to: 2400, q: 0.8, dur: slide + 0.02, peak: 0.05, a: slide * 0.5 });
    T.osc(out, t, { f: 170, to: 280, dur: slide + 0.02, peak: 0.025, a: slide * 0.4, glide: slide });
    T.tick(out, t + slide, { f: 3200, q: 1.5, dur: 0.01, peak: 0.03, blip: 1300, blipPeak: 0.02, blipDur: 0.02 });
  }
}

function (T, out, t, p) {
  T.noise(out, t, { filter: 'bandpass', f: 2200, q: 1.4, dur: 0.025, peak: 0.09 * p.tick, a: 0.003 });
  const start = 1200 + 3200 * p.bright;
  for (let k = 0; k < 2; k++) {
    const f = k ? p.pitch * Math.pow(2, Math.round(p.interval) / 12) : p.pitch;
    const at = t + 0.04 + k * p.gap;
    // the cutoff falls from `start` to just above the note, which is what makes it a pluck
    const lp = T.filter(out, at, { type: 'lowpass', f: start, to: Math.min(start, f * 1.3), dur: 0.3, q: 1.2 });
    T.osc(lp, at, { type: 'sawtooth', f, dur: 0.45, peak: 0.06, a: 0.003 });
    T.osc(lp, at, { type: 'triangle', f: f / 2, dur: 0.3, peak: 0.03, a: 0.003 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.stabs);
  const gap = 0.28;                        // onset to onset, so each stab leaves an 80 ms gap
  const len = 0.2;                         // one stab
  const end = (n - 1) * gap + len;
  // the rumble: one low sine (and its octave, so small speakers still show it) with a fast tremolo
  const sub = p.pitch / 4;
  T.osc(out, t, {
    f: sub, to: sub * 0.97, dur: end + 0.12, peak: 0.055 * p.sub, a: 0.012, s: 0.8, d: 0.05, r: 0.12,
    trem: { rate: 17, depth: 0.7 },
  });
  T.osc(out, t, {
    f: sub * 2, to: sub * 1.94, dur: end + 0.1, peak: 0.03 * p.sub, a: 0.012, s: 0.8, d: 0.05, r: 0.1,
    trem: { rate: 17, depth: 0.7 },
  });
  const lp = T.filter(out, t, { type: 'lowpass', f: 3200, q: 0.8 });
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const f = p.pitch * Math.pow(2, (k * 3) / 12);    // each stab a minor third above the last
    const o = {
      type: 'square', dur: len, peak: 0.075, a: 0.003, s: 0.8, d: 0.025, r: 0.04,
      trem: { rate: 28, depth: 0.55 * p.rough },
    };
    T.osc(lp, at, Object.assign({ f }, o));
    T.osc(lp, at, Object.assign({ f: f * 1.4142 }, o));      // a tritone above: the clash
    T.tick(out, at, { f: 1800, q: 0.9, dur: 0.02, peak: 0.08 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.taps);
  let at = t;
  for (let k = 0; k < n; k++) {
    // seeded wobble in timing and pitch, because a person never knocks twice the same way
    const f = p.pitch * Math.pow(0.93, k) * (1 + T.rand(-0.02, 0.02));
    const lv = 1 - 0.15 * k;
    T.osc(out, at, { f: f * 1.6, to: f, glide: 0.035, dur: 0.1, peak: 0.072 * lv, a: 0.004 });
    T.osc(out, at, { f: f * 3, dur: 0.04, peak: 0.018 * lv, a: 0.004 });
    T.noise(out, at, { filter: 'bandpass', f: 1800, q: 1.6, dur: 0.02, peak: 0.072 * p.wood * lv, a: 0.002 });
    at += p.gap * (1 + T.rand(-0.05, 0.05));
  }
}

function (T, out, t, p) {
  const land = t + p.fall;
  T.osc(out, t, { f: p.pitch * 2, to: p.pitch, glide: p.fall, dur: p.fall + 0.02, peak: 0.05, a: p.fall * 0.4, s: 1, d: 0.01, r: 0.02 });
  T.osc(out, land, { f: 150, to: 70, glide: 0.07, dur: 0.1, peak: 0.07 * p.thump, a: 0.004 });
  T.osc(out, land, { type: 'triangle', f: p.pitch, dur: p.ring, peak: 0.085, a: 0.008 });
  T.osc(out, land + 0.09, { f: p.pitch * 1.5, dur: p.ring * 0.6, peak: 0.05, a: 0.01 });
}

function (T, out, t, p) {
  const lp = T.filter(out, t, { type: 'lowpass', f: p.tone, q: 0.8 });
  const n = Math.round(p.pulses);
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(0.89, k);
    T.osc(lp, t + k * 0.15, {
      type: 'square', f, to: f * 0.95, dur: 0.12, peak: 0.075, a: 0.006, s: 0.6, d: 0.03, r: 0.03,
      trem: { rate: 34, depth: 0.8 * p.rough },
    });
  }
}

function (T, out, t, p) {
  const lp = T.filter(out, t, { type: 'lowpass', f: p.tone, q: 0.7 });
  const per = 1 / p.rate;
  const n = Math.round(0.42 * p.rate);
  for (let r = 0; r < Math.round(p.rings); r++) {
    for (let k = 0; k < n; k++) {
      const swell = 0.6 + 0.4 * Math.sin(Math.PI * (k + 0.5) / n);
      T.osc(lp, t + r * 0.65 + k * per, {
        type: 'triangle', f: k % 2 ? p.pitch * 1.26 : p.pitch, dur: per * 2.2, peak: 0.087 * swell, a: 0.004,
      });
    }
  }
}

function (T, out, t, p) {
  // the 2.76 partial lasts a quarter of the decay, so it reads as the edge of the attack, not a tone
  // a touch of seeded variation (under 1% in pitch, about 1 dB in level) so a busy day is not one
  // identical tap repeated; it is steady when Vary is off
  T.bell(out, t, {
    f: p.pitch * (1 + T.rand(-0.008, 0.008)), dur: p.decay, peak: 0.072 * T.rand(0.9, 1), a: 0.006,
    partials: [[1, 1, 1], [2, 0.2 + 0.3 * p.bright, 0.5], [2.76, 0.04 + 0.12 * p.bright, 0.25]],
  });
}

function (T, out, t, p) {
  const n = Math.round(p.steps);
  const lp = T.filter(out, t, { type: 'lowpass', f: p.tone, to: p.tone * 0.4, dur: (n - 1) * p.gap + 0.4, q: 0.8 });
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(0.89, k);
    const last = k === n - 1;
    const at = t + k * p.gap;
    T.osc(lp, at, { type: 'triangle', f, to: last ? f * 0.8 : f, dur: last ? 0.4 : 0.17, peak: 0.076, a: 0.012 });
    T.osc(lp, at, { f: f / 2, to: last ? f * 0.4 : f / 2, dur: last ? 0.4 : 0.17, peak: 0.036, a: 0.012 });
  }
}

function (T, out, t, p) {
  const room = T.delay(out, t, { time: 0.15, fb: 0.3, mix: p.echo, tone: 3200 });
  const pitch = p.pitch * (1 + T.rand(-0.006, 0.006));   // seeded variation so repeats are not identical
  T.osc(room, t, { f: pitch * 0.667, dur: 0.09, peak: 0.045, a: 0.006 });
  T.bell(room, t + 0.075, {
    f: pitch, dur: p.ring, peak: 0.07, a: 0.004,
    partials: [[1, 1, 1], [2, 0.25, 0.5], [2.76, 0.08 + 0.32 * p.glass, 0.22]],
  });
}

function (T, out, t, p) {
  // seeded variation under 1% in pitch and about 1 dB in level, so repeats are not identical
  const j = 1 + T.rand(-0.008, 0.008);
  const v = T.rand(0.9, 1);
  const notes = [[p.pitch * j, 0, 0.8 * v], [p.pitch * j * Math.pow(2, Math.round(p.interval) / 12), p.gap, v]];
  for (let k = 0; k < 2; k++) {
    const f = notes[k][0];
    const at = t + notes[k][1];
    const lv = notes[k][2];
    T.osc(out, at, { f: f * (1 - 0.22 * p.pop), to: f, glide: 0.03, dur: 0.17, peak: 0.085 * lv, a: 0.006 });
    T.osc(out, at, { f: f * 2, dur: 0.07, peak: 0.018 * lv, a: 0.006 });
  }
}

function (T, out, t, p) {
  const w = p.speed * (1 + T.rand(-0.06, 0.06));   // seeded variation so repeats are not identical
  const pitch = p.pitch * (1 + T.rand(-0.008, 0.008));
  T.noise(out, t, { filter: 'bandpass', f: 600, to: 3200, q: 0.9, dur: w, peak: 0.15 * p.air, a: w * 0.6 });
  T.osc(out, t + w * 0.85, { f: pitch * 0.88, to: pitch, glide: 0.02, dur: 0.11, peak: 0.085, a: 0.005 });
  T.osc(out, t + w * 0.85, { f: pitch * 2, dur: 0.05, peak: 0.016, a: 0.005 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.5, mix: 0.18, tone: 0.6 });
  const parts = [[1, 1, 1], [2, 0.25, 0.5], [2.76, 0.08, 0.2]];
  const pitch = p.pitch * (1 + T.rand(-0.006, 0.006));   // seeded variation so repeats are not identical
  T.noise(room, t, { filter: 'bandpass', f: 3000, to: 700, q: 0.9, dur: 0.1, peak: 0.13 * p.swish, a: 0.03 });
  T.bell(room, t + 0.09, { f: pitch, dur: 0.1, peak: 0.045, a: 0.005, partials: parts });
  T.bell(room, t + 0.2, { f: pitch * Math.pow(2, Math.round(p.interval) / 12), dur: p.ring, peak: 0.07, a: 0.005, partials: parts });
}

function (T, out, t, p) {
  const warm = [[1, 1, 1], [2, 0.14, 0.5], [3, 0.04, 0.25]];
  const glow = p.glow;
  const room = T.delay(out, t, { time: 0.11, fb: 0.15, mix: 0.45 * glow, tone: 2200 });
  if (p.on >= 0.5) {
    const hi = p.pitch * 1.3348;                   // a perfect fourth up
    T.bell(room, t, { f: p.pitch, dur: 0.2, peak: 0.05, a: 0.005, partials: warm });
    T.bell(room, t + 0.1, { f: hi, dur: 0.3, peak: 0.054, a: 0.005, partials: warm });
    T.osc(room, t + 0.1, { f: hi * 2, dur: 0.12, peak: 0.014 * glow, a: 0.006 });
  } else {
    const lp = T.filter(room, t, { type: 'lowpass', f: 2600, to: 900, dur: 0.25 });
    T.bell(lp, t, { f: p.pitch * 0.8, drift: 0.95, dur: 0.28, peak: 0.052, a: 0.006, partials: warm });
  }
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.7, mix: p.space, tone: 0.5 });
  const parts = [[1, 1, 1], [2, 0.3, 0.55], [3, 0.1, 0.3]];
  T.bell(room, t, { f: p.pitch, dur: p.ring, peak: 0.07, a: 0.006, partials: parts });
  T.bell(room, t + p.gap, { f: p.pitch * Math.pow(2, -Math.round(p.drop) / 12), dur: p.ring, peak: 0.075, a: 0.006, partials: parts });
}

function (T, out, t, p) {
  const hi = p.pitch * Math.pow(2, Math.round(p.interval) / 12);
  T.osc(out, t, { type: 'triangle', f: p.pitch, dur: 0.19, peak: 0.11, a: 0.01 });
  T.osc(out, t + p.gap, { type: 'triangle', f: hi, dur: 0.26, peak: 0.11, a: 0.01 });
  T.osc(out, t + p.gap, { f: hi * 2, dur: 0.13, peak: 0.1 * p.shimmer, a: 0.01 });
}

function (T, out, t, p) {
  const n = Math.round(p.cycles) * 2;
  let at = t;
  for (let k = 0; k < n; k++) {
    T.osc(out, at, { type: 'triangle', f: k % 2 ? p.pitch * 1.5 : p.pitch, dur: p.speed * 1.5, peak: 0.055, a: 0.006 });
    at += p.speed;
  }
  T.osc(out, at, { type: 'triangle', f: p.pitch * 2, dur: 0.3, peak: 0.1, a: 0.008 });
  T.osc(out, at, { f: p.pitch * 4, dur: 0.14, peak: 0.06 * p.shimmer, a: 0.008 });
}

function (T, out, t, p) {
  const lp = T.filter(out, t, { type: 'lowpass', f: 1200, q: 0.8 });
  const n = Math.round(p.pulses);
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(0.89, k);
    const last = k === n - 1;
    T.osc(lp, t + k * 0.16, {
      type: 'square', f, to: last ? f * 0.78 : f * 0.97, dur: last ? 0.32 : 0.13, peak: 0.055, a: 0.008,
      s: 0.6, d: 0.03, r: last ? 0.1 : 0.03, trem: { rate: 30, depth: 0.7 * p.rough },
    });
  }
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.6, dur: 0.4, peak: 0.06 * p.weight, a: 0.01 });
}

function (T, out, t, p) {
  const tone = Math.round(p.tone);
  const k = Math.pow(2, p.pitch / 12);
  const land = 0.065;                    // the swish ends as the toast stops
  const at = t + land;
  // the swish rises and cuts off into the tick, like something sliding in and stopping
  T.noise(out, t, { filter: 'bandpass', f: 1400, to: 5200, q: 2, dur: land + 0.01, peak: 0.17 * p.swish, a: land * 0.6 });
  T.tick(out, at, { f: 2600, q: 1.2, dur: 0.012, peak: 0.022 });
  if (tone === 0) {
    // info: one small bell tap
    T.bell(out, at, { f: 880 * k, dur: 0.3, peak: 0.062, a: 0.004, partials: [[1, 1, 1], [2, 0.2, 0.5], [2.76, 0.06, 0.2]] });
  } else if (tone === 1) {
    // success: a rising fifth in round triangles with a glint on the top note
    T.osc(out, at, { type: 'triangle', f: 659 * k, dur: 0.13, peak: 0.08, a: 0.006 });
    T.osc(out, at + 0.08, { type: 'triangle', f: 988 * k, dur: 0.22, peak: 0.08, a: 0.006 });
    T.osc(out, at + 0.08, { f: 1976 * k, dur: 0.09, peak: 0.02, a: 0.006 });
  } else if (tone === 2) {
    // warning: two notes falling a major third, the second longer and wavering
    const lp = T.filter(out, at, { type: 'lowpass', f: 2200, q: 0.7 });
    T.osc(lp, at, { type: 'triangle', f: 554 * k, dur: 0.1, peak: 0.09, a: 0.008 });
    T.osc(lp, at + 0.11, { type: 'triangle', f: 440 * k, dur: 0.24, peak: 0.09, a: 0.01, vib: { rate: 6, depth: 18 } });
  } else if (tone === 3) {
    // danger: two low buzzes, each a step down, through a dull lowpass (a short cousin of the error buzz)
    const lp = T.filter(out, at, { type: 'lowpass', f: 1000, q: 0.8 });
    for (let n = 0; n < 2; n++) {
      const f = 196 * k * Math.pow(0.89, n);
      T.osc(lp, at + n * 0.115, {
        type: 'square', f, to: f * 0.96, dur: 0.1, peak: 0.06, a: 0.005, s: 0.6, d: 0.02, r: 0.03,
        trem: { rate: 34, depth: 0.5 },
      });
    }
  } else {
    // critical: three quick stabs of a tritone buzz, each a little higher, with a sub under the first
    const lp = T.filter(out, at, { type: 'lowpass', f: 2600, q: 0.8 });
    for (let n = 0; n < 3; n++) {
      const f = 294 * k * Math.pow(2, (n * 2) / 12);
      const o = { type: 'sawtooth', dur: 0.075, peak: 0.045, a: 0.004, s: 0.7, d: 0.02, r: 0.025 };
      T.osc(lp, at + n * 0.095, Object.assign({ f }, o));
      T.osc(lp, at + n * 0.095, Object.assign({ f: f * 1.4142 }, o));
    }
    T.osc(out, at, { f: 82 * k, dur: 0.3, peak: 0.07, a: 0.01, s: 0.7, d: 0.04, r: 0.08 });
  }
}

function (T, out, t, p) {
  const sp = p.speed;
  let at = t;
  if (p.drain >= 0.5) {
    // the countdown running out: each tick a little lower and softer than the last
    for (let n = 0; n < 3; n++) {
      T.tick(out, t + (n * 0.055) / sp, {
        f: 2800 * Math.pow(0.82, n), q: 1.4, dur: 0.01, peak: 0.04 * (1 - 0.2 * n),
        blip: 1100 * Math.pow(0.85, n), blipPeak: 0.045 * (1 - 0.2 * n), blipDur: 0.03,
      });
    }
    at = t + 0.17 / sp;
  }
  // the swipe: a band of air and a faint tone both falling
  T.noise(out, at, { filter: 'bandpass', f: 3800, to: 650, q: 1.1, dur: 0.1 / sp, peak: 0.1, a: 0.012 / sp });
  T.osc(out, at, { f: 1000, to: 420, dur: 0.09 / sp, peak: 0.022, a: 0.01 / sp, glide: 0.08 / sp });
  // the pat: a short muffled thud as it comes to rest
  const land = at + 0.085 / sp;
  T.osc(out, land, { f: 190, to: 110, dur: 0.07, peak: 0.07 * p.pat, a: 0.004, glide: 0.05 });
  T.tick(out, land, { filter: 'lowpass', f: 1500, q: 0.7, dur: 0.012, peak: 0.05 * p.pat });
}

function (T, out, t, p) {
  const top = p.pitch * 1.5;
  T.osc(out, t, { f: p.pitch * 0.6, to: top, glide: p.rise, dur: p.rise, peak: 0.05, a: p.rise * 0.5, s: 1, d: 0.01, r: 0.02 });
  const at = t + p.rise;
  T.osc(out, at, { type: 'triangle', f: top, dur: p.ring, peak: 0.105, a: 0.008 });
  T.osc(out, at, { f: top * 2, dur: p.ring * 0.45, peak: 0.05 * p.shimmer, a: 0.008 });
}

function (T, out, t, p) {
  const lp = T.filter(out, t, { type: 'lowpass', f: p.tone, q: 0.7 });
  const low = p.pitch * Math.pow(2, -Math.round(p.drop) / 12);
  T.osc(lp, t, { type: 'triangle', f: p.pitch, dur: 0.15, peak: 0.1, a: 0.01 });
  T.osc(lp, t + p.gap, { type: 'triangle', f: low, dur: 0.3, peak: 0.1, a: 0.012, vib: { rate: 5, depth: 14 } });
}

function (T, out, t, p) {
  const n = Math.round(p.bars);
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  const heights = [];
  for (let k = 0; k < n; k++) heights.push(p.climb * (k / (n - 1)) + (1 - p.climb) * T.rand());
  for (let k = 0; k < n; k++) {
    const h = heights[k];
    const f = p.pitch * Math.pow(2, scale[Math.round(h * 7)] / 12);
    const at = t + k * p.gap;
    const lv = 0.7 + 0.3 * h;   // taller bars hit a touch harder
    // marimba bars ring at about 1, 3.9 and 9.2 times the note
    T.bell(out, at, { f, partials: [[1, 1, 1], [3.9, 0.3, 0.35], [9.2, 0.08, 0.15]], dur: 0.14, peak: 0.034 * lv, a: 0.002 });
    T.noise(out, at, { filter: 'bandpass', f: 2200, q: 1.5, dur: 0.01, peak: 0.05 * lv, a: 0.002 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.ticks);
  // the gap before each tick: wide at the start, tightest mid-run, wide again as it brakes
  const gaps = [];
  let sum = 0;
  for (let k = 0; k < n; k++) {
    const g = 1 + 3 * Math.pow(1 - Math.sin((Math.PI * (k + 0.5)) / n), 1.5);
    gaps.push(g);
    sum += g;
  }
  let at = t;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, (p.rise * k) / (Math.max(1, n - 1) * 12));
    T.tick(out, at, {
      f: f * 2.4, q: 2.2, dur: 0.012, peak: 0.09, blip: f, blipTo: f * 0.88, blipPeak: 0.03, blipDur: 0.022, jitter: 0.5, lp: 7000,
    });
    at += (gaps[k] * p.length) / sum;
  }
  // the landing: the last gap is the slowest, then a round low thunk with a muffled tap
  T.osc(out, at, { f: 140, to: 78, dur: 0.15, peak: 0.11 * p.thunk, a: 0.004 });
  T.noise(out, at, { filter: 'lowpass', f: 520, dur: 0.05, peak: 0.12 * p.thunk, a: 0.003 });
}

function (T, out, t, p) {
  const f = p.pitch * Math.pow(2, p.value);
  const m = p.click;
  // glass: a small bell that rings for a few milliseconds
  T.bell(out, t, { f, partials: [[1, 1, 1], [2.76, 0.4, 0.45], [5.4, 0.12, 0.25]], dur: 0.06, peak: 0.032 * Math.cos(m * Math.PI / 2), a: 0.001 });
  // mechanical: a band-passed snap that follows the note, over a short low knock; a narrow band
  // passes more noise the higher it sits, so the snap is trimmed as the note climbs
  T.tick(out, t, { f: f * 2.2, q: 2.2, dur: 0.011, peak: 0.12 * Math.sin(m * Math.PI / 2) * Math.sqrt(1100 / f), blip: f * 0.45, blipTo: f * 0.35, blipPeak: 0.03 * Math.sin(m * Math.PI / 2), blipDur: 0.03, jitter: 0.3 });
}

function (T, out, t, p) {
  const up = p.up >= 0.5;
  const hi = p.pitch * Math.pow(2, (2 + 10 * p.size) / 12);
  const lo = p.pitch;
  const level = up ? 1 : 0.85;
  const a = up ? lo : hi;
  const b = up ? hi : lo;
  const dir = up ? 1 : -1;
  T.osc(out, t, { type: 'triangle', f: a, to: a * (1 + 0.04 * dir), dur: 0.05, peak: 0.04 * level, a: 0.003 });
  T.osc(out, t + 0.045, { type: 'triangle', f: b, to: b * (1 + 0.06 * dir), dur: 0.08, peak: 0.046 * level, a: 0.003 });
  T.noise(out, t, { filter: 'highpass', f: 4500, q: 0.7, dur: 0.008, peak: 0.008, a: 0.002 });
}

function (T, out, t, p) {
  // node down: a falling blip with a thud of noise under it, kept dark on purpose
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.5, glide: 0.1, dur: 0.12, peak: 0.06, a: 0.004, lp: p.pitch * 1.6 });
  T.tick(out, t, { f: 900, q: 0.9, lp: 1800, dur: 0.02, peak: 0.05 });
  // standby online: root, major third, fifth, each a little louder, the last one rings
  const start = t + 0.12 + p.gap;
  const steps = [0, 4, 7];
  for (let k = 0; k < 3; k++) {
    const at = start + k * 0.07;
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    const last = k === 2;
    T.osc(out, at, { f, dur: last ? 0.36 : 0.09, peak: 0.03 + 0.012 * k, a: 0.005 });
    T.osc(out, at, { type: 'triangle', f: f * 2, dur: last ? 0.2 : 0.06, peak: 0.01 + 0.004 * k, a: 0.005 });
  }
  T.bell(out, start + 0.14, { f: p.pitch * 3, partials: [[1, 1, 1], [2.4, 0.3, 0.5]], dur: 0.36, peak: 0.03 * p.bright, a: 0.004 });
}

function (T, out, t, p) {
  const n = Math.round(p.branches);
  const ladder = [4, 7, 9, 12, 14, 16];
  const drift = T.jitter(1, { cents: 12 });
  T.osc(out, t, { f: p.pitch * drift, dur: 0.08, peak: 0.034, a: 0.004 });
  const start = t + 0.075;
  for (let k = 0; k < n; k++) {
    const at = start + k * p.stagger;
    const x = n > 1 ? p.spread * (-1 + (2 * k) / (n - 1)) : 0;
    const g = T.pan(out, at, { x });
    const f = p.pitch * drift * Math.pow(2, ladder[k] / 12);
    T.osc(g, at, { f, dur: 0.09, peak: 0.028, a: 0.004 });
    T.osc(g, at, { f: f * 2, dur: 0.04, peak: 0.007, a: 0.004 });
  }
}

function (T, out, t, p) {
  const dist = Math.abs(p.sweep);
  const dir = p.sweep >= 0 ? 1 : -1;
  const len = 0.12 + 0.3 * dist;
  const f0 = p.pitch;
  const f1 = f0 * Math.pow(2, dir * (0.15 + 0.85 * dist));
  // the move: a buzzy whir and a band of gear noise riding the same pitch
  T.osc(out, t, {
    type: 'sawtooth', f: f0, to: f1, dur: len, peak: 0.03, a: 0.015, s: 1, d: 0.01, r: 0.04, glide: len * 0.9,
    lp: { f: f0 * 3, to: f1 * 3, q: 1.2 },
  });
  T.noise(out, t, { filter: 'bandpass', f: f0 * 5, to: f1 * 5, q: 3, dur: len, peak: 0.06, a: 0.015, s: 1, d: 0.01, r: 0.04 });
  // the spring: each bounce overshoots the reading by less, alternating sides
  const bounce = [1, -0.55, 0.25];
  let from = f1;
  for (let k = 0; k < 3; k++) {
    const to = f1 * (1 + 0.2 * p.swing * bounce[k]);
    T.osc(out, t + len * 0.95 + k * 0.055, { type: 'triangle', f: from, to, dur: 0.07, peak: 0.032 * p.swing * (1 - 0.25 * k), a: 0.004 });
    from = to;
  }
  // the detent: a small dry tick once everything has settled
  T.tick(out, t + len * 0.95 + 0.17, { f: 2600, q: 3, dur: 0.01, peak: 0.07, blip: f1 * 2, blipDur: 0.025, blipPeak: 0.016 });
}

function (T, out, t, p) {
  const n = Math.round(p.cells);
  const span = p.bloom;
  const steps = [0, 2, 4, 7, 9, 12, 14, 16, 19];
  // the grains are drawn first so the cluster's pattern never depends on the swell's settings
  const grains = [];
  const grainPeak = 0.016 * Math.sqrt(16 / n);   // a denser cluster gets quieter grains, so it blooms rather than gets louder
  for (let k = 0; k < n; k++) {
    const u = (T.rand() + T.rand()) / 2;     // 0..1, most grains near the middle
    const idx = Math.floor(T.rand() * (1 + 8 * p.spread));
    grains.push({ u, f: p.warmth * 2 * Math.pow(2, steps[Math.min(8, idx)] / 12) });
  }
  // the swell under the grains: noise opening upward, plus a root and a fifth
  T.noise(out, t, { filter: 'bandpass', f: p.warmth * 2, to: p.warmth * 4, q: 0.9, dur: span + 0.2, a: span * 0.5, peak: 0.055 });
  T.osc(out, t, { f: p.warmth, dur: span + 0.2, peak: 0.012, a: span * 0.5 });
  T.osc(out, t, { f: p.warmth * 1.5, dur: span + 0.2, peak: 0.007, a: span * 0.5 });
  for (const g of grains) {
    const lv = 1 - Math.abs(g.u - 0.5) * 1.2;  // the busiest part of the bloom is the loudest
    T.osc(out, t + g.u * span, { f: g.f, dur: 0.08, peak: grainPeak * lv, a: 0.003 });
  }
}

function (T, out, t, p) {
  const len = p.length;
  const end = p.pitch * Math.pow(2, p.curve);
  T.osc(out, t, {
    f: p.pitch, to: end, dur: len, peak: 0.04, a: 0.04, s: 0.9, d: 0.06, r: 0.05, glide: len * 0.95,
    vib: { rate: 1.5 / len, depth: 300 * p.wobble },
  });
  // the arrival: fold the end note up into a bright octave and let two detuned sines beat on it
  let top = end * 2;
  while (top < 900) top *= 2;
  while (top > 2500) top /= 2;
  const at = t + len * 0.93;
  T.osc(out, at, { f: top, dur: 0.28, peak: 0.016 * p.shimmer, a: 0.008 });
  T.osc(out, at, { f: top * 1.007, dur: 0.28, peak: 0.016 * p.shimmer, a: 0.008 });
  T.osc(out, at, { f: top * 2.01, dur: 0.18, peak: 0.008 * p.shimmer, a: 0.008 });
}

function (T, out, t, p) {
  const up = p.on >= 0.5;
  const first = up ? p.pitch : p.pitch * 1.5;
  const second = up ? p.pitch * 1.5 : p.pitch;
  const blip = (at, f) => {
    T.osc(out, at, { f, dur: 0.07, peak: 0.036, a: 0.004 });
    T.osc(out, at, { f: f * 2, dur: 0.04, peak: 0.012 * p.tone, a: 0.004 });
  };
  blip(t, first);
  blip(t + p.speed, second);
  const at = t + 2 * p.speed + 0.01;
  if (up) {
    // the settle: it leans up into the octave and rings a moment, a fifth overtone for body
    T.osc(out, at, { f: p.pitch * 1.92, to: p.pitch * 2, glide: 0.07, dur: 0.32, peak: 0.038, a: 0.008 });
    T.osc(out, at, { f: p.pitch * 3, dur: 0.16, peak: 0.01 + 0.008 * p.tone, a: 0.008 });
  } else {
    // the drop: a sine falling an octave and a half while it fades, with no overtone to keep it dull
    T.osc(out, at, { f: p.pitch, to: p.pitch * 0.35, glide: 0.3, dur: 0.32, peak: 0.04, a: 0.01, lp: p.pitch * 1.4 });
  }
}

function (T, out, t, p) {
  const len = p.length;
  const ratio = Math.pow(2, 2 * p.fill);     // end pitch over start pitch
  // the pour: noise narrowed around the climbing resonance, and the resonance itself
  T.noise(out, t, { filter: 'bandpass', f: p.pitch * 2, to: p.pitch * 2 * ratio, q: 4, dur: len + 0.04, peak: 0.12, a: 0.04, s: 1, d: 0.01, r: 0.06 });
  T.osc(out, t, { f: p.pitch, to: p.pitch * ratio, dur: len + 0.04, peak: 0.011, a: 0.05, s: 1, d: 0.01, r: 0.06, glide: len });
  // the glugs, closer together as the level rises
  const n = Math.round(p.glug);
  for (let k = 0; k < n; k++) {
    const x = k / n;
    const rel = 0.9 * (1 - Math.pow(1 - x, 1.4));
    const f = p.pitch * Math.pow(ratio, rel) * T.rand(0.92, 1.08);
    T.osc(out, t + len * rel, { f, to: f * 1.5, dur: 0.07, peak: 0.018, a: 0.004 });
    T.osc(out, t + len * rel, { f: f * 2, to: f * 3, dur: 0.05, peak: 0.004, a: 0.004 });
  }
}

function (T, out, t, p) {
  const sw = p.sweep;
  const at = t + sw;
  // the fill: a sine climbing an octave and swelling all the way to the landing, with a band of
  // air opening beside it; the sine rings on a moment under the landing so the two join
  T.osc(out, t, { f: p.pitch * 0.5, to: p.pitch, glide: sw, dur: sw + 0.12, peak: 0.022, a: sw });
  T.noise(out, t, { filter: 'bandpass', f: p.pitch * 2, to: p.pitch * 6, q: 0.9, dur: sw + 0.01, peak: 0.02, a: sw - 0.005 });
  // the settle: a soft low knock that always lands (the skeleton filling in)
  T.osc(out, at, { f: p.pitch * 0.5, to: p.pitch * 0.4, dur: 0.12, peak: 0.026, a: 0.005 });
  T.noise(out, at, { filter: 'lowpass', f: 900, dur: 0.05, peak: 0.05, a: 0.004 });
  // the check: a glassy ping and a tiny tick, scaled by `check`
  T.bell(out, at, { f: p.pitch * 2, partials: [[1, 1, 1], [3, 0.18, 0.4]], dur: 0.24, peak: 0.012 + 0.04 * p.check, a: 0.003 });
  T.tick(out, at, { f: 5200, q: 2, dur: 0.008, peak: 0.01 + 0.035 * p.check });
}

function (T, out, t, p) {
  const L = p.breath;
  const f = T.jitter(p.pitch, { cents: 8 });
  // the arc: a gain at rest on 0 that half a sine period lifts to 1 and back, so the breath rises
  // and falls with no corner and ends exactly at silence
  const arc = T.gain(out, 0);
  T.lfo(arc, t, { param: 'gain', rate: 1 / (2 * L), depth: 1, dur: L, a: 0.005 });
  const vib = { rate: 3.2, depth: 4 + 26 * p.wobble };
  T.osc(arc, t, { f, dur: L, peak: 0.022, a: 0.01, s: 1, d: 0.01, r: 0.03, vib });
  T.osc(arc, t, { f: f * 1.5, dur: L, peak: 0.011, a: 0.01, s: 1, d: 0.01, r: 0.03, vib: { rate: 2.6, depth: 6 + 20 * p.wobble } });
  T.osc(arc, t, { type: 'triangle', f: f * 2, dur: L, peak: 0.009 * p.tone, a: 0.01, s: 1, d: 0.01, r: 0.03 });
  T.noise(arc, t, { filter: 'bandpass', f: 2200, q: 0.7, dur: L, peak: 0.012 * p.tone, a: 0.01, s: 1, d: 0.01, r: 0.03 });
}

function (T, out, t, p) {
  const lvl = Math.round(p.level);
  const base = [330, 440, 587, 784][lvl];
  const peak = [0.032, 0.037, 0.03, 0.053][lvl];
  const notes = [1, 1.125, 1.25, 1.5];
  const n = Math.round(p.lines);
  const blip = (f, at) => {
    if (lvl === 3) T.pulse(out, at, { duty: 0.25, f, dur: 0.02, peak, a: 0.002 });
    else T.osc(out, at, { type: 'triangle', f, dur: 0.02, peak, a: 0.002 });
    // warn: a partner a quarter tone sharp, so the blip wavers
    if (lvl === 2) T.osc(out, at, { type: 'triangle', f: f * 1.03, dur: 0.02, peak: peak * 0.5, a: 0.002 });
  };
  for (let k = 0; k < n; k++) {
    const start = t + k * p.pace + T.rand(0, 0.01);
    const chars = 3 + Math.floor(T.rand() * 2);
    for (let c = 0; c < chars; c++) {
      blip(base * notes[Math.floor(T.rand() * notes.length)], start + c * 0.022);
    }
    // the return at the end of the line: a dry tick a fifth below
    T.tick(out, start + chars * 0.022 + 0.015, { f: 2400, q: 3, dur: 0.008, peak: 0.03, blip: base * 0.667, blipDur: 0.02, blipPeak: peak * 0.7 });
  }
}

function (T, out, t, p) {
  const rise = 0.004 + 0.02 * p.soft;
  const fall = 0.02 + 0.03 * p.soft;
  T.osc(out, t, { f: p.pitch, dur: p.length, peak: 0.042, a: rise, s: 1, d: 0.005, r: fall });
  T.osc(out, t, { f: p.pitch * 2, dur: p.length, peak: 0.01 * (1 - p.soft), a: rise, s: 1, d: 0.005, r: fall });
  // lub, then a softer dub
  T.osc(out, t, { f: 90, to: 65, dur: 0.07, peak: 0.026 * p.thump, a: 0.006 });
  T.osc(out, t + 0.11, { f: 80, to: 58, dur: 0.07, peak: 0.018 * p.thump, a: 0.006 });
}

function (T, out, t, p) {
  // the strike
  T.osc(out, t, { f: 2600 + 1200 * p.snap, to: 2100, dur: 0.04, peak: 0.012 + 0.025 * p.snap, a: 0.001 });
  T.noise(out, t, { filter: 'highpass', f: 3500, q: 0.7, dur: 0.02, peak: 0.012 + 0.055 * p.snap, a: 0.001 });
  T.crackle(out, t + 0.004, { dur: 0.07, rate: 150, f: 5200, to: 3000, spread: 0.3, q: 1.5, len: 0.003, peak: 0.006 + 0.03 * p.snap });
  // the glow: a warm hum that fades in under the strike, on a soft lowpass
  const warm = T.filter(out, t, { type: 'lowpass', f: 650, q: 0.8, dur: 0.05 });
  const end = p.glow;
  T.osc(warm, t + 0.01, { type: 'sawtooth', f: p.pitch, dur: end, peak: 0.055 * p.hum, a: 0.025, tail: 0.12, fade: 0.06 });
  T.osc(out, t + 0.01, { type: 'triangle', f: p.pitch * 2, dur: end, peak: 0.016 * p.hum, a: 0.03, tail: 0.1, fade: 0.06 });
}

function (T, out, t, p) {
  const n = Math.round(p.hops);
  const gap = 0.055;
  const steps = [0, 2, 4, 7, 9];
  // one seeded drift for the whole packet, so the tenth packet is not a copy of the first
  const drift = T.jitter(1, { cents: 14 });
  const hopPitch = (k) => p.pitch * drift * Math.pow(2, steps[k] / 12);
  const place = (k) => p.travel * (-1 + (2 * k) / n);
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const g = T.pan(out, at, { x: place(k), to: place(k + 1), dur: gap });
    const f = hopPitch(k);
    T.osc(g, at, { f, dur: 0.075, peak: 0.03, a: 0.004 });
    T.osc(g, at, { f: f * 2, dur: 0.04, peak: 0.012 * p.tone, a: 0.004 });
  }
  // the landing: an octave under the last hop, a hair of noise on top
  const land = t + n * gap;
  const f = hopPitch(n - 1) / 2;
  const g = T.pan(out, land, { x: place(n) });
  T.tick(g, land, { f: 2800, q: 1, lp: 4500, dur: 0.012, peak: 0.05, blip: f, blipTo: f * 0.9, blipPeak: 0.03, blipDur: 0.06, jitter: 0.5 });
}

function (T, out, t, p) {
  // the fall: a falling whistle that swells as the pin speeds up, with air around it (the noise is
  // kept low because a narrow band of it spikes well above its average level)
  T.noise(out, t, { filter: 'bandpass', f: 3200, to: 800, q: 1.5, dur: p.height + 0.01, peak: 0.12, a: p.height * 0.9 });
  T.osc(out, t, { f: 1200, to: 380, dur: p.height + 0.01, peak: 0.026, a: p.height * 0.9 });
  const land = t + p.height;
  // the landing: a low tap, a tick of noise, then the tink
  T.osc(out, land, { f: 280, to: 150, dur: 0.07, peak: 0.03, a: 0.003 });
  T.tick(out, land, { f: 1800, q: 1.2, dur: 0.01, peak: 0.026 });
  const ring = 0.1 + 0.1 * p.glint;
  T.bell(out, land, { f: p.pitch, partials: [[1, 1, 1], [2.32, 0.35 * p.glint, 0.5], [4.1, 0.14 * p.glint, 0.3]], dur: ring, peak: 0.03, a: 0.002 });
  // the bounce: a smaller tap and a higher, shorter tink
  if (p.bounce > 0.02) {
    const hop = land + 0.09;
    T.osc(out, hop, { f: 300, to: 190, dur: 0.045, peak: 0.03 * p.bounce, a: 0.003 });
    T.bell(out, hop, { f: p.pitch * 1.12, partials: [[1, 1, 1], [2.32, 0.3 * p.glint, 0.5]], dur: 0.1, peak: 0.032 * p.bounce, a: 0.002 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.ticks);
  const at = (q) => p.pitch * Math.pow(2, (p.span * q) / 12);
  const q = n > 0 ? Math.round(p.pos * n) / n : p.pos;
  const f = at(q);
  // start on the stair below (or 1.5 semitones under when smooth) so each call arrives from below
  const from = n > 0 ? at(Math.max(0, q - 1 / n)) : f * Math.pow(2, -1.5 / 12);
  const lead = from < f ? from : f * 0.97;
  T.osc(out, t, { f: lead, to: f, glide: 0.06, dur: 0.17, peak: 0.036, a: 0.008, tail: 0.1, fade: 0.06 });
  T.osc(out, t, { type: 'triangle', f: f * 2, dur: 0.12, peak: 0.007, a: 0.008, tail: 0.1, fade: 0.05 });
  if (n > 0) T.tick(out, t, { f: f * 3, q: 2, dur: 0.01, peak: 0.02, lp: 5000 });
}

function (T, out, t, p) {
  const drift = T.jitter(1, { cents: 10 });
  const f = p.pitch * drift;
  // out: a tick and a quick upward blip, moving from the left to the right
  const go = T.pan(out, t, { x: -p.width, to: p.width, dur: 0.08 });
  T.osc(go, t, { f, to: f * 1.5, glide: 0.05, dur: 0.07, peak: 0.034, a: 0.004 });
  T.tick(go, t, { f: 2600, q: 1, lp: 4500, dur: 0.01, peak: 0.03 });
  // back: a fifth, then the octave, a little warmer and louder than the request, moving right to left
  const at = t + 0.08 + p.latency;
  const back = T.pan(out, at, { x: p.width, to: -p.width, dur: 0.12 });
  T.osc(back, at, { f: f * 1.5, dur: 0.14, peak: 0.04, a: 0.006 });
  T.osc(back, at + 0.07, { f: f * 2, dur: 0.26, peak: 0.046, a: 0.006 });
  T.osc(back, at + 0.07, { f: f * 4.02, dur: 0.1, peak: 0.01, a: 0.006 });
}

function (T, out, t, p) {
  const n = Math.round(p.waypoints);
  const legs = n + 1;
  const leg = p.length / legs;
  const ladder = [0, 2, 4, 7, 9, 12];
  // waypoint k sits k / legs of the way up the ladder; the last note is the octave
  const note = (k) => ladder[Math.round((5 * k) / legs)];
  const hz = (k) => p.pitch * Math.pow(2, note(k) / 12);
  const travel = T.pan(out, t, { x: -p.width, to: p.width, dur: p.length });
  for (let k = 0; k < legs; k++) {
    const at = t + k * leg;
    // each leg overlaps the next by 30 ms, so the hop is a re-attack rather than a gap
    T.osc(travel, at, { f: hz(k), to: hz(k + 1), glide: leg * 0.85, dur: leg + 0.03, peak: 0.028, a: 0.015, s: 1, d: 0.002, r: 0.03 });
  }
  for (let k = 1; k <= n; k++) {
    const at = t + k * leg;
    const g = T.pan(out, at, { x: -p.width + (2 * p.width * k) / legs });
    T.bell(g, at, { f: hz(k) * 2, partials: [[1, 1, 1], [2.76, 0.3, 0.4]], dur: 0.1, peak: 0.032, a: 0.002 });
    T.tick(g, at, { f: 3500, q: 1.2, lp: 6000, dur: 0.008, peak: 0.03 });
  }
  // arrival: centred, an octave over the glide's last note, with a soft overtone and a low note under it
  const end = t + p.length + 0.02;
  T.bell(out, end, { f: p.pitch * 4, partials: [[1, 1, 1], [2.01, 0.3, 0.55], [3, 0.12, 0.4]], dur: 0.55, peak: 0.038, a: 0.004 });
  T.osc(out, end, { f: p.pitch * 2, dur: 0.3, peak: 0.016, a: 0.006 });
}

function (T, out, t, p) {
  const n = Math.round(p.count);
  const up = p.up >= 0.5;
  const ladder = [0, 2, 4, 7, 9, 12];
  // more blips would add up louder, so each one gets a smaller share
  const peak = 0.05 / Math.sqrt(n);
  const end = t + n * p.speed + 0.3;
  for (let k = 0; k < n; k++) {
    const at = t + k * p.speed;
    const f = p.pitch * Math.pow(2, ladder[up ? k : n - 1 - k] / 12);
    if (up) {
      // every blip rings until the common end, so the run stacks into a chord
      T.osc(out, at, { f, dur: end - at, peak, a: 0.006 });
      T.osc(out, at, { f: f * 2, dur: 0.06, peak: 0.01, a: 0.006 });
    } else {
      // short and dry, with the top of the sound rolled off, each one gone before the next
      T.osc(out, at, { f, dur: 0.1, peak: peak * 1.1, a: 0.005, lp: f * 1.5 });
    }
  }
}

function (T, out, t, p) {
  const n = Math.round(p.echoes);
  // the ping leans up into its pitch over 40 ms, which is what makes it read as a ping
  T.osc(out, t, { f: p.pitch * 0.94, to: p.pitch, glide: 0.04, dur: 0.45, peak: 0.05, a: 0.006 });
  T.osc(out, t, { f: p.pitch * 2.01, dur: 0.2, peak: 0.016 * p.bright, a: 0.006 });
  T.osc(out, t, { f: p.pitch * 3.02, dur: 0.1, peak: 0.007 * p.bright, a: 0.006 });
  for (let k = 1; k <= n; k++) {
    const at = t + k * p.gap;
    const lv = Math.pow(0.5, k);
    // each echo has lost some of its highs and a little pitch on the way back
    T.osc(out, at, { f: p.pitch * (1 - 0.012 * k), dur: 0.34, peak: 0.05 * lv, a: 0.012 + 0.008 * k, lp: p.pitch * (2.2 - 0.4 * k) });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.swaps);
  const scale = [0, 2, 4, 7, 9];
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const lo = p.pitch * Math.pow(2, scale[k % 5] / 12);
    const hi = lo * 1.26;
    // the two rows cross: one rises to the upper place, the other falls to the lower
    T.osc(out, at, { f: lo, to: hi, dur: 0.07, peak: 0.028, a: 0.004 });
    T.osc(out, at, { f: hi, to: lo, dur: 0.07, peak: 0.022, a: 0.004 });
    T.noise(out, at, { filter: 'bandpass', f: 1200, to: 2600, q: 1.2, dur: 0.07, peak: 0.045 * p.slide, a: 0.01 });
    // set off, then land (the second row a hair behind the first)
    T.tick(out, at, { f: 2800, q: 2.5, dur: 0.008, peak: 0.04, jitter: 0.5 });
    T.tick(out, at + 0.07, { f: 3200, q: 2.5, dur: 0.008, peak: 0.05, blip: hi, blipDur: 0.025, blipPeak: 0.022, jitter: 0.5 });
    T.tick(out, at + 0.082, { f: 2400, q: 2.5, dur: 0.008, peak: 0.04, blip: lo, blipDur: 0.025, blipPeak: 0.018, jitter: 0.5 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.steps);
  const gap = p.turn / n;
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const ang = (2 * Math.PI * k) / n;
    const top = (1 + Math.cos(ang)) / 2;
    const f = T.jitter(p.pitch * Math.pow(2, (5 * top) / 12), { cents: 6 });
    const lv = k === 0 ? 1 : 0.78;
    const spot = T.pan(out, at, { x: p.width * Math.sin(ang) });
    T.osc(spot, at, { f, to: f * 0.88, glide: 0.03, dur: 0.045, peak: 0.032 * lv, a: 0.004 });
    T.osc(spot, at, { f: f * 2, dur: 0.02, peak: 0.006 * lv, a: 0.003 });
    T.tick(spot, at, { f: 2600, q: 1.2, dur: 0.012, peak: (0.004 + 0.026 * p.tone) * lv, lp: 4200 });
  }
}

function (T, out, t, p) {
  const nd = Math.round(p.digits);
  const nc = Math.round(p.cards);
  const sp = p.speed;
  const lag = sp * 1.3;
  const lv = 0.1 / Math.sqrt(1 + 0.45 * (nd - 1));
  const band = 1700 + 2300 * p.tone;
  for (let d = 0; d < nd; d++) {
    const start = t + d * lag + T.rand(0, 0.3) * sp;
    for (let c = 0; c < nc; c++) {
      const at = start + c * sp + T.rand(0, 0.15) * sp;
      if (c < nc - 1) {
        T.tick(out, at, { f: band, q: 1.3, dur: 0.009, peak: lv, blip: 190, blipTo: 140, blipPeak: lv * 0.3, blipDur: 0.018, jitter: 0.8 });
      } else {
        // the last card lands flat: lower, rounder and a little louder
        T.tick(out, at, { f: band * 0.6, q: 1, dur: 0.014, peak: lv * 1.4, blip: 130, blipTo: 85, blipPeak: lv * 0.7, blipDur: 0.04, jitter: 0.4 });
      }
    }
  }
}

function (T, out, t, p) {
  const lv = p.level;
  const iv = lv <= 0.5 ? 7 * (1 - lv * 2) : -6 * (lv * 2 - 1);   // semitones from the first pip to the second
  const edge = Math.max(0, (lv - 0.45) / 0.55);                  // 0 through green and amber, 1 at red
  const body = (0.034 + 0.032 * lv) * (p.rising >= 0.5 ? 1 : 0.8);
  const fa = p.pitch;
  const fb = p.pitch * Math.pow(2, iv / 12);
  const pip = (f, at, len) => {
    T.osc(out, at, { type: 'triangle', f, dur: len, peak: body, a: 0.004 });
    // red: a squarer, tremolo-roughened layer on the same note
    T.osc(out, at, { type: 'square', f, dur: len, peak: 0.028 * edge, a: 0.004, lp: 1800, trem: { rate: 30, depth: 0.6 * edge } });
  };
  const first = p.rising >= 0.5 ? fa : fb;
  const second = p.rising >= 0.5 ? fb : fa;
  pip(first, t, 0.07);
  pip(second, t + 0.085, 0.17);
}

function (T, out, t, p) {
  const L = p.length;
  const f = p.pitch;
  const start = Math.pow(2, 1 + 1.5 * p.grain);   // where the static begins, as a multiple of the pitch
  const qs = [0.7, 2, 6, 18, 55];
  for (let k = 0; k < 5; k++) {
    const hi = f * Math.pow(start, 1 - k / 5);
    const lo = f * Math.pow(start, 1 - (k + 1) / 5);
    const fc = Math.sqrt(hi * lo);
    T.noise(out, t + k * L * 0.14, {
      filter: 'bandpass', f: hi, to: lo, q: qs[k], dur: L * 0.44,
      peak: 1.8 * Math.sqrt(qs[k] / fc), a: L * 0.2, s: 1, d: 0.02, r: L * 0.2,
    });
  }
  // the clean tone grows out of the narrowest layer and rings on after the static is gone
  T.osc(out, t + L * 0.45, { f, dur: L * 0.55 + 0.3, peak: 0.045, a: L * 0.4, s: 1, d: 0.02, r: 0.3, tail: 0.1, fade: 0.1 });
  T.osc(out, t + L * 0.75, { f: f * 2, dur: L * 0.25 + 0.3, peak: 0.01, a: L * 0.2, s: 1, d: 0.02, r: 0.3, tail: 0.1, fade: 0.1 });
}

function (T, out, t, p) {
  if (Math.round(p.pass) === 1) {
    T.bell(out, t, { f: p.pitch, partials: [[1, 1, 1], [2, 0.12 + 0.3 * p.edge, 0.5], [3, 0.08, 0.3]], dur: 0.3, peak: 0.055, a: 0.003 });
  } else {
    const f = p.pitch * 0.17;
    // the thud: a sine falling an octave with a muffled knock on top
    T.osc(out, t, { f, to: f * 0.5, glide: 0.1, dur: 0.18, peak: 0.085, a: 0.003 });
    T.noise(out, t, { filter: 'lowpass', f: 600, q: 0.7, dur: 0.05, peak: 0.25, a: 0.002 });
    // the buzz: two close saws through a lowpass with a fast level flutter
    const lp = T.filter(out, t, { type: 'lowpass', f: 700, q: 0.8 });
    const buzz = { type: 'sawtooth', dur: 0.22, peak: 0.045, a: 0.01, s: 0.7, d: 0.03, r: 0.08, trem: { rate: 30, depth: 0.2 + 0.6 * p.edge } };
    T.osc(lp, t + 0.03, Object.assign({ f: f * 0.8 }, buzz));
    T.osc(lp, t + 0.03, Object.assign({ f: f * 0.83 }, buzz));
  }
}

function (T, out, t, p) {
  const L = p.travel;
  const dir = Math.round(p.direction) === 1 ? -1 : 1;
  const pan = T.pan(out, t, { x: -0.85 * dir, to: 0.85 * dir, dur: L + 0.15 });
  const hi = p.pitch * 1.5;
  // the first agent's voice climbs and fades while the second one fades in on the same note
  T.osc(pan, t, { type: 'triangle', f: p.pitch, to: hi, glide: L * 0.8, dur: L, peak: 0.048, a: 0.025, s: 1, d: 0.02, r: L * 0.45, tail: 0.05, fade: 0.1, lp: 1800 });
  T.fm(pan, t + L * 0.5, { f: hi, ratio: 2, index: 0.4 + 1.6 * p.change, index1: 0, dur: 0.5, peak: 0.052, a: 0.05 });
  T.osc(pan, t + L * 0.5, { f: hi * 2, dur: 0.3, peak: 0.016 * p.change, a: 0.05 });
}

function (T, out, t, p) {
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  const k = Math.min(7, Math.max(0, Math.round(p.step) - 1));
  const f = p.pitch * Math.pow(2, scale[k] / 12);
  const from = k === 0 ? f * 0.89 : p.pitch * Math.pow(2, scale[k - 1] / 12);
  T.osc(out, t, { f: from, to: f, glide: 0.05, dur: 0.3, peak: 0.055, a: 0.006 });
  T.osc(out, t, { f: from * 2, to: f * 2, glide: 0.05, dur: 0.14, peak: 0.012, a: 0.006 });
  // two echoes of the settled note, each softer than the last
  T.osc(out, t + 0.12, { f, dur: 0.22, peak: 0.055 * 0.7 * p.glow, a: 0.006 });
  T.osc(out, t + 0.24, { f, dur: 0.2, peak: 0.055 * 0.35 * p.glow, a: 0.006 });
}

function (T, out, t, p) {
  const n = Math.round(p.glints);
  const span = p.sweep;
  // semitones below the ping: a major pentatonic ladder, so the glints always agree with it
  const below = [0, -3, -5, -8, -10, -12, -15, -17];
  const room = T.reverb(out, t, { time: 0.4, mix: 0.2, tone: 0.8 });
  for (let k = 0; k < n; k++) {
    const u = k / n;
    const at = t + span * (1 - Math.pow(1 - u, 1.6));   // the gaps shrink as the glints climb
    const i = Math.max(1, Math.min(7, Math.round((1 - u) * 7 + T.rand(-1, 1))));
    const f = p.pitch * Math.pow(2, below[i] / 12);
    T.fm(out, at, { f, ratio: 3, index: 0.6, index1: 0, dur: 0.06, peak: 0.027 + 0.018 * u, a: 0.003 });
  }
  T.bell(room, t + span + 0.05, { f: p.pitch, partials: [[1, 1, 1], [2, 0.3, 0.55], [3, 0.1, 0.3]], dur: 0.42, peak: 0.047, a: 0.003 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.5, mix: 0.3 * p.glow, tone: 0.75 });
  // the cursor stops: a low little tock, a sine dropping a fifth
  T.osc(out, t, { f: p.pitch * 0.6, to: p.pitch * 0.4, glide: 0.03, dur: 0.05, peak: 0.04 * p.cursor, a: 0.003 });
  const partials = [[1, 1, 1], [2, 0.2 + 0.15 * p.glow, 0.5], [3, 0.07, 0.3]];
  const lo = p.pitch * Math.pow(2, -Math.round(p.fall) / 12);
  T.bell(room, t + 0.08, { f: p.pitch, partials, dur: 0.4, peak: 0.06, a: 0.004 });
  T.bell(room, t + 0.23, { f: lo, partials, dur: 0.55, peak: 0.065, a: 0.004 });
}

function (T, out, t, p) {
  // a few cents of pitch change per trigger so a long wait does not sound stamped
  const f = T.jitter(p.pitch, { cents: 6 });
  const swell = 0.18 + 0.32 * p.depth;   // time to the top of the breath
  const len = 1.22;                       // the cell is silent from here to the next trigger
  const shape = { a: swell, s: 1, d: 0.05, r: 0.62, dur: len, tail: 0.1, fade: 0.2 };
  const open = f * (2 + 4 * p.tone);
  const lp = T.filter(out, t, { type: 'lowpass', f: open, to: open * (1 + 1.6 * p.depth), dur: swell, q: 0.6 });
  const voice = (type, ratio, peak) => T.osc(lp, t, Object.assign({ type, f: f * ratio, peak }, shape));
  voice('triangle', 1, 0.0155);
  voice('triangle', 1.0035, 0.011);
  voice('sine', 1.5, 0.0078);
  voice('sine', 2, 0.0055);
}

function (T, out, t, p) {
  const n = Math.round(p.tokens);
  const span = n / p.rate;
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  const top = Math.round(p.spread * 7);
  // every token draws the same four values, so changing a setting never reshuffles the rest
  const weight = [];
  const idx = [];
  const cents = [];
  const lvl = [];
  let sum = 0;
  let at = Math.min(top, 2);
  for (let k = 0; k < n; k++) {
    const r = T.rand();
    const u = T.rand();
    const walk = T.rand();
    const v = T.rand();
    // most tokens keep an even pace, some arrive in a quick pair, some after a short pause
    const w = r < 0.18 ? 0.35 : r > 0.84 ? 1.9 : 0.75 + 0.5 * u;
    weight.push(w);
    sum += w;
    at = Math.max(0, Math.min(top, at + (walk < 0.3 ? -1 : walk > 0.7 ? 1 : 0)));
    idx.push(at);
    cents.push((u - 0.5) * 24);
    lvl.push(0.75 + 0.25 * v);
  }
  let when = 0;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, scale[idx[k]] / 12 + cents[k] / 1200);
    T.fm(out, t + when, { f, ratio: 3, index: 0.55, index1: 0, dur: 0.04, peak: 0.042 * lvl[k], a: 0.002 });
    when += (weight[k] / sum) * span;
  }
}

function (T, out, t, p) {
  const lat = p.latency;
  const at = t + 0.07 + lat;
  // the request leaves
  T.osc(out, t, { f: p.pitch * 0.7, to: p.pitch * 1.05, glide: 0.02, dur: 0.045, peak: 0.028, a: 0.003 });
  // the wait: a faint thread of tone climbing toward the answer
  T.osc(out, t + 0.07, { f: p.pitch * 0.5, to: p.pitch * 0.96, glide: lat, dur: lat, peak: 0.011, a: Math.min(0.03, lat * 0.4), s: 1, d: 0.01, r: 0.03 });
  if (Math.round(p.ok) === 1) {
    T.bell(out, at, { f: p.pitch, partials: [[1, 1, 1], [2, 0.28, 0.55], [3.01, 0.1, 0.3]], dur: 0.42, peak: 0.047, a: 0.003 });
  } else {
    T.osc(out, at, { type: 'triangle', f: p.pitch * 0.55, to: p.pitch * 0.5, dur: 0.16, peak: 0.055, a: 0.006, lp: p.pitch * 1.3 });
    T.osc(out, at + 0.12, { type: 'triangle', f: p.pitch * 0.44, to: p.pitch * 0.38, dur: 0.22, peak: 0.055, a: 0.006, lp: p.pitch * 1.3 });
  }
}

function (T, out, t, p) {
  const steps = [0, 2, 4];
  const lift = [0.85, 1, 0.92];   // the middle dot leans forward a little
  for (let k = 0; k < 3; k++) {
    const at = t + k * p.gap;
    // a few cents and a fraction of a dB per dot, so the three are never copies
    const o = T.jitter({ f: p.pitch * Math.pow(2, steps[k] / 12), peak: 0.03 * lift[k] }, { cents: 8, db: 0.8 });
    T.osc(out, at, { f: o.f * 0.86, to: o.f, glide: 0.035, dur: 0.15, peak: o.peak, a: 0.008 });
    T.osc(out, at, { f: o.f * 2, dur: 0.07, peak: o.peak * 0.4 * p.glass, a: 0.006 });
  }
}

function (T, out, t, p) {
  T.pluck(out, t, { f: p.pitch, dur: 0.22 + 0.12 * p.twang, bright: 0.3 + 0.6 * p.twang, peak: 0.075 });
  T.osc(out, t, { f: p.pitch * 0.9, to: p.pitch * 0.5, dur: 0.1, peak: 0.03, a: 0.003 });
  // the arrow leaves and recedes: bright and loud at first, then falling away
  T.noise(out, t + 0.015, {
    filter: 'bandpass', f: 5200, to: 1500, q: 2, dur: p.flight, peak: 0.09, a: 0.012,
  });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch * 0.9, to: p.pitch * 1.8, glide: 0.05, dur: 0.06, peak: 0.065, a: 0.004 });
  T.osc(out, t + 0.045, {
    f: p.pitch * 1.8, to: p.pitch, glide: p.length * 0.9, dur: p.length, peak: 0.08, a: 0.01,
    vib: { rate: 13, depth: 350 * p.wobble },
  });
  T.osc(out, t + 0.045, {
    type: 'triangle', f: p.pitch * 3.6, to: p.pitch * 2, glide: p.length * 0.9, dur: p.length * 0.8,
    peak: 0.016, a: 0.01, vib: { rate: 13, depth: 350 * p.wobble },
  });
}

function (T, out, t, p) {
  const steps = [0, 7, 12];
  // the bell partials sit near whole multiples, so it sounds like a held chord, not struck metal
  const warm = [[1, 1, 1], [2, 0.3, 0.5], [3, 0.15, 0.3], [4.07, 0.1, 0.2]];
  T.osc(out, t, { f: 110, to: 70, dur: 0.15, peak: 0.06, a: 0.004 });
  for (let k = 0; k < 3; k++) {
    T.bell(out, t + 0.03 + k * p.spread, {
      f: p.pitch * Math.pow(2, steps[k] / 12), partials: warm, dur: p.ring, peak: 0.055, a: 0.003,
    });
  }
  T.noise(out, t + 0.03 + 2 * p.spread, {
    filter: 'highpass', f: 6000, to: 9000, q: 0.8, dur: 0.15, peak: 0.02, a: 0.03,
  });
}

function (T, out, t, p) {
  const n = Math.round(p.spins);
  const base = p.pitch * 0.574;
  for (let k = 0; k < n; k++) {
    T.osc(out, t + k * p.spin, { type: 'triangle', f: base * (1 + 0.078 * k), dur: 0.05, peak: 0.055, a: 0.004 });
  }
  const land = t + n * p.spin + 0.07;
  T.osc(out, land, { f: p.pitch, dur: p.ring, peak: 0.13, a: 0.006 });
  T.osc(out, land, { f: p.pitch * 2.76, to: p.pitch * 2.7, dur: p.ring * 0.38, peak: 0.05, a: 0.006 });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const scale = [0, 2, 4, 7, 9, 12, 14, 16];
  const f = p.pitch * Math.pow(2, scale[Math.round(p.streak) - 1] / 12);
  if (chip) {
    const dest = T.crush(out, t, { bits: 4, ref: 0.07 });
    T.osc(dest, t, { type: 'square', f, dur: p.ring * 0.8, peak: 0.07, a: 0.003 });
    T.osc(out, t, { type: 'triangle', f: f * 2, dur: p.ring * 0.4, peak: 0.02, a: 0.003 });
  } else {
    T.bell(out, t, {
      f, partials: [[1, 1, 1], [2, 0.35, 0.55], [3.01, 0.18, 0.35]], dur: p.ring, peak: 0.07, a: 0.003,
    });
    T.osc(out, t, { f: f * 4, dur: 0.05, peak: 0.012, a: 0.002 });
  }
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const go = p.go >= 0.5;
  const len = go ? p.length * 2.4 : p.length;
  const f = go ? p.pitch * 2 : p.pitch;
  const peak = (chip ? 0.065 : 0.07) * (go ? 1.15 : 1);
  const dest = chip ? T.crush(out, t, { bits: 5, ref: peak }) : out;
  const type = chip ? 'square' : 'sine';
  // a beep is flat on top with a short release, not a decaying ping
  T.osc(dest, t, { type, f, dur: len, peak, a: 0.003, s: 0.9, d: 0.01, r: len * 0.25 });
  if (go) {
    T.osc(dest, t, { type, f: f * 1.5, dur: len, peak: peak * 0.4, a: 0.003, s: 0.9, d: 0.01, r: len * 0.25 });
  }
  if (!chip) T.osc(out, t, { type: 'triangle', f: f * 2, dur: len * 0.8, peak: 0.02, a: 0.003, s: 0.8, d: 0.01 });
}

function (T, out, t, p) {
  // the latch: a bright click then a small knock as it lets go
  T.noise(out, t, { filter: 'highpass', f: 3200, to: 2400, q: 0.8, dur: 0.012, peak: 0.05, a: 0.001 });
  T.noise(out, t + 0.03, { filter: 'bandpass', f: 1400, q: 2, dur: 0.02, peak: 0.05, a: 0.001 });
  T.osc(out, t + 0.03, { f: 160, to: 110, dur: 0.05, peak: 0.03, a: 0.002 });
  // the hinge: the door swings, so the creak climbs and the bandpass opens with it
  const s = t + 0.08;
  const band = T.filter(out, s, { type: 'bandpass', f: 500, to: 900, dur: p.length, q: 3 });
  const f0 = p.pitch * T.rand(0.95, 1.05);
  T.osc(band, s, {
    type: 'sawtooth', f: f0, to: f0 * 1.5, dur: p.length, peak: 0.17, a: 0.08, s: 0.8, d: 0.2, r: p.length * 0.3,
    trem: { rate: 14 + 10 * p.creak, depth: 0.4 + 0.6 * p.creak },
    vib: { rate: 9, depth: 40 + 200 * p.creak },
  });
  // a second hinge a fifth up, shuddering at an unrelated rate, so the stick and slip never lines up
  T.osc(band, s + 0.02, {
    type: 'sawtooth', f: f0 * 1.51, to: f0 * 2.2, dur: p.length - 0.02, peak: 0.1, a: 0.1, s: 0.8, d: 0.2, r: p.length * 0.3,
    trem: { rate: 19 + 13 * p.creak, depth: 0.5 + 0.5 * p.creak },
  });
  T.noise(band, s, { filter: 'none', dur: p.length, peak: 0.08 * p.creak, a: 0.1, s: 0.8, d: 0.2, r: p.length * 0.3 });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const peak = chip ? 0.06 : 0.08;
  const dest = chip ? T.crush(out, t, { bits: 4, ref: peak * 1.1 }) : out;
  const type = chip ? 'square' : 'triangle';
  const curve = chip ? 'lin' : 'exp';
  // the second hop starts a lift higher than the first and sweeps further
  const f2 = p.pitch * Math.pow(2, Math.round(p.lift) / 12) * 1.25;
  // the first hop ends before the second begins (gap is at least 0.08), so squares never stack
  T.osc(dest, t, { type, f: p.pitch, to: p.pitch * 2, glide: 0.06, glideCurve: curve, dur: 0.075, peak, a: 0.004 });
  T.osc(dest, t + p.gap, {
    type, f: f2, to: f2 * 2.2, glide: 0.1, glideCurve: curve,
    dur: 0.15, peak: peak * 1.1, a: 0.004, s: 0.7, d: 0.04, r: 0.07,
  });
  if (!chip) {
    T.osc(out, t + p.gap, { f: f2 * 2, to: f2 * 4.4, glide: 0.1, dur: 0.13, peak: 0.02, a: 0.004 });
    T.noise(out, t + p.gap, { filter: 'highpass', f: 5000, to: 7000, q: 0.8, dur: 0.06, peak: 0.02, a: 0.01 });
  }
}

function (T, out, t, p) {
  const L = p.size;
  T.noise(out, t, {
    filter: 'lowpass', f: 2800 - 1700 * p.soften, to: 120, q: 0.8, dur: L, peak: 0.23, a: 0.01,
  });
  T.osc(out, t, { f: p.pitch * 2.2, to: p.pitch * 0.6, glide: L * 0.8, dur: L * 0.9, peak: 0.1, a: 0.004 });
  T.osc(out, t, { f: 700, to: 160, dur: 0.07, peak: 0.031, a: 0.002 });
  for (let k = 0; k < 5; k++) {
    T.noise(out, t + 0.05 + k * 0.04 + T.rand(0, 0.03), {
      filter: 'highpass', f: 3500, q: 0.8, dur: 0.02,
      peak: 0.016 * p.crackle * T.rand(0.6, 1), a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const j = T.rand(0.92, 1.08) * p.pitch;
  const l = T.rand(0.85, 1.15);
  T.noise(out, t, {
    filter: 'bandpass', f: (2000 + 2200 * p.surface) * j, q: 1.2,
    dur: 0.02, peak: (0.05 + 0.03 * p.surface) * l, a: 0.001,
  });
  T.osc(out, t, {
    type: 'triangle', f: (280 - 70 * p.surface) * j, to: (150 - 30 * p.surface) * j,
    dur: 0.07, peak: (0.025 + 0.014 * p.weight) * l, a: 0.002,
  });
  T.osc(out, t, {
    f: 115 * j, to: 70, dur: 0.1, peak: (0.007 + 0.025 * p.weight) * l, a: 0.003,
  });
  T.bell(out, t, {
    f: 1800 * j, partials: [[1, 1, 1], [2.76, 0.4, 0.5]], dur: 0.06,
    peak: 0.008 * p.surface * l, a: 0.001,
  });
}

function (T, out, t, p) {
  const j = T.rand(0.9, 1.1);
  const l = T.rand(0.85, 1.15);
  T.noise(out, t, {
    filter: 'lowpass', f: (500 + 1700 * p.surface) * j, to: 250, q: 0.8,
    dur: p.length, peak: (0.053 + 0.053 * p.weight) * l, a: 0.012,
  });
  T.osc(out, t, {
    f: (70 + 30 * p.weight) * j, to: 45, dur: p.length * 1.1,
    peak: (0.009 + 0.015 * p.weight) * l, a: 0.008,
  });
  // gravel crunch: scales with surface, so carpet gets none
  T.noise(out, t + 0.01, {
    filter: 'highpass', f: 3500, q: 0.8, dur: 0.04 + 0.04 * p.surface,
    peak: 0.009 * p.surface * l, a: 0.006,
  });
}

function (T, out, t, p) {
  const glass = [[1, 1, 1], [2.32, 0.45, 0.55], [4.25, 0.25, 0.35], [6.63, 0.12, 0.22]];
  T.bell(out, t, { f: p.pitch, partials: glass, dur: p.ring * 0.7, peak: 0.05, a: 0.002 });
  T.bell(out, t + p.gap, { f: p.pitch * 1.5, partials: glass, dur: p.ring, peak: 0.055, a: 0.002 });
  T.noise(out, t + p.gap, {
    filter: 'highpass', f: 6000, to: 9000, q: 0.8, dur: 0.18,
    peak: 0.05 * p.sparkle, a: 0.02,
  });
}

function (T, out, t, p) {
  const h = t + p.swing;
  const r = p.pitch / 560;
  if (p.swing > 0.05) {
    T.noise(out, t, { filter: 'bandpass', f: 350, to: 1700, q: 1.2, dur: p.swing + 0.02, peak: 0.055, a: p.swing * 0.85 });
  }
  T.bell(out, h, { f: p.pitch, partials: [[1, 1, 1], [2.76, 0.5, 0.67]], drift: 0.98, dur: p.ring, peak: 0.065 });
  T.noise(out, h, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: 0.04, a: 0.001 });
  T.noise(out, h, { filter: 'highpass', f: 3200, to: 2000, q: 0.8, dur: 0.05, peak: 0.037, a: 0.002 });
  T.osc(out, h, { type: 'triangle', f: 1800 * r, to: 700 * r, dur: 0.09, peak: 0.021, a: 0.002 });
  T.osc(out, h, { f: 140, to: 60, dur: 0.16, peak: 0.14 * p.weight + 0.01, a: 0.002 });
}

function (T, out, t, p) {
  const L = p.length;
  const up = Math.pow(2, Math.round(p.rise) / 12);
  T.osc(out, t, { f: p.pitch, to: p.pitch * up, glide: L * 0.6, dur: L, peak: 0.04, a: L * 0.3 });
  T.osc(out, t, { f: p.pitch * 1.5, to: p.pitch * 1.5 * up, glide: L * 0.6, dur: L, peak: 0.028, a: L * 0.35 });
  T.osc(out, t, { type: 'triangle', f: p.pitch * 2, to: p.pitch * 2 * up, glide: L * 0.6, dur: L, peak: 0.02, a: L * 0.4 });
  T.noise(out, t, { filter: 'highpass', f: 5500, to: 8000, q: 0.8, dur: L, peak: 0.03 * p.glow, a: L * 0.4 });
  // the crest: a single soft bell partial pair, scaled by glow so glow 0 is a plain swell
  T.bell(out, t + L * 0.3, {
    f: p.pitch * 4 * up, partials: [[1, 1, 1], [2.76, 0.3, 0.5]], dur: Math.min(0.45, L * 0.7),
    peak: 0.018 * p.glow, a: 0.004,
  });
}

function (T, out, t, p) {
  const bus = T.drive(out, t, { amount: 0.2, ref: 0.15 });
  T.osc(bus, t, {
    f: p.pitch * 2.2, to: p.pitch * 0.5, glide: 0.2, dur: p.tail + 0.1,
    peak: 0.1 + 0.1 * p.weight, a: 0.002,
  });
  T.noise(bus, t, {
    filter: 'lowpass', f: 1800, to: 150, q: 0.8, dur: p.tail, peak: 0.25 + 0.2 * p.weight, a: 0.002,
  });
  T.noise(bus, t, {
    filter: 'highpass', f: 3000, to: 1800, q: 0.8, dur: 0.035, peak: 0.04 + 0.12 * p.crack, a: 0.001,
  });
}

function (T, out, t, p) {
  const j = T.rand(0.95, 1.05);
  T.osc(out, t, { f: p.pitch * 1.6 * j, to: p.pitch * 0.7, dur: 0.07, peak: 0.035 + 0.035 * p.body, a: 0.002 });
  T.noise(out, t, {
    filter: 'bandpass', f: 1800 + 2200 * p.snap, q: 0.9, dur: 0.035,
    peak: 0.042 + 0.056 * p.snap, a: 0.001,
  });
  T.osc(out, t, { type: 'triangle', f: 1400 + 1400 * p.snap, to: 700, dur: 0.03, peak: 0.01, a: 0.001 });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const peak = chip ? 0.1 : 0.11;
  let dest = out;
  if (chip) dest = T.crush(out, t, { bits: 4, ref: peak });
  else dest = T.filter(out, t, { type: 'lowpass', f: 2400, to: 700, dur: p.length, q: 1 });
  T.osc(dest, t, {
    type: chip ? 'square' : 'sawtooth', f: p.pitch, to: p.pitch * (1 - p.drop),
    glide: p.length * 0.9, dur: p.length, peak, a: 0.004,
    s: 0.7, d: p.length * 0.25, r: p.length * 0.4, vib: { rate: 24, depth: 120 },
  });
  T.noise(out, t, { filter: 'bandpass', f: 1500, to: 600, q: 1, dur: 0.05, peak: 0.07, a: 0.002 });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const peak = chip ? 0.065 : 0.085;
  // quantize against the voice peak so the decay walks down 8 steps
  const dest = chip ? T.crush(out, t, { bits: 4, ref: peak }) : out;
  const top = p.pitch * p.rise;
  T.osc(dest, t, {
    type: chip ? 'square' : 'triangle', f: p.pitch, to: top,
    glide: p.length * 0.85, glideCurve: chip ? 'lin' : 'exp',
    dur: p.length, peak, a: 0.004, s: 0.75, d: p.length * 0.2, r: p.length * 0.45,
  });
  if (!chip) {
    T.osc(out, t, { f: p.pitch * 2, to: top * 2, glide: p.length * 0.85, dur: p.length, peak: 0.02, a: 0.004 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.jingles);
  for (let k = 0; k < n; k++) {
    const at = t + k * 0.035 + T.rand(0, 0.008);
    const f = p.pitch * T.rand(0.85, 1.2);
    T.noise(out, at, { filter: 'bandpass', f, q: 4, dur: 0.015, peak: 0.1 * T.rand(0.7, 1), a: 0.001 });
    T.bell(out, at, { f, partials: [[1, 1, 1], [2.76, 0.5, 0.7]], dur: 0.05, peak: 0.025, a: 0.001 });
  }
  const turn = t + n * 0.035 + 0.05;
  T.noise(out, turn, { filter: 'bandpass', f: 1800, to: 2600, q: 3, dur: 0.09, peak: 0.06, a: 0.03 });
  const bolt = turn + 0.1;
  T.osc(out, bolt, { f: 190, to: 90, dur: 0.1, peak: 0.025 + 0.05 * p.clunk, a: 0.002 });
  T.noise(out, bolt, { filter: 'lowpass', f: 1200, to: 500, q: 0.8, dur: 0.045, peak: 0.03 + 0.07 * p.clunk, a: 0.001 });
  T.noise(out, bolt, { filter: 'highpass', f: 3000, q: 0.8, dur: 0.01, peak: 0.05, a: 0.001 });
  T.bell(out, bolt + 0.04, {
    f: p.pitch * 0.5, partials: [[1, 1, 1], [2.76, 0.3, 0.5]], dur: 0.35, peak: 0.045 * p.ding, a: 0.002,
  });
}

function (T, out, t, p) {
  const j = T.rand(0.94, 1.06);
  T.osc(out, t, {
    f: p.pitch * 1.5 * j, to: p.pitch * 0.6, dur: 0.12 + 0.08 * p.weight,
    peak: 0.022 + 0.032 * p.weight, a: 0.003,
  });
  T.noise(out, t, {
    filter: 'lowpass', f: 900 + 1200 * p.scuff, to: 300, q: 0.7,
    dur: 0.07 + 0.05 * p.weight, peak: 0.057 + 0.05 * p.weight, a: 0.002,
  });
  T.noise(out, t + 0.004, {
    filter: 'bandpass', f: 3000 * j, q: 0.8,
    dur: 0.045 + 0.05 * p.scuff, peak: 0.013 + 0.038 * p.scuff, a: 0.004,
  });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const hi = p.pitch * Math.pow(2, Math.round(p.interval) / 12);
  const peak = chip ? 0.045 : 0.06;
  const dest = chip ? T.crush(out, t, { bits: 4, ref: peak }) : out;
  const type = chip ? 'square' : 'sine';
  T.osc(dest, t, { type, f: p.pitch * 0.9, to: p.pitch, glide: 0.03, dur: 0.07, peak, a: 0.004 });
  T.osc(dest, t + p.gap, { type, f: hi * 0.93, to: hi, glide: 0.035, dur: 0.14, peak, a: 0.004 });
  if (!chip) {
    T.osc(out, t + p.gap, { type: 'triangle', f: hi * 2, dur: 0.09, peak: 0.012, a: 0.004 });
    // a speck of air at the grab, so it reads as a pop and not a beep
    T.noise(out, t, { filter: 'highpass', f: 4500, q: 0.8, dur: 0.015, peak: 0.01, a: 0.001 });
  }
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const steps = [0, 2, 4, 7, 9, 12, 14, 16];
  const n = Math.round(p.notes);
  const peak = chip ? 0.08 : 0.1;
  const dest = chip ? T.crush(out, t, { bits: 4, ref: peak }) : out;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    const at = t + k * p.gap;
    if (k < n - 1) {
      // chip notes are flat-topped and cut off, not decaying, so the run reads as a staircase
      if (chip) T.osc(dest, at, { type: 'square', f, dur: p.gap * 1.05, peak, a: 0.003, s: 0.95, d: 0.004, r: 0.006 });
      else T.osc(dest, at, { type: 'triangle', f, dur: p.gap * 1.1, peak, a: 0.003 });
    } else {
      // the held note: flat top, then a release; soft mode also gets a gentle vibrato
      T.osc(dest, at, {
        type: chip ? 'square' : 'triangle', f, dur: 0.22, peak, a: 0.003, s: 0.7, d: 0.04, r: 0.12,
        vib: chip ? null : { rate: 6, depth: 14 },
      });
      if (!chip) T.osc(out, at, { f: f * 2, dur: 0.18, peak: 0.02, a: 0.004 });
    }
  }
}

function (T, out, t, p) {
  const n = Math.round(p.hits);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const l = (1 - 0.12 * k) * T.rand(0.9, 1.1);
    T.osc(out, at, { f: p.pitch * 1.8, to: p.pitch * 0.6, dur: 0.13, peak: 0.065 * l, a: 0.002 });
    T.noise(out, at, {
      filter: 'bandpass', f: (700 + 800 * p.snap) * T.rand(0.9, 1.15), q: 0.8,
      dur: 0.06, peak: 0.16 * l, a: 0.002,
    });
    T.noise(out, at, {
      filter: 'highpass', f: 2500, q: 0.8, dur: 0.02, peak: (0.024 + 0.056 * p.snap) * l, a: 0.001,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const lp = T.filter(out, t, { type: 'lowpass', f: 300, to: 4200, dur: L * 0.9, q: 1.5 });
  T.osc(lp, t, {
    type: 'sawtooth', f: p.pitch, to: p.pitch * 2, glide: L * 0.9, dur: L, peak: 0.05, a: L * 0.55, s: 0.8, d: 0.02, r: L * 0.3,
    trem: { rate: 18, depth: 0.3 },
  });
  T.osc(lp, t, {
    type: 'sawtooth', f: p.pitch, to: p.pitch * 2, glide: L * 0.9, dur: L, peak: 0.04, a: L * 0.55, s: 0.8, d: 0.02, r: L * 0.3, detune: 14,
  });
  T.noise(out, t, {
    filter: 'highpass', f: 3000, to: 7500, q: 0.8, dur: L, peak: 0.04 * p.shimmer, a: L * 0.6,
  });
  // the lock-in ping, an octave and a half above the hum's start
  T.bell(out, t + L * 0.8, {
    f: p.pitch * 8, partials: [[1, 1, 1], [2.76, 0.35, 0.6]], dur: 0.3, peak: 0.05 * p.lock, a: 0.003,
  });
}

function (T, out, t, p) {
  const steel = [[1, 1, 1], [2.76, 0.7, 0.7], [5.4, 0.45, 0.45], [8.93, 0.25, 0.25]];
  T.bell(out, t, { f: p.pitch, partials: steel, drift: 0.995, dur: p.ring, peak: 0.025, a: 0.001 });
  // the second blade: a bit later, a bit shorter, a different pitch, so the ring beats
  T.bell(out, t + 0.008, { f: p.pitch * 1.19, partials: steel, drift: 0.995, dur: p.ring * 0.8, peak: 0.02, a: 0.001 });
  T.noise(out, t, { filter: 'highpass', f: 3500, to: 2500, q: 0.8, dur: 0.03, peak: 0.09, a: 0.001 });
  T.noise(out, t, { filter: 'bandpass', f: 1800, to: 1000, q: 1.5, dur: 0.06, peak: 0.1, a: 0.001 });
  T.noise(out, t + 0.02, {
    filter: 'bandpass', f: 4000, to: 7000, q: 4, dur: 0.12 + 0.12 * p.scrape,
    peak: 0.05 * p.scrape, a: 0.04,
  });
}

function (T, out, t, p) {
  const s = p.length / 0.17;
  T.noise(out, t, {
    filter: 'bandpass', f: 1400 * p.pitch, to: 6200 * p.pitch, q: 2.6,
    dur: 0.14 * s, peak: 0.18, a: 0.045 * s,
  });
  T.noise(out, t + 0.07 * s, {
    filter: 'bandpass', f: 5200 * p.pitch, to: 1800 * p.pitch, q: 3.2,
    dur: 0.1 * s, peak: 0.1, a: 0.02 * s,
  });
  T.osc(out, t + 0.02 * s, {
    f: 3200 * p.pitch, to: 5200 * p.pitch, dur: 0.14 * s, peak: 0.01 * p.edge, a: 0.04 * s,
  });
}

function (T, out, t, p) {
  const L = p.length;
  if (p.fizzle < 0.5) {
    // the snap of the card, then the blast: a held tone with a small upward chirp at the start
    T.noise(out, t, { filter: 'highpass', f: 2600, to: 1800, q: 0.8, dur: 0.03, peak: 0.022, a: 0.002 });
    const at = t + 0.02;
    T.osc(out, at, {
      f: p.pitch, to: p.pitch * 1.064, dur: L, peak: 0.1, a: 0.02, s: 0.85, d: 0.04, r: 0.06,
      trem: { rate: 27, depth: p.pea }, vib: { rate: 27, depth: 18 * p.pea },
    });
    // the second harmonic is kept tiny so it stays a whistle and never turns shrill
    T.osc(out, at, { f: p.pitch * 2, to: p.pitch * 2.128, dur: L, peak: 0.012, a: 0.02, s: 0.85, d: 0.04, r: 0.06, trem: { rate: 27, depth: p.pea } });
    T.noise(out, at, { filter: 'bandpass', f: p.pitch * 1.04, q: 8, dur: L, peak: 0.12, a: 0.03, s: 0.7, d: 0.05, r: 0.06 });
  } else {
    // the whistle fails: the pitch sags to under half, the trill slows and a sigh of air follows
    const D = L * 1.3;
    T.osc(out, t, { f: p.pitch, to: p.pitch * 0.42, dur: D, peak: 0.09, a: 0.02, trem: { rate: 22, depth: 0.6 * (0.4 + 0.6 * p.pea) } });
    T.noise(out, t + D * 0.55, { filter: 'lowpass', f: 900, to: 300, q: 1, dur: 0.22, peak: 0.1, a: 0.01 });
  }
}

function (T, out, t, p) {
  const s = p.length / 0.27;
  // a narrower band throws more of the noise away: lift the peak so the loudness holds
  const lift = Math.sqrt(p.q / 1.1);
  T.noise(out, t, {
    filter: 'bandpass', f: 420 * p.pitch, to: 2300 * p.pitch, q: p.q,
    dur: 0.21 * s, peak: 0.19 * lift, a: 0.045 * s,
  });
  T.noise(out, t + 0.1 * s, {
    filter: 'bandpass', f: 1900 * p.pitch, to: 620 * p.pitch, q: p.q * 1.36,
    dur: 0.17 * s, peak: 0.105 * lift, a: 0.032 * s,
  });
}

function (T, out, t, p) {
  const chip = p.chip >= 0.5;
  const steps = [[0, 12], [0, 7, 12], [0, 4, 7, 12]][Math.round(p.notes) - 2];
  const peak = chip ? 0.08 : 0.085;
  const dest = chip ? T.crush(out, t, { bits: 5, ref: 0.1 }) : out;
  const voice = (at, o) => (chip ? T.osc(dest, at, Object.assign({ type: 'square' }, o)) : T.pulse(dest, at, Object.assign({ duty: 0.25 }, o)));
  // the swoop: an octave below the root up into it
  voice(t, { f: p.pitch / 2, to: p.pitch, glide: 0.055, dur: 0.07, peak: peak * 0.5, a: 0.004 });
  let at = t + 0.06;
  for (let k = 0; k < steps.length; k++) {
    const last = k === steps.length - 1;
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    if (last) {
      voice(at, { f, dur: p.hold, peak, a: 0.003, s: 0.75, d: 0.03, r: p.hold * 0.45, vib: { rate: 7, depth: 14 } });
      if (!chip) T.osc(out, at, { type: 'triangle', f: f * 2, dur: p.hold * 0.7, peak: 0.014, a: 0.004 });
      // a sparkle over the landing note
      T.noise(out, at + 0.01, { filter: 'highpass', f: 7000, to: 11000, q: 0.7, dur: 0.14, peak: 0.01, a: 0.01 });
    } else {
      voice(at, { f, dur: p.gap * 1.25, peak: peak * 0.8, a: 0.003, s: 0.6, d: 0.02, r: p.gap * 0.4 });
      at += p.gap;
    }
  }
}

function (T, out, t, p) {
  const g = 0.14 + 0.08 * p.power;
  const f = p.pitch;
  const pt = t + g * 0.55;
  // the breath and the glide
  T.noise(out, t, { filter: 'bandpass', f: 700, to: 2600, q: 1.4, dur: g, peak: 0.09, a: g * 0.3 });
  T.osc(out, t, { type: 'triangle', f, to: f * 2, dur: g, peak: 0.09, a: 0.008 });
  // the banner ping: the top note and one a fourth below it
  T.osc(out, pt, { f: f * 4, dur: p.ring, peak: 0.055, a: 0.006 });
  T.osc(out, pt, { type: 'triangle', f: f * 2.667, dur: p.ring * 0.9, peak: 0.035, a: 0.006 });
  if (p.power > 0.02) {
    T.osc(out, t, { f: f * 0.5, to: f, dur: g + 0.1, peak: 0.07 * p.power, a: g * 0.8 });
    T.osc(out, pt + 0.05, { f: f * 3, dur: p.ring, peak: 0.04 * p.power, a: 0.006 });
  }
}

function (T, out, t, p) {
  const r = t + p.draw;
  const h = r + p.flight;
  // the draw: wood and string creaking tighter, a narrow band over a rising tone
  T.osc(out, t, { type: 'triangle', f: 160, to: 235, dur: p.draw, peak: 0.04, a: p.draw * 0.8 });
  T.noise(out, t, { filter: 'bandpass', f: 900, to: 1100, q: 4, dur: p.draw, peak: 0.15, a: p.draw * 0.8 });
  // the flight: a whistle rising as the arrow closes in
  T.noise(out, r, { filter: 'bandpass', f: p.whistle, to: p.whistle * 1.6, q: 3, dur: p.flight, peak: 0.15, a: p.flight * 0.65 });
  T.osc(out, r, { f: p.whistle * 0.73, to: p.whistle * 0.88, dur: p.flight, peak: 0.022, a: p.flight * 0.7 });
  // the landing: a short body, a dry tick of wood, and the shaft shivering
  T.osc(out, h, { f: 340 - 120 * p.thunk, to: 120 - 40 * p.thunk, dur: 0.12, peak: 0.055 + 0.065 * p.thunk, a: 0.002 });
  T.noise(out, h, { filter: 'highpass', f: 2600, to: 1600, q: 0.8, dur: 0.04, peak: 0.06, a: 0.002 });
  if (p.quiver > 0.02) {
    T.osc(out, h + 0.01, { type: 'triangle', f: 330, to: 300, dur: 0.18, peak: 0.04 * p.quiver, a: 0.004, trem: { rate: 28, depth: 0.8 } });
  }
}

function (T, out, t, p) {
  const g = p.gap;
  const x = t + g + 0.03;
  const snap = (at, f, l) => {
    T.bell(out, at, { f, partials: [[1, 1, 1], [2.76, 0.5, 0.7]], dur: 0.08, peak: 0.04 * l * p.edge, a: 0.002 });
    T.noise(out, at, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: 0.05 * l * p.edge, a: 0.001 });
  };
  // two cuts, the second sweeping the other way so they read as an X
  T.noise(out, t, { filter: 'bandpass', f: 2800, to: 6000, q: 1.2, dur: 0.1, peak: 0.13, a: 0.012 });
  T.noise(out, t + g, { filter: 'bandpass', f: 6000, to: 2800, q: 1.2, dur: 0.1, peak: 0.11, a: 0.012 });
  snap(t + 0.04, 1900, 1);
  snap(t + g + 0.05, 2300, 1.2);
  // the chop where they cross
  T.osc(out, x, { f: 200, to: 90, dur: 0.14, peak: 0.05 + 0.12 * p.weight, a: 0.003 });
  T.noise(out, x, { filter: 'lowpass', f: 2000, to: 600, q: 1, dur: 0.12, peak: 0.03 + 0.08 * p.weight, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.claws);
  const last = t + (n - 1) * p.rake;
  for (let k = 0; k < n; k++) {
    T.noise(out, t + k * p.rake, { filter: 'bandpass', f: T.jitter(4200, { cents: 150 }), to: 900, q: 2, dur: 0.09, peak: 0.22, a: 0.004 });
  }
  // the rasp: a crackle of grit across the whole rake
  if (p.tear > 0.02) {
    T.crackle(out, t, { dur: n * p.rake + 0.06, rate: 160, f: 3500, to: 1500, spread: 0.7, q: 1.2, len: 0.005, peak: 0.16 * p.tear });
  }
  // the body behind the last swipe
  T.osc(out, last + 0.03, { f: 130, to: 52, dur: 0.24, peak: 0.04 + 0.07 * p.weight, a: 0.004 });
  T.noise(out, last + 0.03, { filter: 'lowpass', f: 1400, to: 250, q: 1, dur: 0.15, peak: 0.025 + 0.05 * p.weight, a: 0.004 });
}

function (T, out, t, p) {
  const n = Math.round(p.discs);
  const b = t + p.flight;
  for (let k = 0; k < n; k++) {
    const at = t + k * 0.06;
    const d = Math.max(0.12, b - at);
    // each blade crosses from one side to the other, the next one the other way round
    const lane = T.pan(out, at, { x: k % 2 ? 0.7 : -0.7, to: k % 2 ? -0.7 : 0.7, dur: d });
    const f = 1046.5 * (1 + 0.12 * k);
    T.osc(lane, at, { type: 'triangle', f, to: f * 1.1, dur: d, peak: 0.04, a: 0.1, trem: { rate: p.spin, depth: 0.8 } });
  }
  // the burst: a low pop, then three bright points climbing and a breath of air
  T.osc(out, b, { f: 180, to: 80, dur: 0.18, peak: 0.085, a: 0.004 });
  if (p.stars > 0.02) {
    [1318.5, 1760, 2637].forEach((f, k) => {
      T.osc(out, b + k * 0.035, { type: 'triangle', f, dur: 0.12 + 0.18 * p.stars, peak: 0.052 * p.stars, a: 0.004 });
    });
    T.noise(out, b, { filter: 'highpass', f: 5000, to: 7000, q: 0.8, dur: 0.1, peak: 0.035 * p.stars, a: 0.005 });
  }
}

function (T, out, t, p) {
  const d = p.drop;
  const h = t + d;
  // the plunge: a whistle falling to a fifth of its start, wobbling a little, over rushing air
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.21, dur: d, peak: 0.06, a: 0.05, vib: { rate: 7, depth: 30 } });
  T.noise(out, t, { filter: 'bandpass', f: 3400, to: 600, q: 1.3, dur: d, peak: 0.14, a: 0.08 });
  // the landing: a falling body, a short mid knock and a burst of air
  T.osc(out, h, { f: 150, to: 55, dur: 0.22, peak: 0.11, a: 0.004 });
  T.osc(out, h, { type: 'triangle', f: 392, to: 262, dur: 0.1, peak: 0.035, a: 0.004 });
  T.noise(out, h, { filter: 'bandpass', f: 2600, to: 700, q: 1.6, dur: 0.12, peak: 0.085, a: 0.004 });
  // wisps: each a short rising puff of air ending in a tiny pop, a little softer than the last
  for (let k = 0; k < Math.round(p.wisps); k++) {
    const at = h + 0.07 + k * 0.085;
    const l = 1 - 0.2 * k;
    T.noise(out, at, { filter: 'bandpass', f: T.jitter(1800, { cents: 200 }), to: 4200, q: 2, dur: 0.12, peak: 0.07 * l, a: 0.04 });
    T.osc(out, at + 0.05, { f: T.jitter(520, { cents: 150 }), to: 300, dur: 0.07, peak: 0.045 * l, a: 0.004 });
  }
}

function (T, out, t, p) {
  const r = p.reach;
  const w = p.weight;
  const h = t + r;
  // the drive forward: air opening upward over a rising hum
  T.noise(out, t, { filter: 'bandpass', f: 260, to: 1500, q: 1.4, dur: r + 0.02, peak: 0.12, a: r * 0.85 });
  T.osc(out, t, { f: 98, to: 147, dur: r + 0.02, peak: 0.045, a: r * 0.7 });
  T.osc(out, t, { type: 'triangle', f: 196, to: 294, dur: r + 0.02, peak: 0.018, a: r * 0.7 });
  // contact: a falling body, a lowpassed dusty burst and a tiny crack of knuckle
  T.osc(out, h, { f: 190 - 80 * w, to: 44, dur: 0.14 + 0.1 * w, peak: 0.095, a: 0.003 });
  T.noise(out, h, { filter: 'lowpass', f: 1500 - 500 * w, to: 260, q: 1, dur: 0.1 + 0.05 * w, peak: 0.095, a: 0.003 });
  T.noise(out, h, { filter: 'highpass', f: 3000, to: 1200, q: 0.8, dur: 0.05, peak: 0.03, a: 0.002 });
  // the shockwave: a sub falling away and a soft band of rumble rolling out
  T.osc(out, h + 0.02, { f: 62, to: 30, dur: 0.2 + 0.3 * p.shock, peak: 0.035 + 0.06 * p.shock, a: 0.01 });
  T.noise(out, h + 0.03, { filter: 'bandpass', f: 900, to: 240, q: 0.9, dur: 0.15 + 0.3 * p.shock, peak: 0.026 + 0.077 * p.shock, a: 0.02 });
}

function (T, out, t, p) {
  const d = p.descent;
  const w = p.weight;
  const s = t + d;
  // the approach: low noise swelling open over a rising sub, something big coming down
  T.noise(out, t, { filter: 'lowpass', f: 180, to: 900, q: 1.2, dur: d + 0.02, peak: 0.15, a: d * 0.75 });
  T.osc(out, t, { f: 55, to: 80, dur: d + 0.02, peak: 0.07, a: d * 0.7 });
  // the landing: a deep falling sub, a lowpassed body of dust and a dull knock
  T.osc(out, s, { f: 96, to: 34, dur: 0.28 + 0.27 * w, peak: 0.11, a: 0.003 });
  T.noise(out, s, { filter: 'lowpass', f: 1200, to: 120, q: 1.1, dur: 0.15 + 0.3 * p.dust, peak: 0.043 + 0.085 * p.dust, a: 0.004 });
  T.osc(out, s, { type: 'triangle', f: 180, to: 70, dur: 0.2, peak: 0.043, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.hits);
  for (let k = 0; k < n; k++) {
    const last = k === n - 1;
    const at = t + k * p.gap;
    const l = last ? 0.6 + 0.55 * p.finish : 0.6;
    const v = T.jitter({ f: p.pitch, to: p.pitch * 0.42, peak: 0.11 * l }, { cents: 70, db: 1 });
    T.osc(out, at, { f: v.f, to: v.to, dur: 0.08, peak: v.peak, a: 0.003 });
    T.noise(out, at, { filter: 'lowpass', f: 2200, to: 600, q: 1, dur: 0.055, peak: 0.085 * l, a: 0.002 });
    if (last) {
      // the finisher: a deeper body under the last blow, none at finish 0
      T.osc(out, at, { f: p.pitch * 0.8, to: 60, dur: 0.16, peak: 0.06 * p.finish, a: 0.003 });
    }
  }
}

function (T, out, t, p) {
  const n = Math.round(p.flips);
  const heads = Math.min(n, Math.round(p.heads));
  const lead = 0.12;
  // coins still in the air: a thin flutter that lasts until the last one lands
  T.noise(out, t, { filter: 'bandpass', f: 1800, to: 2600, q: 3, dur: lead + (n - 1) * p.gap + 0.05, peak: 0.1, a: 0.05 });
  for (let k = 0; k < n; k++) {
    const at = t + lead + k * p.gap;
    const dest = T.pan(out, at, { x: k % 2 ? 0.3 : -0.3 });
    if (k < heads) {
      const f = p.pitch * Math.pow(1.04, k);
      T.bell(dest, at, { f, partials: [[1, 1, 1], [2.76, 0.4, 0.4], [5.4, 0.15, 0.2]], dur: 0.2, peak: 0.065, a: 0.003 });
    } else {
      T.osc(dest, at, { f: 698.5, to: 640, dur: 0.16, peak: 0.09, a: 0.004 });
      T.noise(dest, at, { filter: 'lowpass', f: 1200, to: 500, q: 1, dur: 0.05, peak: 0.08, a: 0.002 });
      T.noise(dest, at, { filter: 'bandpass', f: 2200, q: 2, dur: 0.015, peak: 0.06, a: 0.001 });
    }
  }
}

function (T, out, t, p) {
  const n = Math.round(p.count);
  const r = p.pitch / 587.3;
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    if (p.up >= 0.5) {
      const f = p.pitch * Math.pow(2, (3 * k) / 12);
      T.osc(out, at, { type: 'triangle', f, to: f * 1.06, dur: 0.08, peak: 0.05, a: 0.003 });
      T.osc(out, at, { f: f * 2, to: f * 2.1, dur: 0.05, peak: 0.016, a: 0.003 });
    } else {
      T.tick(out, at, { filter: 'highpass', f: 3500 * r, q: 0.8, dur: 0.016, peak: 0.026, blip: 1100 * r, blipTo: 800 * r, blipPeak: 0.03, blipDur: 0.03, jitter: 0.6 });
    }
  }
}

function (T, out, t, p) {
  const f = 523.25 * Math.pow(2, [0, 2, 4, 7, 9, 12, 14, 16, 19][Math.round(p.element)] / 12);
  T.noise(out, t, { filter: 'highpass', f: 3800, to: 2600, q: 0.8, dur: 0.022, peak: 0.03, a: 0.002 });
  T.osc(out, t, { type: 'triangle', f, to: f * 0.96, dur: 0.09, peak: 0.045, a: 0.003 });
  T.osc(out, t, { f: f * 2, to: f * 1.98, dur: p.ring, peak: 0.015, a: 0.003 });
  if (p.special >= 0.5) {
    T.osc(out, t + 0.028, { type: 'triangle', f: f * 2.5, to: f * 2.4, dur: 0.08, peak: 0.032, a: 0.003 });
    T.osc(out, t + 0.028, { f: f * 3.01, dur: p.ring, peak: 0.014, a: 0.003 });
    T.noise(out, t + 0.028, { filter: 'highpass', f: 6000, to: 8000, q: 0.8, dur: 0.12, peak: 0.01, a: 0.01 });
  }
}

function (T, out, t, p) {
  const h = t + p.swing;
  if (p.swing > 0.05) T.noise(out, t, { filter: 'bandpass', f: 350, to: 1700, q: 1.2, dur: p.swing + 0.02, peak: 0.07, a: p.swing * 0.85 });
  // the clank and the crack
  T.osc(out, h, { f: 560, to: 549, dur: 0.12, peak: 0.06, a: 0.002 });
  T.osc(out, h, { f: 1546, to: 1512, dur: 0.08, peak: 0.03, a: 0.002 });
  T.noise(out, h, { filter: 'highpass', f: 3400, to: 1300, q: 0.8, dur: 0.05, peak: 0.05, a: 0.002 });
  T.osc(out, h, { type: 'triangle', f: 1800, to: 700, dur: 0.09, peak: 0.025, a: 0.002 });
  T.osc(out, h, { f: 140, to: 60, dur: 0.16, peak: 0.035 + 0.06 * p.weight, a: 0.002 });
  // the thud
  T.noise(out, h + 0.02, { filter: 'lowpass', f: 1400, to: 220, q: 1.1, dur: 0.2, peak: 0.025 + 0.06 * p.weight, a: 0.003 });
  // the shards
  const n = Math.round(p.shards);
  for (let k = 0; k < n; k++) {
    const at = h + 0.04 + (k * 0.26) / n + T.rand(0, 0.02);
    const f = T.rand(2600, 6200);
    const fade = 1 - (0.6 * k) / n;
    T.osc(out, at, { f, to: f * 0.97, dur: T.rand(0.04, 0.09), peak: 0.02 * fade, a: 0.001 });
    T.noise(out, at, { filter: 'highpass', f: 3000 + 300 * k, to: 2400, q: 0.8, dur: 0.025, peak: 0.03 * fade, a: 0.001 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const f = p.pitch;
  if (p.up >= 0.5) {
    T.chord(out, t, { notes: [f, f * 1.5, f * 2], type: 'triangle', bend: 2, dur: L, peak: 0.11, a: L * 0.55, spread: 14 });
    T.noise(out, t, { filter: 'highpass', f: 2000, to: 6000, q: 0.8, dur: L, peak: 0.09 * p.shimmer, a: L * 0.6 });
    // the arrival: a bell on the top note of the chord
    T.bell(out, t + L * 0.82, { f: f * 4, partials: [[1, 1, 1], [2.76, 0.25, 0.5]], dur: 0.28, peak: 0.05, a: 0.006 });
  } else {
    T.chord(out, t, { notes: [f * 2, f * 3, f * 4], type: 'triangle', bend: 0.5, dur: L, peak: 0.11, a: L * 0.12, spread: 14 });
    T.noise(out, t, { filter: 'highpass', f: 6000, to: 2000, q: 0.8, dur: L, peak: 0.09 * p.shimmer, a: L * 0.1 });
    // the landing: a soft low note, the form it settled into
    T.osc(out, t + L * 0.82, { f, to: f * 0.8, dur: 0.26, peak: 0.05, a: 0.01 });
  }
}

function (T, out, t, p) {
  const D = p.length;
  const b = D * 0.4;
  // the throw: air and a rising whistle
  T.noise(out, t, { filter: 'bandpass', f: 1200, to: 4200, q: 1.2, dur: 0.12, peak: 0.07, a: 0.01 });
  T.osc(out, t, { type: 'triangle', f: 900, to: 1800, dur: 0.12, peak: 0.017, a: 0.01 });
  // the bite
  T.osc(out, t + b, { f: p.pitch, to: p.pitch * 0.98, dur: 0.12, peak: 0.045, a: 0.002 });
  T.osc(out, t + b, { f: p.pitch * 2.76, to: p.pitch * 2.7, dur: 0.08, peak: 0.022, a: 0.002 });
  T.noise(out, t + b, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: 0.028, a: 0.001 });
  // the reel: ratchet clicks spread over the pull, under a falling whoosh
  const n = Math.round(p.clicks);
  const step = Math.max(0.03, (D - b - 0.05) / n);
  for (let k = 0; k < n; k++) {
    T.tick(out, t + b + 0.05 + k * step, { filter: 'highpass', f: 2600, q: 0.8, dur: 0.014, peak: 0.034 * (1 - 0.08 * k), jitter: 0.5 });
  }
  T.noise(out, t + b, { filter: 'bandpass', f: 2400, to: 700, q: 1.1, dur: D - b + 0.05, peak: 0.056, a: 0.03 });
  // the card lands
  T.noise(out, t + D, { filter: 'lowpass', f: 1100, to: 480, q: 1, dur: 0.045, peak: 0.045, a: 0.002 });
  T.osc(out, t + D, { f: 200, to: 118, dur: 0.05, peak: 0.04, a: 0.003 });
}

function (T, out, t, p) {
  const w = p.weight;
  const f = p.pitch;
  // the moment of failure
  T.noise(out, t, { filter: 'highpass', f: 3400, to: 1300, q: 0.8, dur: 0.045, peak: 0.03 + 0.08 * p.crack, a: 0.002 });
  // the body: a falling tone, a smear of noise, a triangle underneath
  T.osc(out, t, { f, to: f * 0.25, dur: 0.34, peak: 0.14, a: 0.004 });
  T.noise(out, t + 0.012, { filter: 'lowpass', f: 2600, to: 155, q: 1.1, dur: 0.34, peak: 0.105, a: 0.004 });
  T.osc(out, t + 0.05, { type: 'triangle', f: f * 0.71, to: f * 0.28, dur: 0.26, peak: 0.058, a: 0.005 });
  // the slow sub that makes it heavy rather than loud
  T.osc(out, t + 0.07, {
    f: 84 - 20 * w, to: 37 - 7 * w, dur: p.length + 0.1 * w, peak: 0.06 + 0.06 * w, a: 0.014, tail: 0.08, fade: 0.05,
  });
  // the settle: the fighter landing, dull and low
  T.osc(out, t + 0.27, { f: 92, to: 48, dur: 0.14, peak: 0.025 + 0.05 * w, a: 0.004 });
  T.noise(out, t + 0.27, { filter: 'lowpass', f: 600, to: 220, q: 1, dur: 0.08, peak: 0.016 + 0.04 * w, a: 0.004 });
}

function (T, out, t, p) {
  const n = Math.round(p.count);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const r = 1 + 0.06 * k;
    T.noise(out, at, { filter: 'highpass', f: 2800, to: 1800, q: 0.9, dur: 0.034, peak: 0.032, a: 0.002 });
    T.osc(out, at, { type: 'triangle', f: 480, to: 260, dur: 0.028, peak: 0.01, a: 0.002 });
    [2.378, 2.997, 3.564].forEach((m, j) => {
      T.osc(out, at + 0.06 + j * 0.03, { type: 'triangle', f: p.pitch * m * r, dur: 0.18, peak: 0.034 - 0.006 * j, a: 0.004 });
    });
    T.noise(out, at + 0.06, { filter: 'highpass', f: 6000, to: 7000, q: 0.8, dur: 0.12, peak: 0.025, a: 0.01 });
  }
  const c = t + (n - 1) * p.gap + 0.15;
  T.osc(out, c, { type: 'triangle', f: p.pitch, dur: 0.13, peak: 0.09, a: 0.008 });
  T.osc(out, c + 0.1, { type: 'triangle', f: p.pitch * 1.498, dur: 0.16, peak: 0.08, a: 0.008 });
  T.osc(out, c + 0.1, { f: p.pitch * 2.996, dur: 0.12, peak: 0.025, a: 0.008 });
}

function (T, out, t, p) {
  const pop = (at, level) => T.noise(out, at + T.rand(0, 0.01), { filter: 'highpass', f: 2200 + 800 * p.heat, to: 2000, q: 0.8, dur: 0.018, peak: 0.07 * level, a: 0.001 });
  if (p.cure >= 0.5) {
    T.noise(out, t, { filter: 'highpass', f: 3600 + 1200 * p.heat, to: 2500, q: 0.8, dur: 0.43, peak: 0.05, a: 0.04 });
    T.osc(out, t, { f: 988, to: 740, dur: 0.25, peak: 0.025, a: 0.01 });
  } else if (p.tick >= 0.5) {
    T.noise(out, t, { filter: 'highpass', f: 3200, to: 6000, q: 0.8, dur: 0.42, peak: 0.045, a: 0.02 });
    pop(t + 0.05, 1);
    pop(t + 0.11, 1);
    pop(t + 0.2, 1);
    T.osc(out, t, { f: 120, to: 60, dur: 0.15, peak: 0.06, a: 0.006 });
  } else {
    T.noise(out, t, { filter: 'bandpass', f: 400, to: 1700 + 1800 * p.heat, q: 0.9, dur: 0.32, peak: 0.14, a: 0.06 });
    T.osc(out, t, { f: 130, to: 70, dur: 0.2, peak: 0.1, a: 0.01 });
    const n = Math.round(p.crackle);
    for (let k = 0; k < n; k++) pop(t + 0.05 + k * 0.045, 1 - 0.05 * k);
  }
}

function (T, out, t, p) {
  const star = (at, f, level) => T.osc(out, at, { type: 'triangle', f, dur: 0.1, peak: 0.04 * level, a: 0.003 });
  if (p.cure >= 0.5) {
    T.osc(out, t, { f: 600, to: 560, dur: 0.14, peak: 0.07, a: 0.01, vib: { rate: p.wobble, depth: 50 } });
    T.osc(out, t + 0.12, { f: 880, dur: 0.3, peak: 0.07, a: 0.006 });
    T.osc(out, t + 0.2, { f: 1318.5, dur: 0.3, peak: 0.05, a: 0.006 });
  } else if (p.tick >= 0.5) {
    T.osc(out, t, { f: 880, to: 220, dur: 0.14, peak: 0.06, a: 0.003 });
    T.osc(out, t, { type: 'triangle', f: 1250, dur: 0.05, peak: 0.03, a: 0.002 });
    star(t + 0.08, 1568, 0.9);
    star(t + 0.14, 2093, 0.75);
  } else {
    T.osc(out, t, { f: 700, to: 420, dur: 0.5, peak: 0.08, a: 0.01, vib: { rate: p.wobble, depth: 90 } });
    const notes = [1568, 1975.5, 1760, 2093, 1661];
    const n = Math.round(p.stars);
    for (let k = 0; k < n; k++) star(t + 0.05 + k * 0.1, notes[k], 1);
  }
}

function (T, out, t, p) {
  const zap = (at, f, level) => T.osc(out, at, { type: 'triangle', f, to: f * 0.25, dur: 0.05, peak: 0.04 * level, a: 0.002 });
  if (p.cure >= 0.5) {
    T.osc(out, t, { type: 'triangle', f: p.buzz, to: p.buzz * 0.5, dur: 0.2, peak: 0.06, a: 0.01, trem: { rate: 30, depth: 0.9 } });
    T.osc(out, t + 0.17, { f: p.buzz * 3, to: p.buzz * 6, dur: 0.09, peak: 0.08, a: 0.004 });
    T.osc(out, t + 0.2, { type: 'triangle', f: p.buzz * 8.2, dur: 0.22, peak: 0.06, a: 0.005 });
  } else if (p.tick >= 0.5) {
    T.osc(out, t, { type: 'triangle', f: p.buzz, to: p.buzz * 0.94, dur: 0.18, peak: 0.04, a: 0.01, trem: { rate: 34, depth: 0.9 } });
    zap(t, 2200, 0.8);
    zap(t + 0.06, 2500, 0.6);
    zap(t + 0.15, 2000, 0.7);
  } else {
    T.osc(out, t, { type: 'triangle', f: p.buzz, to: p.buzz * 0.94, dur: 0.32, peak: 0.05, a: 0.01, trem: { rate: 34, depth: 0.9 } });
    const n = Math.round(p.zaps);
    for (let k = 0; k < n; k++) zap(t + k * 0.12, 2400 - 200 * (k % 2), 1);
    T.noise(out, t, { filter: 'highpass', f: 3000, to: 4200, q: 0.8, dur: 0.08, peak: 0.045, a: 0.002 });
  }
}

function (T, out, t, p) {
  const f0 = p.pitch;
  const blip = (at, from, to, peak, len) => T.osc(out, at, { f: T.jitter(from, { cents: 60 }), to, dur: len, peak, a: 0.004 });
  if (p.cure >= 0.5) {
    for (let k = 0; k < 4; k++) blip(t + k * 0.05, f0 * (1.5 + 0.25 * k), f0 * (3 + 0.5 * k), 0.05, 0.06);
    T.osc(out, t + 0.2, { type: 'triangle', f: f0 * 4, dur: 0.22, peak: 0.07, a: 0.006 });
    T.osc(out, t + 0.28, { type: 'triangle', f: f0 * 6, dur: 0.26, peak: 0.06, a: 0.006 });
  } else if (p.tick >= 0.5) {
    blip(t, f0 * 1.46, f0 * 3.46, 0.09, 0.05);
    blip(t + 0.09, f0 * 1.15, f0 * 2.92, 0.07, 0.05);
    T.noise(out, t, { filter: 'lowpass', f: 450, to: 320, q: 4, dur: 0.16, peak: 0.16, a: 0.02 });
  } else {
    const n = Math.round(p.bubbles);
    for (let k = 0; k < n; k++) {
      blip(t + k * 0.075 + T.rand(0, 0.012), f0 * (1 + 0.23 * (k % 2)), f0 * (2.38 + 0.31 * k), 0.08, 0.06);
    }
    T.noise(out, t, { filter: 'lowpass', f: 500, to: 350, q: 4, dur: n * 0.075 + 0.08, peak: 0.14, a: 0.04 });
  }
}

function (T, out, t, p) {
  const f0 = p.pitch;
  if (p.cure >= 0.5) {
    T.osc(out, t, { f: f0 * 0.66, to: f0 * 1.33, dur: 0.12, peak: 0.09, a: 0.004 });
    T.osc(out, t + 0.06, { type: 'triangle', f: f0 * 1.68, dur: 0.25, peak: 0.065, a: 0.005 });
    T.osc(out, t + 0.1, { type: 'triangle', f: f0 * 2.52, dur: 0.2, peak: 0.04, a: 0.005 });
  } else if (p.tick >= 0.5) {
    // in-breath rasps up, out-breath sinks; a low hum rides the out-breath
    T.noise(out, t, { filter: 'bandpass', f: 300, to: 520, q: 5, dur: 0.2, peak: 0.1 + 0.12 * p.breath, a: 0.12 });
    T.noise(out, t + 0.2, { filter: 'bandpass', f: 440, to: 280, q: 5, dur: 0.3, peak: 0.12 + 0.12 * p.breath, a: 0.08 });
    T.osc(out, t + 0.18, { f: 110, to: 98, dur: 0.34, peak: 0.04, a: 0.08 });
  } else {
    T.osc(out, t, { type: 'triangle', f: f0, dur: 0.3, peak: 0.07, a: 0.03, vib: { rate: 5, depth: 10 } });
    T.osc(out, t + 0.18, { type: 'triangle', f: f0 * 0.75, dur: 0.43, peak: 0.07, a: 0.04, vib: { rate: 5, depth: 10 } });
    T.noise(out, t, { filter: 'lowpass', f: 700, to: 500, q: 1, dur: 0.5, peak: 0.1 * p.breath, a: 0.2 });
  }
}

function (T, out, t, p) {
  const D = p.travel;
  const pw = p.power;
  const L = t + D;
  const mix = T.gain(out, 0.71);  // one trim sets the whole strike to the house level
  const fly = (o) => Object.assign({ a: 0.7 * D, dur: D, tail: 0.3, fade: 0.03 }, o);
  T.noise(mix, t, fly({ filter: 'bandpass', f: 500, to: 2500, q: 1.1, peak: 0.23 }));
  // the impact
  T.osc(mix, L, { f: 236 - 80 * pw, to: 64, dur: 0.11 + 0.09 * pw, peak: 0.24, a: 0.003 });
  T.noise(mix, L, { filter: 'lowpass', f: 2300 - 700 * pw, to: 500, q: 0.9, dur: 0.08 + 0.03 * pw, peak: 0.12, a: 0.003 });
  T.noise(mix, L, { filter: 'highpass', f: 3000, to: 2200, q: 0.8, dur: 0.02, peak: 0.06, a: 0.001 });
  if (p.weak >= 0.5) {
    // the doubled accent: two struck-bell dings a beat apart, bright and clear of the low end
    T.osc(mix, L + 0.03, { type: 'triangle', f: 1245, to: 1180, dur: 0.16, peak: 0.1, a: 0.004 });
    T.osc(mix, L + 0.03, { type: 'triangle', f: 1868, to: 1790, dur: 0.13, peak: 0.06, a: 0.004 });
    T.osc(mix, L + 0.085, { type: 'triangle', f: 2490, to: 2360, dur: 0.11, peak: 0.045, a: 0.004 });
    T.noise(mix, L + 0.03, { filter: 'highpass', f: 5200, to: 3600, q: 0.8, dur: 0.05, peak: 0.05, a: 0.002 });
  }
}

function (T, out, t, p) {
  const D = p.travel;
  const pw = p.power;
  const L = t + D;
  const mix = T.gain(out, 0.7);  // one trim sets the whole strike to the house level
  const fly = (o) => Object.assign({ a: 0.7 * D, dur: D, tail: 0.3, fade: 0.03 }, o);
  T.noise(mix, t, fly({ filter: 'lowpass', f: 1800, to: 250, q: 1.4, peak: 0.11 }));
  T.osc(mix, t, fly({ f: 104, to: 78, peak: 0.064 }));
  T.osc(mix, t, fly({ f: 740, to: 300, vib: { rate: 6, depth: 40 }, peak: 0.016 }));
  // the impact
  T.noise(mix, L, { filter: 'lowpass', f: 1900, to: 170, q: 1.4, dur: 0.18 + 0.08 * pw, peak: 0.17, a: 0.015 });
  T.osc(mix, L, { f: 108 - 32 * pw, to: 52, dur: 0.14 + 0.08 * pw, peak: 0.2, a: 0.004 });
  T.osc(mix, L, { f: 111 - 32 * pw, to: 51, dur: 0.22 + 0.08 * pw, peak: 0.08, a: 0.01 });
  T.osc(mix, L + 0.04, { f: 740, to: 185, vib: { rate: 6, depth: 40 }, dur: 0.22, peak: 0.04, a: 0.03 });
  if (p.weak >= 0.5) {
    // the doubled accent: two struck-bell dings a beat apart, bright and clear of the low end
    T.osc(mix, L + 0.03, { type: 'triangle', f: 1245, to: 1180, dur: 0.16, peak: 0.1, a: 0.004 });
    T.osc(mix, L + 0.03, { type: 'triangle', f: 1868, to: 1790, dur: 0.13, peak: 0.06, a: 0.004 });
    T.osc(mix, L + 0.085, { type: 'triangle', f: 2490, to: 2360, dur: 0.11, peak: 0.045, a: 0.004 });
    T.noise(mix, L + 0.03, { filter: 'highpass', f: 5200, to: 3600, q: 0.8, dur: 0.05, peak: 0.05, a: 0.002 });
  }
}

function (T, out, t, p) {
  const D = p.travel;
  const pw = p.power;
  const L = t + D;
  const mix = T.gain(out, 0.62);  // one trim sets the whole strike to the house level
  const fly = (o) => Object.assign({ a: 0.7 * D, dur: D, tail: 0.3, fade: 0.03 }, o);
  T.noise(mix, t, fly({ filter: 'bandpass', f: 500, to: 1400, q: 1.3, peak: 0.077 }));
  T.osc(mix, t, fly({ f: 92, to: 140, vib: { rate: 9, depth: 25 }, peak: 0.05 }));
  T.osc(mix, t, fly({ f: 222, to: 337, peak: 0.019 }));
