  const f = p.pitch;
  // first strike: the note, a fifth above it and a faint metal partial, falling a little
  T.bell(out, t, {
    type: 'triangle', f, partials: [[1, 1, 1], [1.5, 0.58, 0.8], [2.76, 0.2, 0.4]], drift: 0.95,
    dur: p.ring, peak: 0.085, a: 0.004,
  });
  // second strike an octave up: the "x2"
  T.bell(out, t + p.gap, {
    type: 'triangle', f: f * 2, partials: [[1, 1, 1], [2.76, 0.25, 0.5]], drift: 0.95,
    dur: p.ring * 0.75, peak: 0.055, a: 0.004,
  });
  T.noise(out, t, { filter: 'highpass', f: 5200, to: 3600, q: 0.8, dur: 0.05, peak: 0.07 * p.air, a: 0.002 });
}

function (T, out, t, p) {
  const f = p.pitch * T.rand(0.97, 1.03);
  // the two bands are narrow, so their peaks are high for the level they deliver
  T.noise(out, t, { filter: 'bandpass', f, to: f * 0.93, q: 9, dur: p.ring, peak: 0.25, a: 0.001 });
  T.noise(out, t, { filter: 'bandpass', f: f * 1.62, to: f * 1.5, q: 9, dur: p.ring * 0.7, peak: 0.15, a: 0.001 });
  T.noise(out, t, { filter: 'highpass', f: 3800, to: 2600, q: 0.8, dur: 0.012, peak: 0.024, a: 0.001 });
  T.osc(out, t, { f: 700, to: 380, dur: 0.035, peak: 0.003 + 0.03 * p.weight, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.chips);
  let at = t;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * (1 + 0.025 * k) * T.rand(0.92, 1.08);
    const l = T.rand(0.8, 1.15) * (k === 0 ? 1.2 : 0.9);
    T.noise(out, at, { filter: 'bandpass', f, to: f * 0.93, q: 9, dur: 0.04, peak: 0.2 * l, a: 0.001 });
    T.noise(out, at, { filter: 'bandpass', f: f * 1.62, to: f * 1.5, q: 9, dur: 0.03, peak: 0.115 * l, a: 0.001 });
    T.noise(out, at, { filter: 'highpass', f: 3800, to: 2600, q: 0.8, dur: 0.012, peak: 0.02 * l, a: 0.001 });
    T.osc(out, at, { f: 700, to: 380, dur: 0.03, peak: 0.013 * l, a: 0.002 });
    if (k === n - 1) {
      // the top chip rocks once as it settles
      T.noise(out, at + 0.028, { filter: 'bandpass', f: f * 1.1, to: f, q: 9, dur: 0.025, peak: 0.09, a: 0.001 });
    }
    at += p.pace * T.rand(0.75, 1.3);
  }
}

function (T, out, t, p) {
  const L = p.length;
  const n = Math.round(p.chips);
  T.noise(out, t, { filter: 'bandpass', f: 600, to: 1000, q: 0.8, dur: L + 0.05, peak: 0.015 + 0.1 * p.slide, a: L * 0.5 });
  for (let k = 0; k < n; k++) {
    // three uniform draws averaged: the clicks bunch in the middle of the shove
    const u = (T.rand() + T.rand() + T.rand()) / 3;
    const f = p.pitch * T.rand(0.7, 1.5);
    const l = (0.35 + 0.65 * Math.sin(Math.PI * u)) * T.rand(0.7, 1.2);
    T.noise(out, t + 0.02 + u * (L - 0.05), { filter: 'bandpass', f, to: f * 0.92, q: 9, dur: 0.03, peak: 0.3 * l, a: 0.001 });
  }
  const hit = t + L;
  T.osc(out, hit, { f: 150, to: 70, dur: 0.14, peak: 0.1, a: 0.003 });
  T.noise(out, hit, { filter: 'lowpass', f: 700, to: 250, q: 1, dur: 0.1, peak: 0.08, a: 0.002 });
  const rest = [0.04, 0.1, 0.19, 0.31];
  for (let k = 0; k < rest.length; k++) {
    const f = p.pitch * T.rand(0.8, 1.3);
    T.noise(out, hit + rest[k], { filter: 'bandpass', f, to: f * 0.93, q: 9, dur: 0.035, peak: 0.3 * (0.8 - 0.16 * k), a: 0.001 });
  }
}

function (T, out, t, p) {
  const at = t + p.reach;
  T.noise(out, t, { filter: 'highpass', f: 2600 + 900 * p.tone, to: 1800, q: 0.9, dur: 0.034, peak: 0.037, a: 0.002 });
  T.osc(out, t, { type: 'triangle', f: 460 + 160 * p.tone, to: 260, dur: 0.028, peak: 0.01, a: 0.002 });
  // a wide, slow band: the skim must read as air under the card, never as a hit
  T.noise(out, t + 0.012, {
    filter: 'bandpass', f: 1500 + 1300 * p.tone, to: 650 + 350 * p.tone, q: 1.1,
    dur: p.reach + 0.03, peak: 0.125, a: p.reach * 0.35,
  });
  T.noise(out, at, { filter: 'lowpass', f: 1100, to: 480, q: 1, dur: 0.045, peak: 0.025 + 0.038 * p.land, a: 0.002 });
  T.osc(out, at, { f: 200, to: 118, dur: 0.05, peak: 0.01 + 0.038 * p.land, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  const seat = [1, 0.84, 1.19, 0.92, 1.06, 0.78, 1.28, 0.97];
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const l = 1 - 0.04 * k;
    const f = 200 * (1 + (seat[k] - 1) * p.spread) * T.rand(0.97, 1.03);
    const b = T.rand(0.2, 0.6);
    T.noise(out, at, { filter: 'highpass', f: 2600 + 900 * b, to: 1800, q: 0.9, dur: 0.034, peak: 0.034 * l, a: 0.002 });
    T.noise(out, at + 0.01, { filter: 'bandpass', f: 1900 * seat[k], to: 800, q: 1.1, dur: 0.1, peak: 0.094 * l, a: 0.035 });
    T.noise(out, at + 0.08, { filter: 'lowpass', f: 1100 * seat[k], to: 480, q: 1, dur: 0.045, peak: 0.05 * l, a: 0.002 });
    T.osc(out, at + 0.08, { f, to: f * 0.59, dur: 0.05, peak: 0.038 * l, a: 0.003 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.bounces);
  // gaps shrink by a constant ratio and add up to the length
  let sum = 0;
  for (let k = 0; k < n - 1; k++) sum += Math.pow(0.66, k);
  let at = t;
  for (let k = 0; k < n; k++) {
    const l = Math.pow(0.7, k) * T.rand(0.9, 1.1);
    const f = (1300 + 1900 * p.surface) * T.rand(0.85, 1.2);
    T.noise(out, at, { filter: 'bandpass', f, to: f * 0.7, q: 2, dur: 0.03 + 0.03 * p.surface, peak: 0.12 * l, a: 0.001 });
    T.osc(out, at, { f: (440 + 520 * p.surface) * T.rand(0.9, 1.15), to: 260, dur: 0.04, peak: (0.018 + 0.012 * p.surface) * l, a: 0.001 });
    if (k < n - 1) at += (p.length * Math.pow(0.66, k)) / sum;
  }
  // the die rocks to rest: a few small ticks closing up
  const rock = [0.035, 0.07, 0.095];
  for (let k = 0; k < rock.length; k++) {
    const f = (1500 + 1500 * p.surface) * T.rand(0.85, 1.15);
    T.noise(out, at + rock[k], { filter: 'bandpass', f, q: 2, dur: 0.02, peak: 0.07 * (1 - 0.25 * k), a: 0.001 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.shakes);
  const per = p.length / n;
  // a faint steady rattle of dice sliding over each other, under the clacks
  T.noise(out, t, { filter: 'bandpass', f: 2200 * p.pitch, to: 1800 * p.pitch, q: 0.9, dur: p.length + 0.05, peak: 0.016, a: p.length * 0.4 });
  const many = 4 + 3 * Math.round(p.dice);
  for (let s = 0; s < n; s++) {
    const centre = t + per * (s + 0.5);
    const u = (s + 0.5) / n;
    const swell = 0.45 + 0.55 * Math.sin(Math.PI * u);
    T.noise(out, centre - per * 0.45, { filter: 'lowpass', f: 520, to: 260, q: 1, dur: 0.05, peak: 0.03 * swell, a: 0.004 });
    for (let j = 0; j < many; j++) {
      const at = centre + per * T.rand(-0.42, 0.42);
      const f = 2400 * p.pitch * T.rand(0.7, 1.5);
      const l = swell * T.rand(0.55, 1.15);
      T.noise(out, at, { filter: 'bandpass', f, to: f * 0.8, q: 2.5, dur: 0.02, peak: 0.1 * l, a: 0.001 });
      T.osc(out, at, { f: 900 * p.pitch * T.rand(0.8, 1.3), to: 500 * p.pitch, dur: 0.02, peak: 0.016 * l, a: 0.001 });
    }
  }
}

function (T, out, t, p) {
  const air = 0.03 + 0.1 * p.toss;
  const at = t + 0.02 + 0.1 * p.toss;
  T.noise(out, t, { filter: 'highpass', f: 2700, to: 1800, q: 0.9, dur: 0.03, peak: 0.034, a: 0.002 });
  T.noise(out, t + 0.01, { filter: 'bandpass', f: 1800, to: 700, q: 1.1, dur: air + 0.02, peak: 0.098, a: air * 0.4 });
  const thump = 1 - 0.5 * p.pile;
  T.noise(out, at, { filter: 'lowpass', f: 950, to: 400, q: 1, dur: 0.06, peak: (0.039 + 0.039 * p.weight) * thump, a: 0.002 });
  T.osc(out, at, { f: 175, to: 100, dur: 0.07, peak: (0.013 + 0.052 * p.weight) * thump, a: 0.003 });
  const ticks = 1 + Math.round(4 * p.pile);
  for (let j = 0; j < ticks; j++) {
    T.noise(out, at + 0.006 + j * 0.014, {
      filter: 'bandpass', f: 2300 * T.rand(0.8, 1.4), to: 1400, q: 2, dur: 0.025,
      peak: 0.117 * (0.5 + 0.5 * p.pile) * (1 - 0.14 * j) * T.rand(0.8, 1.2), a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const r = p.reach;
  const end = t + r;
  // the rub swells until the card clears, so the attack takes most of the length
  T.noise(out, t, { filter: 'bandpass', f: 600 + 500 * p.tone, to: 1900 + 1500 * p.tone, q: 1.4, dur: r + 0.02, peak: 0.085, a: r * 0.85 });
  T.noise(out, t, { filter: 'highpass', f: 3600, to: 5200, q: 0.8, dur: r + 0.02, peak: 0.016, a: r * 0.85 });
  T.noise(out, end, { filter: 'highpass', f: 2700 + 900 * p.tone, to: 1900, q: 0.9, dur: 0.03, peak: 0.003 + 0.022 * p.snap, a: 0.002 });
  T.osc(out, end, { type: 'triangle', f: 480 + 140 * p.tone, to: 270, dur: 0.026, peak: 0.002 + 0.007 * p.snap, a: 0.002 });
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  for (let k = 0; k < n; k++) {
    const u = k / (n - 1);
    const f = (1600 + 1800 * p.bright) * (1 + 0.6 * u) * T.rand(0.96, 1.04);
    const l = 0.75 + 0.25 * Math.sin(Math.PI * u);
    T.noise(out, t + p.length * u, { filter: 'bandpass', f, to: f * 0.7, q: 2.8, dur: 0.016, peak: 0.12 * l * T.rand(0.85, 1.15), a: 0.002 });
  }
  T.noise(out, t, { filter: 'bandpass', f: 800 + 400 * p.bright, to: 2600 + 800 * p.bright, q: 0.9, dur: p.length + 0.05, peak: 0.06, a: p.length * 0.45 });
}

function (T, out, t, p) {
  const n = Math.round(p.count);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const l = 1 - 0.06 * k;
    const b = Math.min(1, p.bright + k / 12);
    T.noise(out, at, { filter: 'highpass', f: 2600 + 900 * b, to: 1800, q: 0.9, dur: 0.034, peak: 0.037 * l, a: 0.002 });
    T.osc(out, at, { type: 'triangle', f: 460 + 160 * b, to: 260, dur: 0.028, peak: 0.011 * l, a: 0.002 });
  }
}

function (T, out, t, p) {
  const s = 1 / p.speed;
  const turn = t + 0.07 * s;
  const land = t + 0.15 * s;
  T.noise(out, t, { filter: 'bandpass', f: 1300 + 600 * p.tone, to: 2800 + 800 * p.tone, q: 1.3, dur: 0.07 * s, peak: 0.083, a: 0.03 * s });
  T.noise(out, turn, { filter: 'highpass', f: 2800 + 900 * p.tone, to: 1900, q: 0.9, dur: 0.034, peak: 0.009 + 0.048 * p.snap, a: 0.002 });
  T.osc(out, turn, { type: 'triangle', f: 520 + 160 * p.tone, to: 280, dur: 0.028, peak: 0.005 + 0.015 * p.snap, a: 0.002 });
  T.noise(out, land, { filter: 'lowpass', f: 1300, to: 560, q: 1, dur: 0.04, peak: 0.048, a: 0.002 });
  T.osc(out, land, { f: 220, to: 130, dur: 0.045, peak: 0.033, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  const last = t + (n - 1) * p.gap;
  // one swoosh over the whole sweep: air rising as the hand moves, hushing as the deck is reached
  const air = (n - 1) * p.gap + p.reach + 0.02;
  T.noise(out, t, { filter: 'bandpass', f: 600, to: 2400, q: 0.9, dur: air, peak: 0.085, a: air * 0.3, tail: 0.15 });
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    T.noise(out, at, { filter: 'highpass', f: 2870 * T.rand(0.95, 1.05), to: 1800, q: 0.9, dur: 0.034, peak: 0.032 * (1 - 0.03 * k), a: 0.002 });
    T.osc(out, at, { type: 'triangle', f: 556, to: 260, dur: 0.028, peak: 0.009, a: 0.002 });
  }
  // the deck takes them
  const bump = last + p.reach;
  T.osc(out, bump, { f: 150, to: 80, dur: 0.07, peak: 0.06, a: 0.003 });
  T.noise(out, bump, { filter: 'lowpass', f: 500, to: 250, q: 1, dur: 0.05, peak: 0.045, a: 0.002 });
  const ticks = Math.round(7 * p.riffle);
  for (let k = 0; k < ticks; k++) {
    T.noise(out, bump + 0.03 + k * 0.024, {
      filter: 'bandpass', f: T.rand(1500, 2900), to: 900, q: 2.2, dur: 0.045,
      peak: (k === 0 ? 0.12 : 0.09) * (0.5 + 0.5 * p.riffle) * T.rand(0.8, 1.2), a: 0.003,
    });
  }
}

function (T, out, t, p) {
  const d = Math.round(p.onto);
  const w = 0.6 + 0.8 * p.weight;
  const air = 0.7 + 0.6 * p.tone;
  if (d === 0) {
    // stadium: the body thunk drops lower than a pat, and a wide low breath of paper rides over it
    T.osc(out, t, { f: 96 * (1.2 - 0.3 * p.weight), to: 48, dur: 0.2, peak: 0.06 * w, a: 0.003 });
    T.noise(out, t, { filter: 'lowpass', f: 480 * air, to: 200, q: 1.1, dur: 0.075, peak: 0.05 * w, a: 0.002 });
    T.noise(out, t, { filter: 'bandpass', f: 1500 * air, to: 500, q: 1, dur: 0.07, peak: 0.055 * w, a: 0.004 });
  } else if (d === 1) {
    // tool: a quick pat, then the clink one beat later: a bell with the struck-metal partials
    T.noise(out, t, { filter: 'lowpass', f: 1000 * air, to: 400, q: 1, dur: 0.04, peak: 0.04 * w, a: 0.002 });
    T.osc(out, t, { f: 300, to: 180, dur: 0.05, peak: 0.03 * w, a: 0.003 });
    T.bell(out, t + 0.012, { f: 2100 * air, partials: [[1, 1, 1], [2.76, 0.5, 0.65], [5.4, 0.2, 0.3]], dur: 0.2, peak: 0.032 * (0.7 + 0.3 * w), a: 0.001 });
    T.noise(out, t + 0.012, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: 0.012, a: 0.001 });
  } else {
    // discard: a duller pat, then the pile shifting under it
    T.noise(out, t, { filter: 'lowpass', f: 1000 * air, to: 430, q: 1, dur: 0.05, peak: 0.07 * w, a: 0.002 });
    T.osc(out, t, { f: 190, to: 108, dur: 0.06, peak: 0.05 * w, a: 0.003 });
    for (let j = 0; j < 2; j++) {
      T.noise(out, t + 0.012 + j * 0.016, {
        filter: 'bandpass', f: 2300 * air * T.rand(0.85, 1.25), to: 1400, q: 2, dur: 0.022, peak: 0.1 * (1 - 0.3 * j) * T.rand(0.8, 1.2), a: 0.002,
      });
    }
  }
}

function (T, out, t, p) {
  const lift = p.lift;
  const down = t + 0.012 + lift + p.hold;
  // the thumb catches the corner
  T.noise(out, t, { filter: 'highpass', f: 3000, to: 2200, q: 0.8, dur: 0.014, peak: 0.01, a: 0.002 });
  // the corner rises off the felt
  T.noise(out, t + 0.012, { filter: 'bandpass', f: 800 + 400 * p.tone, to: 2000 + 900 * p.tone, q: 1.4, dur: lift, peak: 0.07, a: lift * 0.75 });
  // fine creaks while it bends, spread over the lift, climbing a little
  const creaks = Math.round(1 + 4 * p.creak);
  for (let k = 0; k < creaks; k++) {
    const u = (k + 0.5) / creaks;
    T.noise(out, t + 0.012 + lift * u * T.rand(0.8, 1), {
      filter: 'bandpass', f: (1900 + 700 * u + 500 * p.tone) * T.rand(0.9, 1.1), to: 1500, q: 3, dur: 0.014,
      peak: (0.03 + 0.1 * p.creak) * T.rand(0.7, 1.15), a: 0.002,
    });
  }
  // the corner lets go
  T.noise(out, down, { filter: 'highpass', f: 2500 + 600 * p.tone, to: 1700, q: 0.9, dur: 0.03, peak: 0.02, a: 0.002 });
  T.noise(out, down + 0.008, { filter: 'lowpass', f: 900, to: 400, q: 1, dur: 0.04, peak: 0.03, a: 0.002 });
  T.osc(out, down + 0.008, { f: 200, to: 120, dur: 0.05, peak: 0.022, a: 0.003 });
}

function (T, out, t, p) {
  const hard = 0.6 + 0.4 * p.force;
  T.bell(out, t, {
    f: p.pitch, partials: [[1, 1, 1], [2.45, 0.5, 0.55], [4.3, 0.2, 0.3]], dur: 0.12, peak: 0.048 * hard, a: 0.001,
  });
  T.bell(out, t + 0.003, {
    f: p.pitch * 1.19, partials: [[1, 1, 1], [2.45, 0.4, 0.5]], dur: 0.1, peak: 0.032 * hard, a: 0.001,
  });
  T.noise(out, t, { filter: 'bandpass', f: 2400 + 800 * p.force, to: 1800, q: 1.4, dur: 0.018, peak: 0.096 * hard, a: 0.001 });
  T.osc(out, t, { f: 160, to: 80, dur: 0.06, peak: 0.016 + 0.016 * p.force, a: 0.002 });
  const taps = 1 + Math.round(2 * p.scatter);
  let at = t + 0.075;
  for (let k = 0; k < taps; k++) {
    const l = Math.pow(0.6, k);
    T.bell(out, at, {
      f: p.pitch * 0.8 * Math.pow(0.92, k) * T.rand(0.95, 1.05),
      partials: [[1, 1, 1], [2.45, 0.35, 0.5]], dur: 0.09, peak: 0.04 * l, a: 0.001,
    });
    T.noise(out, at, { filter: 'bandpass', f: 1700, to: 1200, q: 1.4, dur: 0.012, peak: 0.06 * l, a: 0.001 });
    at += (0.08 + 0.07 * p.scatter) * T.rand(0.8, 1.2) * (1 - 0.12 * k);
  }
}

function (T, out, t, p) {
  const at = t + p.slide;
  if (p.slide > 0.015) {
    T.noise(out, t, { filter: 'bandpass', f: 800 + p.pitch * 0.5, to: 600 + p.pitch * 0.4, q: 1.2, dur: p.slide + 0.01, peak: 0.05, a: p.slide * 0.5 });
  }
  T.bell(out, at, {
    f: p.pitch * T.rand(0.98, 1.02),
    partials: [[1, 1, 1], [2.45, 0.25 + 0.4 * p.hollow, 0.55], [4.3, 0.08 * p.hollow, 0.3]],
    dur: 0.09, peak: 0.036, a: 0.001,
  });
  T.noise(out, at, { filter: 'bandpass', f: 1500 + p.pitch, to: 1100, q: 1.5, dur: 0.012, peak: 0.05, a: 0.001 });
  T.osc(out, at, { f: 150, to: 85, dur: 0.045, peak: 0.014, a: 0.002 });
}

function (T, out, t, p) {
  const f = 700 + 900 * p.tone;
  if (p.drop > 0.02) {
    T.noise(out, t, { filter: 'highpass', f: 2800, to: 2000, q: 0.9, dur: 0.02, peak: 0.004 + 0.04 * p.drop, a: 0.002 });
  }
  const at = t + 0.012 * p.drop;
  T.noise(out, at, { filter: 'lowpass', f, to: f * 0.44, q: 1, dur: 0.045, peak: 0.05 + 0.033 * p.weight, a: 0.002 });
  T.osc(out, at, { f: 200 - 30 * p.weight, to: 118 - 18 * p.weight, dur: 0.055, peak: 0.016 + 0.065 * p.weight, a: 0.003 });
}

function (T, out, t, p) {
  const k = Math.round(p.kind);
  const hit = (0.65 + 0.5 * p.force) * 0.83;
  const air = 0.7 + 0.6 * p.tone;
  // the slap itself: [body Hz, noise cutoff Hz, level] per kind, from soft and high (item) to
  // low and broad (stadium, ace)
  const spec = [[240, 3400, 0.05], [170, 2400, 0.056], [110, 1600, 0.06], [210, 3000, 0.046], [95, 2000, 0.068]][k];
  const body = spec[0];
  const cut = spec[1] * air;
  const l = spec[2] * hit;
  T.osc(out, t, { f: body, to: body * 0.5, dur: 0.075, peak: l, a: 0.002 });
  T.noise(out, t, { filter: 'lowpass', f: cut, to: cut * 0.4, q: 1, dur: 0.055, peak: 0.9 * l, a: 0.002 });
  T.noise(out, t, { filter: 'highpass', f: 3200, to: 2400, q: 0.8, dur: 0.022, peak: 0.35 * l, a: 0.001 });
  const r = p.ring;
  if (k === 0) {
    // item: one small bright tick on top
    T.osc(out, t, { type: 'triangle', f: 1400, to: 1300, dur: 0.04 * r, peak: 0.01, a: 0.002 });
  } else if (k === 1) {
    // supporter: a warm major third rings under the slap
    T.osc(out, t + 0.02, { type: 'triangle', f: 392, dur: 0.22 * r, peak: 0.013, a: 0.01 });
    T.osc(out, t + 0.02, { type: 'triangle', f: 493.9, dur: 0.22 * r, peak: 0.011, a: 0.01 });
  } else if (k === 2) {
    // stadium: a wide low breath of air as the big card fills the table
    T.noise(out, t, { filter: 'bandpass', f: 300, to: 900, q: 1, dur: 0.3 * r, peak: 0.03, a: 0.05 });
  } else if (k === 3) {
    // tool: a small metal clip at the corner (inharmonic partials)
    const c = 2400 * air;
    T.osc(out, t + 0.03, { f: c, to: c * 0.98, dur: 0.12 * r, peak: 0.016, a: 0.002 });
    T.osc(out, t + 0.03, { f: c * 2.76, to: c * 2.7, dur: 0.08 * r, peak: 0.008, a: 0.002 });
    T.noise(out, t + 0.03, { filter: 'highpass', f: 4200, to: 3000, q: 0.8, dur: 0.02, peak: 0.01, a: 0.001 });
  } else {
    // ace: a sub under the slap, then a rising flash of three high notes and a veil of air
    T.osc(out, t, { f: 70, to: 40, dur: 0.3, peak: 0.04, a: 0.004 });
    const flash = [1318.5, 1975.5, 2637];
    for (let j = 0; j < flash.length; j++) {
      T.osc(out, t + 0.04 + 0.04 * j, { type: 'triangle', f: flash[j], dur: 0.4 * r, peak: 0.016, a: 0.01 });
    }
    T.noise(out, t + 0.04, { filter: 'highpass', f: 6000, to: 7000, q: 0.8, dur: 0.3 * r, peak: 0.012, a: 0.05 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  for (let k = 0; k < n; k++) {
    T.noise(out, t + k * p.gap, {
      filter: 'bandpass', f: p.pitch * T.rand(1, 1.93), to: p.pitch * 0.6, q: 2.2,
      dur: 0.045, peak: (k === 0 ? 0.135 : 0.104) * T.rand(0.75, 1.25), a: 0.003,
    });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.chunks);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.pace;
    const ticks = Math.max(3, 7 - k);
    const l = 1 - 0.05 * k;
    for (let j = 0; j < ticks; j++) {
      T.noise(out, at + j * 0.009, {
        filter: 'bandpass', f: p.pitch * T.rand(0.85, 1.7), to: p.pitch * 0.6, q: 1.8,
        dur: 0.03, peak: (j === 0 ? 0.125 : 0.095) * l * T.rand(0.75, 1.2), a: 0.002,
      });
    }
    // the hand shifting under the chunk
    T.noise(out, at, { filter: 'lowpass', f: 700, to: 350, q: 1, dur: 0.05, peak: 0.02 * l, a: 0.004 });
  }
  const end = t + n * p.pace + 0.04;
  T.noise(out, end, { filter: 'lowpass', f: 1000, to: 450, q: 1, dur: 0.05, peak: 0.01 + 0.04 * p.square, a: 0.002 });
  T.osc(out, end, { f: 190, to: 110, dur: 0.06, peak: 0.003 + 0.03 * p.square, a: 0.003 });
}

function (T, out, t, p) {
  const L = p.length;
  const from = p.pitch * (1000 - 650 * p.rise);
  const to = p.pitch * (350 + 650 * p.rise);
  // eased in, held, eased out: a sustained envelope, so the glide stays audible for its whole length
  T.noise(out, t, { filter: 'bandpass', f: from, to, q: 1.1, dur: L, peak: 0.16, a: Math.min(0.07, L * 0.3), s: 0.7, d: 0.05, r: Math.min(0.1, L * 0.4) });
  const grains = Math.round(p.grit * L * 60);
  for (let k = 0; k < grains; k++) {
    T.noise(out, t + T.rand(0.01, L - 0.03), { filter: 'bandpass', f: 3200 * p.pitch * T.rand(0.8, 1.3), q: 2.5, dur: 0.012, peak: 0.05, a: 0.002 });
  }
}

function (T, out, t, p) {
  const s = 1 / p.speed;
  const tap = p.on >= 0.5;
  const turn = 0.1 * s;
  const lo = 650 + 400 * p.tone;
  const hi = 1700 + 900 * p.tone;
  // the corner lifts
  T.noise(out, t, { filter: 'highpass', f: 3000, to: 2200, q: 0.8, dur: 0.016, peak: tap ? 0.018 : 0.011, a: 0.002 });
  // the drag: rises as the card turns over to its side, falls as it turns back
  T.noise(out, t + 0.012, { filter: 'bandpass', f: tap ? lo : hi, to: tap ? hi : lo, q: 1.3, dur: turn, peak: tap ? 0.1 : 0.08, a: turn * 0.45 });
  // the settle
  const at = t + 0.012 + turn;
  const h = tap ? 0.3 + 0.7 * p.weight : 0.15 + 0.45 * p.weight;
  T.noise(out, at, { filter: 'lowpass', f: tap ? 1000 : 1300, to: tap ? 450 : 600, q: 1, dur: 0.04, peak: 0.07 * h, a: 0.002 });
  T.osc(out, at, { f: tap ? 190 : 230, to: tap ? 110 : 140, dur: 0.05, peak: 0.075 * h, a: 0.003 });
  // the corner touching down, or the card squaring up
  T.noise(out, at - 0.004, { filter: 'bandpass', f: 2200 + 400 * p.tone, q: 2.5, dur: 0.012, peak: 0.04 * (0.5 + 0.5 * h), a: 0.001 });
  if (!tap) T.noise(out, at + 0.035, { filter: 'bandpass', f: 2600, to: 2000, q: 2.5, dur: 0.012, peak: 0.03 * h + 0.012, a: 0.001 });
}

function (T, out, t, p) {
  const n = Math.round(p.beats);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const f = p.pitch * (k % 2 ? 0.76 : 1);
    // tone fades from a soft wooden knock to a crisp click
    T.noise(out, at, { filter: 'bandpass', f: f * 2, to: f * 1.5, q: 3, dur: 0.016, peak: 0.04 + 0.12 * p.tone, a: 0.001 });
    T.osc(out, at, { f, to: f * 0.8, dur: 0.035, peak: 0.02 + 0.014 * (1 - p.tone), a: 0.001 });
  }
}

function (T, out, t, p) {
  const F = p.flight;
  const fly = T.pan(out, t, { x: -0.7 * p.arc, to: 0.7 * p.arc, dur: F + 0.1 });
  // the flick
  T.noise(out, t, { filter: 'highpass', f: 3000, to: 1800, q: 0.9, dur: 0.034, peak: 0.037, a: 0.002 });
  T.osc(out, t, { type: 'triangle', f: 520, to: 260, dur: 0.028, peak: 0.011, a: 0.002 });
  // puff times: the gaps stretch by 1.3x over the flight and add up to it
  const n = Math.max(3, Math.round(F * p.spin * 0.8));
  let sum = 0;
  for (let k = 0; k < n; k++) sum += 1 + 1.3 * (k / n);
  let at = t + 0.025;
  for (let k = 0; k < n; k++) {
    const u = k / (n - 1);
    const f = (1500 + 1900 * p.tone) * (1.25 - 0.55 * u) * T.rand(0.93, 1.07);
    const l = (0.45 + 0.55 * Math.sin(Math.PI * (0.1 + 0.8 * u))) * T.rand(0.85, 1.1);
    T.noise(fly, at, { filter: 'bandpass', f, to: f * 0.8, q: 1.5, dur: 0.04, peak: 0.095 * l, a: 0.01 });
    at += ((1 + 1.3 * (k / n)) / sum) * F * 0.95;
  }
  // down it comes: a skid, then a soft pat
  const land = t + 0.025 + F;
  T.noise(fly, land, { filter: 'bandpass', f: 1300, to: 550, q: 1.1, dur: 0.07, peak: 0.07, a: 0.01 });
  T.noise(out, land + 0.02, { filter: 'lowpass', f: 1000, to: 450, q: 1, dur: 0.045, peak: 0.055, a: 0.002 });
  T.osc(out, land + 0.02, { f: 195, to: 115, dur: 0.055, peak: 0.045, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.strokes);
  const L = p.length;
  const step = L / n;
  const len = step * 1.8;
  const hands = [T.pan(out, t, { x: -0.45 }), T.pan(out, t, { x: 0.45 })];
  const mid = 800 + 700 * p.tone;
  for (let k = 0; k < n; k++) {
    const up = k % 4 < 2;
    const f = mid * T.rand(0.85, 1.15);
    const l = 0.75 + 0.25 * Math.sin(Math.PI * (k + 0.5) / n);
    T.noise(hands[k % 2], t + k * step, {
      filter: 'bandpass', f: up ? f * 0.65 : f * 1.4, to: up ? f * 1.4 : f * 0.65, q: 0.9,
      dur: len, peak: 0.11 * l * T.rand(0.85, 1.1), a: len * 0.35, s: 0.35, d: len * 0.2, r: len * 0.35,
    });
  }
  // the felt under the cards, and the grit between them (one scatter per hand)
  T.noise(out, t, { filter: 'bandpass', f: 420, to: 650, q: 0.7, dur: L + step * 0.8, peak: 0.03, a: L * 0.4 });
  const rate = 15 + 110 * p.grit;
  for (let h = 0; h < 2; h++) {
    T.crackle(hands[h], t, { dur: L + step * 0.6, rate, f: 2800 + 800 * p.tone, spread: 0.5, q: 2, len: 0.008, peak: 0.07 * p.grit + 0.01, vary: 0.7 });
  }
}

function (T, out, t, p) {
  const f2 = p.pitch * Math.pow(2, p.interval / 12);
  const mallet = (at, f, dur, peak) => {
    T.bell(out, at, { f, partials: [[1, 1, 1], [3.9, 0.12 + 0.22 * p.bright, 0.3], [9.2, 0.05 * p.bright, 0.12]], dur, peak, a: 0.006 });
  };
  mallet(t, p.pitch, p.ring * 0.8, 0.07);
  mallet(t + 0.13, f2, p.ring, 0.075);
  T.noise(out, t, { filter: 'lowpass', f: 1000, to: 450, q: 1, dur: 0.04, peak: 0.02, a: 0.002 });
}

function (T, out, t, p) {
  const W = p.wind;
  const snap = t + W;
  // 1. the card rises: air gathering upward, with a faint rising tone inside it
  T.noise(out, t, { filter: 'bandpass', f: 420, to: 4200, q: 1.2, dur: W + 0.02, peak: 0.1, a: W * 0.85 });
  T.osc(out, t, { type: 'triangle', f: 300, to: 900, dur: W + 0.02, peak: 0.024, a: W * 0.85 });
  // 2. the pop: a noise snap with a dull body, and a glass ring that grows with flash
  T.noise(out, snap, { filter: 'highpass', f: 3600, to: 2400, q: 0.8, dur: 0.03, peak: 0.03 + 0.07 * p.flash, a: 0.002 });
  T.osc(out, snap, { f: 330, to: 170, dur: 0.07, peak: 0.07, a: 0.003 });
  T.bell(out, snap, { f: 1760, partials: [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34]], dur: 0.32, peak: 0.05 * p.flash, a: 0.002 });
  // 3. the pulse: a narrow band of air that travels across the table, left to right
  const sw = T.pan(out, snap, { x: -0.8, to: 0.8, dur: 0.3 });
  T.noise(sw, snap + 0.02, { filter: 'bandpass', f: 2600, to: 900, q: 3, dur: 0.28, peak: 0.12 * p.pulse, a: 0.05, s: 0.5, d: 0.08, r: 0.12 });
  T.osc(sw, snap + 0.02, { f: 520, to: 330, dur: 0.28, peak: 0.03 * p.pulse, a: 0.05, s: 0.5, d: 0.08, r: 0.12 });
  // 4. the spent card is flicked onto the discard pile: paper tick, falling tick, low bump
  const down = snap + 0.27;
  T.noise(out, down, { filter: 'highpass', f: 3000, to: 1800, q: 0.9, dur: 0.034, peak: 0.04, a: 0.002 });
  T.osc(out, down, { type: 'triangle', f: 480, to: 260, dur: 0.03, peak: 0.012, a: 0.002 });
  T.osc(out, down + 0.05, { f: 140, to: 90, dur: 0.08, peak: 0.05, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.count);
  const steps = [0, 4, 7, 12];
  const wood = [[1, 1, 1], [2, 0.22, 0.4], [3.76, 0.14, 0.22]];
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const last = k === n - 1;
    const side = T.pan(out, at, { x: n > 1 ? -0.35 + (0.7 * k) / (n - 1) : 0 });
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    T.bell(side, at, { f, partials: wood, dur: 0.1, peak: 0.075, a: 0.001 });
    T.noise(side, at, { filter: 'bandpass', f: 2400 + f, q: 2, dur: 0.01, peak: 0.06, a: 0.001 });
    T.bell(side, at + 0.035, {
      f: f * 3, partials: [[1, 1, 1], [2.32, 0.3, 0.5]], dur: last ? 0.4 : 0.14,
      peak: (last ? 0.04 : 0.028) * p.ping, a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const F = p.fall;
  const glass = [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34], [6.63, 0.09, 0.2]];
  const room = T.reverb(out, t, { time: 0.6, mix: 0.12, tone: 0.55 });
  // the crack: bursts of high noise, quick and uneven, that tighten into the break
  T.crackle(room, t, { dur: 0.22, rate: 45 + 40 * p.shatter, f: 4200, to: 6500, spread: 0.5, q: 1.5, len: 0.005, peak: 0.045 + 0.055 * p.shatter, vary: 0.6 });
  // the break: a glass ring that sinks in pitch as the card falls
  const br = t + 0.2;
  T.bell(room, br, { f: 2200, partials: glass, drift: 0.62, dur: 0.45, peak: 0.012 + 0.055 * p.shatter, a: 0.001 });
  T.noise(room, br, { filter: 'highpass', f: 3500, to: 2000, q: 0.8, dur: 0.05, peak: 0.03 + 0.068 * p.shatter, a: 0.001 });
  // grey dust sifting down: a band of noise that sinks as far as the fall is long
  T.noise(room, br, { filter: 'bandpass', f: 5500, to: 300, q: 1.1, dur: F, peak: 0.11, a: 0.03, glide: F * 0.9 });
  // shards tinkling off the edge of the card, each lower and quieter than the last
  for (let k = 0; k < 4; k++) {
    const at = br + 0.08 + k * 0.07 + T.rand(0, 0.03);
    T.osc(room, at, { f: T.rand(3200, 5200) * (1 - 0.1 * k), dur: 0.09, peak: 0.016 * p.shatter * (1 - 0.18 * k), a: 0.002 });
  }
  // the card settles: a low thump just as the dust finishes sinking
  T.osc(room, br + F * 0.55, { f: 120, to: 46, dur: 0.2, peak: 0.12 * p.thump, a: 0.004 });
}

function (T, out, t, p) {
  const S = p.slide;
  // the wide card slides in: a low breathy sweep that swells and settles, a deep tone beneath
  T.noise(out, t, { filter: 'bandpass', f: 220, to: 720, q: 1, dur: S, peak: 0.16, a: S * 0.55, s: 0.6, d: 0.05, r: S * 0.3 });
  T.osc(out, t, { f: 80, to: 130, dur: S, peak: 0.05, a: S * 0.55, s: 0.6, d: 0.05, r: S * 0.3 });
  // the banner unrolls: two cloth flaps, the second lower and softer, each a lowpassed puff
  const f1 = t + S * 0.7;
  T.noise(out, f1, { filter: 'bandpass', f: 800, to: 380, q: 2.4, dur: 0.1, peak: 0.4 * p.cloth, a: 0.012 });
  T.noise(out, f1 + 0.12, { filter: 'bandpass', f: 600, to: 300, q: 2.4, dur: 0.1, peak: 0.3 * p.cloth, a: 0.012 });
  // the gold chime for the lore it pays: two glass partials, a fourth apart in pitch
  const at = f1 + 0.22;
  const glass = [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34]];
  T.bell(out, at, { f: 1568, partials: glass, dur: 0.32, peak: 0.05 * p.chime, a: 0.002 });
  T.bell(out, at + 0.07, { f: 2093, partials: glass, dur: 0.3, peak: 0.05 * p.chime, a: 0.002 });
}

function (T, out, t, p) {
  const w = p.weight;
  // the landing: a lowpassed pat over a short thump, both dulled so the card sounds damp
  T.noise(out, t, { filter: 'lowpass', f: 1100, to: 280, q: 1, dur: 0.06, peak: 0.09 + 0.06 * w, a: 0.002 });
  T.osc(out, t, { f: 190 - 30 * w, to: 100 - 15 * w, dur: 0.075, peak: 0.03 + 0.08 * w, a: 0.003 });
  // beads falling off the wet card, each a small bent plink, a little quieter than the last
  const n = Math.round(p.beads);
  for (let k = 0; k < n; k++) {
    const f = T.rand(650, 1250);
    T.osc(out, t + 0.07 + k * 0.065 + T.rand(0, 0.02), { f, to: f * 1.45, glide: 0.025, dur: 0.07, peak: 0.032 * (1 - 0.12 * k), a: 0.002 });
  }
  // drying: the colour floods in, two soft tones opening behind a lowpass
  const dry = t + 0.2;
  const lp = T.filter(out, dry, { type: 'lowpass', f: 420, to: 4200, dur: 0.4, q: 1.2 });
  T.osc(lp, dry, { type: 'triangle', f: 784, dur: 0.5, peak: 0.036 * p.dry, a: 0.2, s: 0.7, d: 0.08, r: 0.2 });
  T.osc(lp, dry, { f: 1175, dur: 0.5, peak: 0.024 * p.dry, a: 0.22, s: 0.7, d: 0.08, r: 0.2 });
  T.bell(out, dry + 0.25, { f: 3136, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.25, peak: 0.016 * p.dry, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.notes);
  const ladder = [0, 4, 7, 12];
  const gap = 0.15;
  const room = T.reverb(out, t, { time: 0.9, mix: 0.2, tone: 0.45 });
  // vowel "ah": three formant bands (Hz, Q, level) that every voice is filtered through
  const bands = [[720, 3, 0.1], [1100, 4, 0.08], [2500, 6, 0.04]];
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const f = p.pitch * Math.pow(2, ladder[k] / 12);
    const len = k === n - 1 ? 0.5 : 0.3;
    // a gentle lowpass keeps the saws from buzzing: the vowel sits in the formants, not the top
    const soft = T.filter(room, at, { type: 'lowpass', f: 3200, q: 0.7 });
    const voice = T.bus(soft, at, { peak: 1, a: 0.04, dur: len, s: 0.85, d: 0.06, r: 0.12 });
    for (const b of bands) {
      const fl = T.filter(voice, at, { type: 'bandpass', f: b[0], q: b[1] });
      for (const d of [-9, 9]) {
        T.osc(fl, at, { type: 'sawtooth', f: f * 0.97, to: f, glide: 0.05, dur: len, peak: b[2] * 0.5, a: 0.03, s: 1, d: 0.01, r: 0.06, detune: d, vib: { rate: 5.5, depth: 12 } });
      }
    }
    // breath: a little air on the vowel
    T.noise(voice, at, { filter: 'bandpass', f: 1500, q: 1.2, dur: len, peak: 0.07 * p.breath, a: 0.05, s: 1, d: 0.01, r: 0.06 });
  }
  // where the song lights up: a glass bell three octaves above the root
  const lit = t + (n - 1) * gap + 0.07;
  T.bell(room, lit, { f: p.pitch * 8, partials: [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34]], dur: 0.6, peak: 0.06 * p.shine, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  const tones = [0, 7, 12, 16, 19];
  const last = t + (n - 1) * p.gap;
  const end = last + 0.55;
  const room = T.reverb(out, t, { time: 0.8, mix: 0.18, tone: 0.55 });
  // each voice is a little quieter when more of them sing, so five singers do not clip a chord of two
  const v = 0.075 / Math.sqrt(n);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const f = p.pitch * Math.pow(2, tones[k] / 12);
    // the card tilts and its cost pip counts up
    T.tick(room, at, { f: 1500, q: 2, dur: 0.014, peak: 0.03, blip: 520, blipTo: 400, blipType: 'triangle', blipDur: 0.05, blipPeak: 0.02 });
    T.bell(room, at, { f: f * 8, partials: [[1, 1, 0.5], [2.32, 0.3, 0.3]], dur: 0.14, peak: 0.02, a: 0.002 });
    // the voice joins the held chord: two detuned sines and a faint octave
    for (const d of [-7, 7]) {
      T.osc(room, at, { f, dur: end - at, peak: v * 0.5, a: 0.05, s: 0.9, d: 0.05, r: 0.28, detune: d });
    }
    T.osc(room, at, { type: 'triangle', f: f * 2, dur: end - at, peak: v * 0.25, a: 0.06, s: 0.9, d: 0.05, r: 0.28 });
  }
  // the threshold is met: a swell of air and a glass bell at the top of the stack
  T.noise(room, last + 0.05, { filter: 'highpass', f: 5000, to: 8500, q: 0.8, dur: 0.4, peak: 0.03 * p.shine, a: 0.1 });
  T.bell(room, last + p.gap * 0.8, { f: p.pitch * 16, partials: [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34]], dur: 0.6, peak: 0.055 * p.shine, a: 0.003 });
}

function (T, out, t, p) {
  const hit = t + 0.14;
  const ring = [[1, 1, 1], [2.32, 0.6, 0.55], [4.25, 0.35, 0.35], [6.63, 0.15, 0.2]];
  // the lunge: a rush of air that climbs into the contact
  T.noise(out, t, { filter: 'bandpass', f: 500, to: 3200, q: 1.2, dur: 0.15, peak: 0.1, a: 0.1 });
  // the clunk: a low thump, a dull crack and a short bright edge
  T.osc(out, hit, { f: 170, to: 62, dur: 0.12, peak: 0.03 + 0.055 * p.force, a: 0.003 });
  T.noise(out, hit, { filter: 'bandpass', f: 1500, to: 800, q: 1.4, dur: 0.06, peak: 0.065 + 0.045 * p.force, a: 0.001 });
  T.noise(out, hit, { filter: 'highpass', f: 3500, to: 2500, q: 0.8, dur: 0.025, peak: 0.035 + 0.03 * p.force, a: 0.001 });
  // the cold ring: two bodies a third apart, the second a touch later and shorter
  T.bell(out, hit, { f: p.pitch, partials: ring, drift: 0.995, dur: 0.24, peak: 0.02 + 0.016 * p.force, a: 0.001 });
  T.bell(out, hit + 0.006, { f: p.pitch * 1.26, partials: ring, drift: 0.995, dur: 0.2, peak: 0.015 + 0.012 * p.force, a: 0.001 });
  // both cards take their counters at once: a dry tick in each ear
  const l = T.pan(out, hit, { x: -0.7 });
  const r = T.pan(out, hit, { x: 0.7 });
  T.tick(l, hit + 0.09, { f: 2300, q: 2, dur: 0.013, peak: 0.15 * p.damage, blip: 700, blipTo: 520, blipDur: 0.03, blipPeak: 0.045 * p.damage });
  T.tick(r, hit + 0.09, { f: 1850, q: 2, dur: 0.013, peak: 0.15 * p.damage, blip: 620, blipTo: 470, blipDur: 0.03, blipPeak: 0.045 * p.damage });
}

function (T, out, t, p) {
  const R = p.speed;
  // the dash: a band of noise rushing upward with a thin rising tone under it
  T.noise(out, t, { filter: 'bandpass', f: 500, to: 5200, q: 1.5, dur: R, peak: 0.105, a: R * 0.85 });
  T.osc(out, t, { type: 'sawtooth', f: 260, to: 1100, dur: R, peak: 0.016, a: R * 0.85, lp: 1800 });
  // the snap where the dash ends
  const s = t + R;
  T.noise(out, s, { filter: 'highpass', f: 2600, q: 0.8, dur: 0.02, peak: 0.026 + 0.05 * p.snap, a: 0.001 });
  T.osc(out, s, { f: 200, to: 85, dur: 0.07, peak: 0.013 + 0.026 * p.snap, a: 0.002 });
  // the tether goes taut: a plucked string and a small bent twang
  T.pluck(out, s, { f: p.tension, dur: 0.24, bright: 0.75, tone: 0.85, peak: 0.04 });
  T.osc(out, s, { type: 'triangle', f: p.tension * 1.08, to: p.tension, dur: 0.12, peak: 0.012, a: 0.003, vib: { rate: 9, depth: 25 } });
}

function (T, out, t, p) {
  const ex = Math.round(p.on) === 1;
  const L = p.turn;
  const w = p.weight;
  // the slide: a breathy band falling (the card dims) or rising (it brightens)
  const f0 = ex ? 1250 + 700 * p.tone : 520 + 300 * p.tone;
  const f1 = ex ? 460 + 200 * p.tone : 1450 + 900 * p.tone;
  T.noise(out, t, { filter: 'bandpass', f: f0, to: f1, q: 1.1, dur: L + 0.02, peak: 0.1, a: L * 0.45 });
  // the knock as the card settles on its side or on its feet
  const at = t + L;
  T.osc(out, at, { f: ex ? 190 : 270, to: ex ? 108 : 190, dur: 0.075, peak: 0.02 + 0.06 * w, a: 0.003 });
  T.noise(out, at, { filter: 'lowpass', f: (ex ? 800 : 1500) + 500 * p.tone, to: 300, q: 0.9, dur: 0.045, peak: 0.04 + 0.05 * w, a: 0.002 });
  if (!ex) {
    // readied: the face catches the light, a thin glass tip
    T.bell(out, at + 0.01, { f: 2093, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.16, peak: 0.022, a: 0.002 });
  }
}

function (T, out, t, p) {
  const f = p.pitch * T.rand(0.97, 1.03);
  // the thud: a falling knock and a woody band of noise
  T.osc(out, t, { f: f * 1.55, to: f * 0.6, dur: 0.075, peak: 0.023 + 0.04 * p.weight, a: 0.002 });
  T.noise(out, t, { filter: 'bandpass', f: 520 + f * 3, to: 380 + f * 1.5, q: 1.1, dur: 0.05, peak: 0.052 + 0.048 * p.weight, a: 0.001 });
  // the crack where the blow lands
  T.noise(out, t, { filter: 'highpass', f: 3000, to: 2200, q: 0.8, dur: 0.012, peak: 0.026 + 0.026 * p.weight, a: 0.001 });
  // the metal ring: struck metal partials, longer as the ring knob rises
  const metal = [[1, 1, 1], [2.76, 0.55, 0.6], [5.4, 0.3, 0.35]];
  T.bell(out, t + 0.004, { f: f * 7, partials: metal, dur: 0.06 + 0.2 * p.ring, peak: 0.004 + 0.03 * p.ring, a: 0.001 });
}

function (T, out, t, p) {
  const hits = Math.round(p.hits);
  // the action pings the exerted target: a bright glass ping and a quick zip of ray
  T.bell(out, t, { f: 2600, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.3, peak: 0.035, a: 0.002 });
  T.noise(out, t, { filter: 'bandpass', f: 1800, to: 6000, q: 2, dur: 0.07, peak: 0.04, a: 0.01 });
  // the two ready characters cannot be touched: dull, closed taps
  for (let k = 0; k < 2; k++) {
    T.osc(out, t + 0.09 + k * 0.08, { type: 'triangle', f: 170 - 20 * k, to: 110, dur: 0.05, peak: 0.03, a: 0.003 });
  }
  // the reticle locks on: dry ticks that speed up, then a small bright click
  const lock = [0.14, 0.25, 0.34, 0.41, 0.46];
  for (let k = 0; k < lock.length; k++) {
    T.tick(out, t + lock[k], { f: 2200 + 180 * k, q: 3, dur: 0.012, peak: 0.05, blip: 1300 + 110 * k, blipPeak: 0.014, blipDur: 0.02 });
  }
  T.osc(out, t + 0.5, { f: 1900, dur: 0.05, peak: 0.02, a: 0.003 });
  // the chain: each attacker whooshes in and strikes, a step higher, then two damage ticks land
  const metal = [[1, 1, 1], [2.76, 0.7, 0.7], [5.4, 0.45, 0.45], [8.93, 0.25, 0.25]];
  const c0 = t + 0.64;
  for (let k = 0; k < hits; k++) {
    const at = c0 + k * p.pace;
    const f = p.pitch * Math.pow(2, (2 * k) / 12);
    const lift = 0.9 + 0.1 * k;
    T.noise(out, at - 0.1, { filter: 'bandpass', f: 400 + 120 * k, to: 2600, q: 1.2, dur: 0.1, peak: 0.1, a: 0.06 });
    T.bell(out, at, { f, partials: metal, drift: 0.995, dur: 0.38, peak: 0.02 * lift, a: 0.001 });
    T.bell(out, at + 0.007, { f: f * 1.19, partials: metal, drift: 0.995, dur: 0.3, peak: 0.016 * lift, a: 0.001 });
    T.noise(out, at, { filter: 'highpass', f: 3500, to: 2500, q: 0.8, dur: 0.03, peak: 0.07 * lift, a: 0.001 });
    T.noise(out, at, { filter: 'bandpass', f: 1800, to: 1000, q: 1.5, dur: 0.06, peak: 0.08 * lift, a: 0.001 });
    for (let j = 0; j < 2; j++) {
      T.tick(out, at + 0.06 + j * 0.05, { f: 1600 + 300 * j, q: 2.5, dur: 0.012, peak: 0.045, blip: 240, blipPeak: 0.016, blipDur: 0.025 });
    }
  }
  // eight pips and it is gone: a glass crackle and fall with a low thump
  const b = c0 + (hits - 1) * p.pace + 0.2;
  T.crackle(out, b, { dur: 0.36, rate: 130, f: 6000, to: 2100, spread: 0.5, q: 1.2, len: 0.01, peak: 0.02 + 0.18 * p.shatter });
  T.osc(out, b, { f: 2700, to: 470, dur: 0.38, peak: 0.006 + 0.034 * p.shatter, a: 0.004 });
  T.osc(out, b + 0.02, { f: 3500, to: 720, dur: 0.3, peak: 0.003 + 0.016 * p.shatter, a: 0.004 });
  T.osc(out, b, { f: 100, to: 46, dur: 0.24, peak: 0.02 + 0.06 * p.shatter, a: 0.004 });
}

function (T, out, t, p) {
  const at = (s) => 587.33 * p.pitch * Math.pow(2, s / 12);
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.6 });
  const bar = [[1, 1, 1], [4, 0.12 + 0.3 * p.mallet, 0.22], [10, 0.04 + 0.08 * p.mallet, 0.1]];
  // the flourish: marimba D, F#, A with a clock tick on each, ticks quickening
  [0, 4, 7].forEach((s, i) => {
    const a = t + i * 0.062;
    T.bell(room, a, { f: at(s), partials: bar, dur: 0.34, peak: 0.04, a: 0.003 });
    T.tick(room, a, { f: 4200 + 500 * i, q: 4, dur: 0.01, peak: 0.045, blip: 5200 + 600 * i, blipDur: 0.012, blipPeak: 0.01 });
  });
  T.tick(room, t + 0.16, { f: 5200, q: 4, dur: 0.01, peak: 0.03 });
  // the landing at 0.19 s: the high D on the marimba, a clock tick on top
  const L = t + 0.19;
  T.bell(room, L, { f: at(12), partials: bar, dur: 0.62, peak: 0.068, a: 0.003 });
  T.tick(room, L, { f: 4800, q: 4, dur: 0.012, peak: 0.05, blip: 6200, blipDur: 0.014, blipPeak: 0.012 });
  // the gears slowing: ticks that spread out and fade
  const gaps = [0.09, 0.15, 0.22];
  let g = 0;
  for (let k = 0; k < Math.round(p.gears); k++) {
    g += gaps[k];
    T.tick(room, L + g, { f: 3600 - 250 * k, q: 4, dur: 0.01, peak: 0.045 * (1 - 0.2 * k) });
  }
}

function (T, out, t, p) {
  const at = (s) => 293.66 * p.pitch * Math.pow(2, s / 12);
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.55 });
  // the flourish: a plucked major triad, 62 ms apart
  [0, 4, 7].forEach((s, i) => {
    T.pluck(room, t + i * 0.062, { f: at(s), dur: 0.42, bright: 0.45, tone: 0.5, peak: 0.065, a: 0.002 });
  });
  // the landing at 0.19 s: the octave and the major third above it, as near-harmonic warm bells
  const L = t + 0.19;
  const warm = [[1, 1, 1], [2, 0.3, 0.6], [3, 0.14, 0.4], [4.1, 0.06, 0.25]];
  T.bell(room, L, { f: at(12), partials: warm, dur: 0.62, peak: 0.046, a: 0.003 });
  T.bell(room, L + 0.012, { f: at(16), partials: warm, dur: 0.54, peak: 0.033, a: 0.003 });
  // the glow: the root and its fifth swelling in under the bells
  T.osc(room, L - 0.02, { f: at(0), dur: 0.62, peak: 0.009 + 0.028 * p.glow, a: 0.12 });
  T.osc(room, L - 0.02, { f: at(7), dur: 0.56, peak: 0.005 + 0.018 * p.glow, a: 0.14 });
  // a last small bell a fifth above, the lift that passes the warmth on
  T.bell(room, L + 0.13, { f: at(19), partials: [[1, 1, 1], [3, 0.2, 0.4]], dur: 0.4, peak: 0.018, a: 0.003 });
}

function (T, out, t, p) {
  const at = (s) => 293.66 * p.pitch * Math.pow(2, s / 12);
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.5 });
  // the flourish: pizzicato D, G, A (an open, unresolved climb), a swish after each
  [0, 5, 7].forEach((s, i) => {
    const a = t + i * 0.062;
    T.pluck(room, a, { f: at(s), dur: 0.18, bright: 0.25, tone: 0.8, peak: 0.085, a: 0.002 });
    T.noise(room, a + 0.012, { filter: 'highpass', f: 4500 + 700 * i, to: 8000, q: 0.8, dur: 0.03, peak: 0.02, a: 0.004 });
  });
  // the landing at 0.19 s: the same three notes an octave up, strummed fast (still unresolved), and the snap
  const L = t + 0.19;
  [0, 5, 7].forEach((s, i) => {
    T.pluck(room, L + i * 0.012, { f: at(12 + s), dur: 0.65 - 0.05 * i, bright: 0.35, tone: 0.8, peak: 0.108 - 0.012 * i, a: 0.002 });
  });
  T.noise(room, L, { filter: 'bandpass', f: 1800 + 1200 * p.snap, to: 1500, q: 2, dur: 0.035, peak: 0.03 + 0.07 * p.snap, a: 0.001 });
  T.osc(room, L, { f: 190, to: 95, dur: 0.03, peak: 0.01 + 0.025 * p.snap, a: 0.002 });
  // the leaves: a soft wash of rustle with high ticks in it, thinning out and dying away
  const fall = T.bus(room, L + 0.03, { peak: 1, a: 0.02, dur: 0.5, s: 0.5, d: 0.15, r: 0.25 });
  T.noise(fall, L + 0.03, { filter: 'bandpass', f: 4800, to: 3200, q: 0.9, dur: 0.5, peak: 0.012 + 0.08 * p.leaves, a: 0.03, s: 0.8, d: 0.05, r: 0.2 });
  T.crackle(fall, L + 0.03, { dur: 0.5, rate: 110, f: 5200, to: 3000, spread: 0.4, q: 1.6, len: 0.007, peak: 0.03 + 0.26 * p.leaves, vary: 0.8 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.4 });
  const k = p.pitch;
  // the flourish: three rivet tinks, each higher
  [0, 1, 2].forEach((i) => {
    const a = t + i * 0.062;
    T.bell(room, a, { f: 1800 * k * Math.pow(2, (i * 4) / 12), partials: [[1, 1, 1], [2.76, 0.5, 0.5]], dur: 0.07, peak: 0.04, a: 0.001 });
    T.noise(room, a, { filter: 'highpass', f: 5000, to: 7000, q: 0.8, dur: 0.012, peak: 0.03, a: 0.001 });
  });
  // the landing at 0.19 s: the anvil, inharmonic metal partials a fourth below D4 (heavier than the
  // other five, which land on D)
  const L = t + 0.19;
  const anvil = [[1, 1, 1], [2.4, 0.6, 0.8], [4.17, 0.5, 0.65], [5.81, 0.35, 0.5], [8.2, 0.2, 0.3]];
  T.bell(room, L, { f: 220 * k, partials: anvil, drift: 0.995, dur: p.ring, peak: 0.039, a: 0.001 });
  T.bell(room, L + 0.006, { f: 220 * k * 1.5, partials: anvil, drift: 0.995, dur: p.ring * 0.8, peak: 0.023, a: 0.001 });
  T.osc(room, L, { f: 95 * k, to: 48 * k, dur: 0.18, peak: 0.01 + 0.05 * p.weight, a: 0.003 });
  T.noise(room, L, { filter: 'bandpass', f: 1800, to: 1000, q: 1.5, dur: 0.05, peak: 0.02, a: 0.001 });
  T.noise(room, L, { filter: 'highpass', f: 3500, to: 2500, q: 0.8, dur: 0.025, peak: 0.014, a: 0.001 });
}

function (T, out, t, p) {
  const R = 146.83 * p.pitch;
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.45 });
  // the flourish: two detuned saws climb an octave through a filter that opens, over a noise riser
  const rise = T.filter(room, t, { type: 'lowpass', f: 350, to: 3800, dur: 0.18, q: 2 });
  T.osc(rise, t, { type: 'sawtooth', f: R, to: R * 2, glide: 0.18, dur: 0.2, peak: 0.05, a: 0.17 });
  T.osc(rise, t, { type: 'sawtooth', f: R, to: R * 2, glide: 0.18, dur: 0.2, peak: 0.04, a: 0.17, detune: 14 });
  T.noise(room, t, { filter: 'bandpass', f: 600, to: 6000, q: 1.2, dur: 0.2, peak: 0.07, a: 0.17 });
  // the landing at 0.19 s: a stab on a power chord (D, A, D, A), brightest at the start
  const L = t + 0.19;
  const stab = T.filter(room, L, { type: 'lowpass', f: 900 + 2600 * p.bite, to: 700, dur: 0.22, q: 1.2 });
  [1, 1.5, 2, 3].forEach((m, i) => {
    T.osc(stab, L, { type: 'sawtooth', f: R * m, dur: 0.42, peak: 0.021 - 0.0027 * i, a: 0.012, s: 0.6, d: 0.06, r: 0.26 });
    T.osc(stab, L, { type: 'sawtooth', f: R * m, dur: 0.42, peak: 0.0135, a: 0.012, s: 0.6, d: 0.06, r: 0.26, detune: 11 });
  });
  T.osc(room, L, { f: 150, to: 55, dur: 0.12, peak: 0.015 + 0.05 * p.punch, a: 0.003 });
  T.noise(room, L, { filter: 'highpass', f: 2500, q: 0.8, dur: 0.03, peak: 0.008 + 0.045 * p.punch, a: 0.001 });
  // the dash ghost: a band of noise falling away after the stab
  T.noise(room, L + 0.02, { filter: 'bandpass', f: 3500, to: 700, q: 1.3, dur: 0.64, peak: 0.06, a: 0.02 });
}

function (T, out, t, p) {
  const R = 587.33 * p.pitch;
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.75 });
  // the flourish: a noise swell opening upward (a reverb tail in reverse) and an FM glide climbing
  T.noise(room, t, { filter: 'bandpass', f: 900, to: 6500, q: 1.2, dur: 0.2, peak: 0.07, a: 0.17 });
  T.fm(room, t, { f: R * (1 - 0.65 * p.swirl), to: R, ratio: 2.01, index: 3, index1: 0.6, dur: 0.2, glide: 0.18, peak: 0.05, a: 0.12 });
  // the landing: two FM bells a few cents apart, so the ring beats softly
  const L = t + 0.19;
  const idx = 0.8 + 3 * p.shimmer;
  T.fm(room, L, { f: R, to: R * 0.99, ratio: 3.5, index: idx, index1: 0.15, dur: 0.62, peak: 0.05, a: 0.003 });
  T.fm(room, L, { f: R * 1.006, to: R * 0.996, ratio: 3.5, index: idx, index1: 0.15, dur: 0.56, peak: 0.032, a: 0.003 });
  T.noise(room, L, { filter: 'highpass', f: 7000, to: 9000, q: 0.7, dur: 0.1, peak: 0.01 + 0.03 * p.shimmer, a: 0.004 });
  // the return: a soft glide back down an octave under the ring
  T.osc(room, L + 0.04, { f: R * 2, to: R * 0.9, dur: 0.5, peak: 0.014, a: 0.05 });
}

function (T, out, t, p) {
  const n = Math.round(p.tiers);
  const gap = 0.2;
  let top = p.pitch;
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const f = p.pitch * Math.pow(2, (k * p.rise) / 12);
    top = f;
    // the form slides onto the stack and lands: a whisper of paper, a soft knock
    T.noise(out, at, { filter: 'bandpass', f: 1500, to: 3400, q: 1.2, dur: 0.07, peak: 0.05, a: 0.03 });
    T.osc(out, at + 0.055, { f: 150, to: 62, dur: 0.14, peak: 0.06, a: 0.003 });
    // its tone: one more detuned saw per tier under a clear triangle an octave up, scooping into the
    // step through an opening filter; every tier but the last is cut short so each step is heard
    const last = k === n - 1;
    const len = last ? 0.9 : 0.25;
    const lp = T.filter(out, at + 0.05, { type: 'lowpass', f: 420, to: 1500 + 500 * k, dur: 0.2, q: 1.2 });
    for (let j = 0; j <= k; j++) {
      const spread = k === 0 ? 0 : (j / k - 0.5) * 22;
      T.osc(lp, at + 0.05, {
        type: 'sawtooth', f: f * 0.84, to: f, glide: 0.06, dur: len, peak: 0.05 / Math.sqrt(k + 1), a: 0.02,
        detune: spread, tail: 0.3, fade: 0.03,
      });
    }
    T.osc(out, at + 0.05, { type: 'triangle', f: f * 1.68, to: f * 2, glide: 0.06, dur: len, peak: 0.045, a: 0.012, tail: 0.3, fade: 0.03 });
    // the step lights up: a small glass tick an octave and a half above the tone
    T.bell(out, at + 0.07, { f: f * 6, partials: [[1, 1, 1], [2.32, 0.3, 0.5]], dur: 0.22, peak: 0.032 * p.glass, a: 0.002 });
  }
  // the last form arrives free: a small pop, a bloom of air and three lore stars in a rising stack
  const fin = t + (n - 1) * gap + 0.2;
  T.osc(out, fin, { f: 380, to: 900, dur: 0.06, peak: 0.05, a: 0.004 });
  T.noise(out, fin, { filter: 'highpass', f: 3500, to: 8000, q: 0.8, dur: 0.45, peak: 0.035, a: 0.12 });
  const glassy = [[1, 1, 1], [2.32, 0.38, 0.55], [4.1, 0.14, 0.3]];
  for (let k = 0; k < 3; k++) {
    T.bell(out, fin + 0.04 + k * 0.07, { f: top * (4 + k), partials: glassy, dur: k === 2 ? 0.85 : 0.55, peak: 0.05 * p.glass, a: 0.003 });
  }
}

function (T, out, t, p) {
  const bar = [[1, 1, 1], [4, 0.28, 0.3], [9.8, 0.1, 0.15]];
  const f1 = p.pitch;
  const f2 = p.pitch * Math.pow(2, p.step / 12);
  const hop = (at, f, lv) => {
    T.bell(out, at, { f, partials: bar, dur: 0.2, peak: 0.06 * lv * (0.8 + 0.4 * p.bright), a: 0.002 });
    // the tap of the mallet
    T.noise(out, at, { filter: 'bandpass', f: f * 3, q: 1.2, dur: 0.008, peak: 0.004 + 0.02 * p.bright * lv, a: 0.001 });
  };
  hop(t, f1, 0.85);
  hop(t + p.gap, f2, 1);
}

function (T, out, t, p) {
  const L = Math.round(p.lore);
  const ladder = [0, 7, 12, 16, 19];
  const glass = [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34], [6.63, 0.09, 0.2]];
  const room = T.reverb(out, t, { time: 0.7, mix: 0.16, tone: 0.75 });
  // the star arcs up toward the meter
  T.noise(room, t, { filter: 'bandpass', f: 2500, to: 7000, q: 1.2, dur: 0.14, peak: 0.03, a: 0.1 });
  T.osc(room, t, { f: p.pitch * 0.8, to: p.pitch * 1.6, dur: 0.14, peak: 0.01, a: 0.1 });
  // the landing: L + 1 chimes climbing the ladder, the last one left to ring
  const start = t + 0.13;
  for (let k = 0; k <= L; k++) {
    const at = start + k * 0.075;
    const f = p.pitch * Math.pow(2, ladder[k] / 12);
    const top = k === L;
    T.bell(room, at, { f, partials: glass, dur: top ? 0.5 : 0.3, peak: top ? 0.068 : 0.054, a: 0.002 });
    T.osc(room, at, { type: 'triangle', f: f / 2, dur: top ? 0.35 : 0.18, peak: 0.012, a: 0.004 });
  }
  T.noise(room, start + L * 0.075, { filter: 'highpass', f: 5500, to: 9000, q: 0.8, dur: 0.35, peak: 0.04 * p.shine, a: 0.02 });
}

function (T, out, t, p) {
  const f = p.pitch;
  T.tick(out, t, { f: f * 2.4, q: 2.4, dur: 0.009, peak: 0.022 });
  T.bell(out, t, { f, partials: [[1, 1, 1], [2.32, 0.35, 0.5]], dur: 0.05 + 0.1 * p.glass, peak: 0.034, a: 0.002 });
}

function (T, out, t, p) {
  const k = p.pitch;
  // the hop: a breath rising and a soft blip lifting
  T.noise(out, t, { filter: 'bandpass', f: 550 * k, to: 1900 * k, q: 1.2, dur: 0.06, peak: 0.1, a: 0.045 });
  T.noise(out, t + 0.055, { filter: 'bandpass', f: 1900 * k, to: 800 * k, q: 1.2, dur: 0.06, peak: 0.08, a: 0.006 });
  T.osc(out, t, { f: 420 * k, to: 680 * k, dur: 0.07, peak: 0.016, a: 0.01 });
  // the slide: an eased brush that falls as the card slows
  const s = t + 0.09;
  T.noise(out, s, { filter: 'bandpass', f: 1500 * k, to: 480 * k, q: 1, dur: p.distance, peak: 0.13, a: p.distance * 0.3, s: 0.7, d: 0.03, r: p.distance * 0.5, curve: 'lin' });
  // the landing
  const L = s + p.distance;
  T.noise(out, L, { filter: 'lowpass', f: 1000 * k, to: 420 * k, q: 1, dur: 0.045, peak: 0.07, a: 0.002 });
  T.osc(out, L, { f: 170 * k, to: 95 * k, dur: 0.07, peak: 0.04, a: 0.003 });
  T.bell(out, L + 0.005, { f: 1320 * k, partials: [[1, 1, 1], [2.32, 0.3, 0.5]], dur: 0.3, peak: 0.004 + 0.022 * p.ring, a: 0.003 });
}

function (T, out, t, p) {
  const n = Math.round(p.pump);
  const f0 = p.pitch;
  // the +N token hops from the quester to the ally: a small rising blip and a soft landing tick
  T.osc(out, t, { f: f0 * 3.4, to: f0 * 6.2, dur: 0.085, peak: 0.07, a: 0.004 });
  T.tick(out, t + 0.095, { f: 2400, q: 2, dur: 0.014, peak: 0.055, blip: f0 * 5, blipPeak: 0.022, blipDur: 0.025 });
  // the ally's strength counts up, one whole tone per point
  for (let k = 0; k < n; k++) {
    T.osc(out, t + 0.16 + k * 0.058, { type: 'triangle', f: f0 * 5 * Math.pow(2, (2 * k) / 12), dur: 0.07, peak: 0.072, a: 0.003 });
  }
  // the challenge goes out: a dashed ray of air and the bow
  const a0 = t + 0.2 + n * 0.058 + 0.06;
  T.noise(out, a0 - 0.06, { filter: 'bandpass', f: 700, to: 2600, q: 1.2, dur: 0.1, peak: 0.095, a: 0.05 });
  T.pluck(out, a0, { f: f0, dur: 0.24, bright: 0.75, peak: 0.1 });
  T.osc(out, a0, { f: f0 * 0.9, to: f0 * 0.5, dur: 0.1, peak: 0.04, a: 0.003 });
  T.noise(out, a0 + 0.012, { filter: 'bandpass', f: 5200, to: 1500, q: 2, dur: p.flight, peak: 0.12, a: 0.012 });
  // it lands: both fighters take a dry tick at the same moment, over a small clang
  const hit = a0 + 0.04 + p.flight * 0.8;
  T.tick(out, hit, { f: 1700, q: 2.5, dur: 0.014, peak: 0.12, blip: 260, blipPeak: 0.04, blipDur: 0.03 });
  T.tick(out, hit, { f: 2500, q: 2.5, dur: 0.014, peak: 0.095, blip: 340, blipPeak: 0.027, blipDur: 0.03 });
  T.bell(out, hit, { f: 1150, partials: [[1, 1, 1], [2.76, 0.6, 0.6], [5.4, 0.3, 0.4]], dur: 0.35, peak: 0.04, a: 0.001 });
  // the target breaks: a glass crackle that drifts down, a falling glassy tone and a low thump
  const br = hit + 0.05;
  T.crackle(out, br, { dur: 0.42, rate: 120, f: 6000, to: 2200, spread: 0.5, q: 1.2, len: 0.01, peak: 0.14 * p.shatter + 0.012 });
  T.osc(out, br, { f: 2700, to: 480, dur: 0.45, peak: 0.032 * p.shatter, a: 0.004 });
  T.noise(out, br + 0.05, { filter: 'lowpass', f: 500, to: 130, q: 0.8, dur: 0.4, peak: 0.03 * p.shatter, a: 0.04 });
  T.osc(out, br, { f: 95, to: 48, dur: 0.2, peak: 0.027 + 0.06 * p.shatter, a: 0.004 });
}

function (T, out, t, p) {
  const P = p.pull;
  T.osc(out, t, { f: p.pitch, to: p.pitch * 1.6, dur: P, peak: 0.05, a: P * 0.5, s: 0.6, d: 0.05, r: P * 0.3, vib: { rate: 5.5, depth: 14 } });
  T.osc(out, t, { type: 'triangle', f: p.pitch * 2, to: p.pitch * 3.2, dur: P, peak: 0.014, a: P * 0.55, s: 0.6, d: 0.05, r: P * 0.3, lp: 2400 });
  // the lore lands: a small golden glass chime, two octaves above where the pull began
  if (p.lore > 0.02) {
    T.bell(out, t + P * 0.85, {
      f: p.pitch * 4, partials: [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34], [6.63, 0.09, 0.2]],
      dur: 0.27, peak: 0.045 * p.lore, a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.cards);
  const ready = Math.round(p.on) === 0;
  const span = (n - 1) * p.gap;
  const sw = T.pan(out, t, { x: -0.7, to: 0.7, dur: span + 0.1 });
  // the band of light: soft air rising (ready) or sinking (exert) as it passes along the row
  T.noise(sw, t, {
    filter: 'bandpass', f: ready ? 700 + 400 * p.tone : 2400 + 800 * p.tone, to: ready ? 3000 + 1500 * p.tone : 750, q: 0.9,
    dur: span + 0.2, peak: 0.05, a: (span + 0.2) * 0.5,
  });
  for (let k = 0; k < n; k++) {
    const at = t + k * p.gap;
    const f = ready ? 640 * Math.pow(2, (k * 2) / 12) : 920 * Math.pow(2, (-k * 2) / 12);
    const l = ready ? 1 : 1 - 0.05 * k;
    // a wooden tick: a short triangle body under a band-passed click
    T.tick(sw, at, {
      f: f * (2.4 + 1.2 * p.tone), q: 2, dur: 0.014, peak: 0.065 * l, blip: f, blipTo: f * (ready ? 1.05 : 0.8),
      blipType: 'triangle', blipDur: 0.06, blipPeak: 0.044 * l,
    });
  }
  if (ready) {
    // the last card catches the light: a thin glass tip, once
    T.bell(sw, t + span + 0.01, { f: 2349, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.3, peak: 0.02, a: 0.003 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.chips);
  const gap = 0.075;
  const metal = [[1, 1, 1], [2.76, 0.5, 0.5], [5.4, 0.22, 0.3]];
  // one tink per point resisted, each a little lower and softer
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    T.bell(out, at, { f: p.pitch * Math.pow(0.88, k) * T.rand(0.99, 1.01), partials: metal, dur: 0.13, peak: 0.03 * (1 - 0.12 * k), a: 0.001 });
    T.noise(out, at, { filter: 'highpass', f: 5000, q: 0.8, dur: 0.006, peak: 0.03, a: 0.001 });
  }
  // the number shrinks: a short step down
  const down = t + n * gap + 0.01;
  T.osc(out, down, { f: 1150, to: 1150 * (1 - 0.55 * p.drop), dur: 0.06, peak: 0.035, a: 0.003 });
  // the single point that lands: a dry damage tick
  T.tick(out, down + 0.06, { f: 2300, q: 2, dur: 0.013, peak: 0.09, blip: 700, blipTo: 520, blipPeak: 0.03, blipDur: 0.03 });
}

function (T, out, t, p) {
  const S = p.swell;
  const up = Math.round(p.up) === 1;
  const a = p.pitch * (up ? 1 : 1.5);
  const b = p.pitch * (up ? 1.5 : 1);
  const stage = T.dcblock(out);
  // the card slides over the one beneath it
  T.noise(stage, t, { filter: 'bandpass', f: up ? 500 : 1500, to: up ? 1500 : 500, q: 1.1, dur: S, peak: 0.08, a: S * 0.6 });
  // the swell: two detuned pulses and an octave triangle glide the fifth behind an opening lowpass
  const lp = T.filter(stage, t, { type: 'lowpass', f: up ? 380 : 2600, to: up ? 2600 : 480, dur: S * 0.95, q: 1.2 });
  const body = { glide: S * 0.95, dur: S + 0.28, a: S * 0.6, s: 0.8, d: 0.05, r: 0.25 };
  T.pulse(lp, t, { ...body, duty: 0.3, f: a, to: b, peak: 0.05, detune: -8 });
  T.pulse(lp, t, { ...body, duty: 0.3, f: a, to: b, peak: 0.045, detune: 8 });
  T.osc(lp, t, { ...body, type: 'triangle', f: a * 2, to: b * 2, peak: 0.03 });
  // the landing: a thud, a dull pat and a glass overtone (a soft tick only when the stack comes apart)
  const at = t + S;
  const w = up ? 1 : 0.3;
  T.osc(stage, at, { f: 125, to: 55, dur: 0.14, peak: 0.1 * p.land * w, a: 0.003 });
  T.noise(stage, at, { filter: 'lowpass', f: 1400, to: 400, q: 0.9, dur: 0.05, peak: 0.07 * p.land * w, a: 0.002 });
  T.bell(stage, at, { f: p.pitch * 8, partials: [[1, 1, 1], [2.32, 0.42, 0.55], [4.25, 0.2, 0.34]], dur: 0.34, peak: 0.05 * p.land * w, a: 0.002 });
  if (!up) T.tick(stage, at, { f: 1800, q: 2, dur: 0.012, peak: 0.04 });
}

function (T, out, t, p) {
  const L = p.length;
  const lane = T.pan(out, t, { x: -0.8 * p.width, to: 0.8 * p.width, dur: L });
  // the pass: a band that falls as it goes by (like a horn passing), swelling then fading
  T.noise(lane, t, {
    filter: 'bandpass', f: 3600 * p.pitch, to: 1150 * p.pitch, q: 2.4, dur: L, peak: 0.16,
    a: L * 0.3, s: 0.6, d: L * 0.1, r: L * 0.5,
  });
  // a faint airy edge above it
  T.noise(lane, t + L * 0.08, {
    filter: 'highpass', f: 5200 * p.pitch, to: 3200 * p.pitch, q: 0.7, dur: L * 0.8, peak: 0.022,
    a: L * 0.3, s: 0.6, d: L * 0.1, r: L * 0.4,
  });
  // the flutter: little bandpassed grains falling along the same path
  const n = Math.round(p.flutter * 6);
  for (let k = 0; k < n; k++) {
    const u = (k + T.rand(0.1, 0.9)) / n;
    T.noise(lane, t + L * (0.05 + 0.8 * u), {
      filter: 'bandpass', f: 4200 * p.pitch * Math.pow(0.4, u) * T.rand(0.9, 1.1), q: 3,
      dur: 0.02, peak: 0.05 * (1 - 0.5 * Math.abs(u - 0.4)), a: 0.003,
    });
  }
}

function (T, out, t, p) {
  const x = p.pitch;
  // two attackers glide past from one side to the other: rushing in, then falling away
  for (let k = 0; k < 2; k++) {
    const at = t + k * 0.15;
    const lane = T.pan(out, at, { x: -0.8, to: 0.8, dur: 0.32 });
    T.noise(lane, at, { filter: 'bandpass', f: 450 * x * (1 + 0.25 * k), to: 3000 * x, q: 1.3, dur: 0.17, peak: 0.15, a: 0.075 });
    T.noise(lane, at + 0.1, { filter: 'bandpass', f: 2600 * x, to: 650 * x, q: 1.8, dur: 0.22, peak: 0.1, a: 0.03 });
    T.osc(lane, at, { f: 760 * x * (1 + 0.25 * k), to: 1500 * x, dur: 0.32, peak: 0.022 * p.ghost + 0.001, a: 0.1, vib: { rate: 9, depth: 45 } });
  }
  // the defender swings and misses: a lower, slower whiff that comes up late
  T.noise(out, t + 0.2, { filter: 'bandpass', f: 280, to: 950, q: 1, dur: 0.22, peak: 0.1, a: 0.09 });
  // the bounce: a swirl that tightens upward and ends in a soft bubbling pop
  const b = t + 0.56;
  T.osc(out, b, { f: 300 * x, to: 1500 * x, dur: 0.26, peak: 0.055, a: 0.04, trem: { rate: 22, depth: 0.5 } });
  T.noise(out, b, { filter: 'bandpass', f: 800 * x, to: 3600 * x, q: 3, dur: 0.26, peak: 0.1, a: 0.1 });
  T.tick(out, b + 0.27, { f: 1500 * x, q: 2, dur: 0.02, peak: 0.07, blip: 700 * x, blipTo: 320 * x, blipPeak: 0.05, blipDur: 0.06 });
  // the quest pays lore: small gold glass chimes, each a whole tone above the last
  const glassy = [[1, 1, 1], [2.32, 0.38, 0.55], [4.1, 0.14, 0.3]];
  const lore = Math.round(p.lore);
  const q0 = t + 0.92;
  for (let k = 0; k < lore; k++) {
    T.bell(out, q0 + k * 0.1, { f: 1175 * x * Math.pow(2, (2 * k) / 12), partials: glassy, dur: k === lore - 1 ? 0.6 : 0.42, peak: 0.075, a: 0.003 });
  }
  // the draw trigger: a short swish from the deck, then a flick per card
  const d0 = q0 + (lore - 1) * 0.1 + 0.27;
  const draws = Math.round(p.draws);
  for (let k = 0; k < draws; k++) {
    const at = d0 + k * 0.075;
    T.noise(out, at - 0.06, { filter: 'bandpass', f: 1400, to: 3400, q: 1, dur: 0.07, peak: 0.055, a: 0.03 });
    T.noise(out, at, { filter: 'highpass', f: 3000 + 250 * k, to: 1800, q: 0.9, dur: 0.034, peak: 0.07, a: 0.002 });
    T.osc(out, at, { type: 'triangle', f: 520 + 60 * k, to: 260, dur: 0.03, peak: 0.024, a: 0.002 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.notes);
  // two soft tilts: the singers exert
  for (let k = 0; k < 2; k++) {
    const at = t + k * 0.075;
    T.noise(out, at, { filter: 'bandpass', f: 950, to: 520, q: 1.6, dur: 0.05, peak: 0.06, a: 0.003 });
    T.osc(out, at, { type: 'triangle', f: 240 + 20 * k, to: 150, dur: 0.055, peak: 0.026, a: 0.003 });
  }
  // a voice: a saw through three vowel bands (first, second and third formant) that glide to a
  // neighbouring vowel while the note holds; a trace of breath keeps it from sounding like a synth
  const oo = [330, 820, 2600];
  const ah = [800, 1250, 2800];
  const q = [4.5, 5.5, 6.5];
  const lvl = [1, 0.75, 0.4];
  const open = p.vowel;
  const vowel = (at, f, len, dst, side, level) => {
    const lo = [oo[0] + (ah[0] - oo[0]) * open, oo[1] + (ah[1] - oo[1]) * open, oo[2] + (ah[2] - oo[2]) * open];
    for (let k = 0; k < 3; k++) {
      const to = lo[k] * (k === 1 ? 1 + 0.12 * side : 1);
      const band = T.filter(dst, at, { type: 'bandpass', f: lo[k] * (k === 1 ? 1 - 0.12 * side : 1), to, dur: len * 0.8, q: q[k] });
      T.osc(band, at, {
        type: 'sawtooth', f, dur: len, peak: level * lvl[k], a: 0.012, s: 0.75, d: 0.02, r: len * 0.4, vib: { rate: 6.5, depth: 16 },
      });
    }
    T.noise(dst, at, { filter: 'bandpass', f: lo[1], q: 3, dur: len * 0.5, peak: level * 0.02, a: 0.01 });
  };
  const left = T.pan(out, t, { x: -0.45 });
  const right = T.pan(out, t, { x: 0.45 });
  const arp = [0, 4, 7, 12, 16, 19, 24, 28];
  const t0 = t + 0.17;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, arp[k] / 12);
    vowel(t0 + k * p.speed, f, p.speed * 1.5, k % 2 ? right : left, k % 2 ? 1 : -1, 0.19 + 0.01 * k);
  }
  // the total is added up: two small glass ticks
  const tot = t0 + n * p.speed + 0.04;
  T.bell(out, tot, { f: 2200, partials: [[1, 1, 1], [2.32, 0.3, 0.5]], dur: 0.12, peak: 0.025, a: 0.002 });
  T.bell(out, tot + 0.075, { f: 2200, partials: [[1, 1, 1], [2.32, 0.3, 0.5]], dur: 0.12, peak: 0.025, a: 0.002 });
  // the song fires free: a flare of air and a stack of gold glass chimes over a warm swell
  const fire = tot + 0.17;
  T.noise(out, fire, { filter: 'highpass', f: 2500, to: 9000, q: 0.8, dur: 0.4, peak: 0.04, a: 0.06 });
  T.chord(out, fire, { type: 'triangle', root: p.pitch * 2, notes: [0, 7, 12, 16], dur: 0.7, peak: 0.07, a: 0.04 });
  const glassy = [[1, 1, 1], [2.32, 0.38, 0.55], [4.1, 0.14, 0.3]];
  const up = [12, 19, 24, 28];
  for (let k = 0; k < 4; k++) {
    T.bell(out, fire + 0.03 + k * 0.045, { f: p.pitch * 4 * Math.pow(2, (up[k] - 12) / 12), partials: glassy, dur: 0.7, peak: 0.04, a: 0.003 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.pumps);
  const step = 0.052;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, (k * 3) / 12);
    T.pulse(out, t + k * step, { duty: 0.2, f, to: f * 1.12, dur: 0.034, peak: 0.05 * (0.8 + 0.2 * (n > 1 ? k / (n - 1) : 1)), a: 0.003, lp: 3600 });
  }
  // the crack as the attack lands
  const c = t + n * step + 0.01;
  T.noise(out, c, { filter: 'highpass', f: 2400, to: 3800, q: 0.8, dur: 0.025, peak: 0.025 + 0.055 * p.crack, a: 0.001 });
  T.osc(out, c, { f: 520, to: 150, dur: 0.06, peak: 0.012 + 0.028 * p.crack, a: 0.002 });
}

function (T, out, t, p) {
  // the turn marker steps: one dry tick
  T.tick(out, t, { f: 2800, q: 3, dur: 0.012, peak: 0.05, blip: 1800, blipPeak: 0.016, blipDur: 0.02 });
  // an ink drip: a falling plunk with a quick liquid rise inside it, a glassy edge and a dark puff
  const drip = (at, up) => {
    T.osc(out, at, { f: 720 * up, to: 250 * up, dur: 0.1, peak: 0.05, a: 0.003 });
    T.osc(out, at + 0.012, { f: 420 * up, to: 980 * up, dur: 0.05, peak: 0.02, a: 0.004 });
    T.noise(out, at, { filter: 'bandpass', f: 2200 * up, q: 2, dur: 0.03, peak: 0.05, a: 0.002 });
    T.osc(out, at, { f: 3300 * up, dur: 0.05, peak: 0.01, a: 0.002 });
    T.noise(out, at + 0.01, { filter: 'lowpass', f: 420, q: 0.8, dur: 0.07, peak: 0.04, a: 0.006 });
  };
  const n = Math.round(p.drips);
  for (let k = 0; k < n; k++) drip(t + 0.11 + k * 0.1, 1 + 0.18 * k);
  // the rise: a saw and a band of noise opening together, cut off sharply at the landing
  const r0 = t + 0.2 + n * 0.1;
  const L = r0 + p.rise;
  const lp = T.filter(out, r0, { type: 'lowpass', f: 260, to: 3800, dur: p.rise, q: 2 });
  T.osc(lp, r0, { type: 'sawtooth', f: p.pitch * 1.2, to: p.pitch * 3.4, dur: p.rise + 0.02, peak: 0.042, a: p.rise * 0.95 });
  T.osc(lp, r0, { type: 'sawtooth', f: p.pitch * 1.2, to: p.pitch * 3.4, dur: p.rise + 0.02, peak: 0.03, a: p.rise * 0.95, detune: 13 });
  T.noise(out, r0, { filter: 'bandpass', f: 500, to: 5500, q: 1.1, dur: p.rise + 0.02, peak: 0.085, a: p.rise * 0.95 });
  // the landing: a deep falling thump, a lowpassed body, a wooden knock and a low metal ring
  const w = p.weight;
  T.osc(out, L, { f: p.pitch * 1.6, to: p.pitch * 0.45, dur: 0.3 + 0.25 * w, peak: 0.08 + 0.055 * w, a: 0.003 });
  T.noise(out, L, { filter: 'lowpass', f: 1400, to: 160, q: 0.8, dur: 0.14 + 0.1 * w, peak: 0.11 + 0.08 * w, a: 0.002 });
  T.noise(out, L, { filter: 'bandpass', f: 1500, to: 900, q: 1.4, dur: 0.05, peak: 0.095, a: 0.001 });
  T.bell(out, L, { f: p.pitch * 2.5, partials: [[1, 1, 1], [2.76, 0.45, 0.6], [5.4, 0.2, 0.35]], dur: 0.35 + 0.35 * w, peak: 0.02, a: 0.002 });
  // light floods the card: a gold glass shimmer
  T.bell(out, L + 0.03, { f: 1320, partials: [[1, 1, 1], [2.32, 0.38, 0.55], [4.1, 0.14, 0.3]], dur: 0.6, peak: 0.03, a: 0.004 });
  // the ink is spent: soft ticks as the pips exert
  for (let k = 0; k < 3; k++) {
    T.tick(out, L + 0.2 + k * 0.07, { f: 1200 + 150 * k, q: 2, dur: 0.02, peak: 0.03, blip: 240, blipPeak: 0.012, blipDur: 0.03 });
  }
}

function (T, out, t, p) {
  const stacks = Math.round(p.stacks);
  const fallen = Math.round(p.fallen);
  const w = p.crash;
  // cards slide under a character: a paper whisper and a small soft tick, one more each turn
  for (let k = 0; k < stacks; k++) {
    const at = t + k * 0.2;
    T.noise(out, at, { filter: 'bandpass', f: 1300 + 100 * k, to: 2700, q: 1.1, dur: 0.09, peak: 0.05, a: 0.04 });
    T.tick(out, at + 0.085, { f: 1000 + 120 * k, q: 2, dur: 0.02, peak: 0.035, blip: 230 + 25 * k, blipPeak: 0.014, blipDur: 0.03 });
  }
  // the wave: a low swell and a band of noise that opens as it travels, ending at the crash
  const w0 = t + stacks * 0.2 + 0.08;
  const S = p.swell;
  const L = w0 + S;
  const lp = T.filter(out, w0, { type: 'lowpass', f: 160, to: 1800, dur: S, q: 1.5 });
  T.osc(lp, w0, { type: 'sawtooth', f: 46, to: 105, dur: S + 0.02, peak: 0.03, a: S * 0.96, trem: { rate: 5, depth: 0.25 } });
  T.osc(out, w0, { f: 46, to: 105, dur: S + 0.02, peak: 0.024, a: S * 0.96 });
  T.noise(out, w0, { filter: 'lowpass', f: 140, to: 2300, q: 0.9, dur: S + 0.02, peak: 0.056, a: S * 0.96 });
  T.noise(out, w0 + S * 0.35, { filter: 'bandpass', f: 600, to: 4200, q: 0.9, dur: S * 0.65 + 0.02, peak: 0.03, a: S * 0.6 });
  // the crash: a deep boom, a falling body of noise, a hard crack and a burst of glass
  T.osc(out, L, { f: 140, to: 36, dur: 0.45 + 0.25 * w, peak: 0.06 + 0.04 * w, a: 0.003 });
  T.noise(out, L, { filter: 'lowpass', f: 2600, to: 160, q: 0.8, dur: 0.3 + 0.2 * w, peak: 0.1 + 0.056 * w, a: 0.002 });
  T.noise(out, L, { filter: 'highpass', f: 3000, to: 1800, q: 0.8, dur: 0.04, peak: 0.027 + 0.042 * w, a: 0.001 });
  T.crackle(out, L, { dur: 0.3, rate: 130, f: 5200, to: 2000, spread: 0.6, q: 1.8, len: 0.009, peak: 0.021 + 0.037 * w });
  // the characters break and fall, one after another: a glass crackle and a falling glassy tone each
  for (let k = 0; k < fallen; k++) {
    const at = L + 0.08 + k * 0.1;
    T.crackle(out, at, { dur: 0.22, rate: 90, f: 4800 - 500 * k, to: 1800, spread: 0.5, q: 2.2, len: 0.007, peak: 0.06 });
    T.osc(out, at, { f: 2200 - 250 * k, to: 420, dur: 0.3, peak: 0.016, a: 0.004 });
    T.osc(out, at, { f: 110 - 10 * k, to: 55, dur: 0.12, peak: 0.03, a: 0.003 });
  }
  // the hush: a low rumble dying away with a little dust
  const h = L + 0.1;
  T.noise(out, h, { filter: 'lowpass', f: 380, to: 90, q: 0.8, dur: 0.65, peak: 0.05, a: 0.06 });
  T.noise(out, h + 0.2, { filter: 'bandpass', f: 3200, to: 1100, q: 1, dur: 0.45, peak: 0.012, a: 0.05 });
}

function (T, out, t, p) {
  // the ink gathering: a short sine bloop rising
  T.osc(out, t, { f: 420, to: 1000, dur: 0.06, peak: 0.004 + 0.04 * p.bloop, a: 0.006 });
  // the tink: struck metal partials, each chirping up about 12% in the first 30 ms, then ringing
  const at = t + 0.04;
  [[1, 0.05, 1], [2.76, 0.02, 0.5], [5.4, 0.009, 0.25]].forEach(([m, peak, len]) => {
    T.osc(out, at, { f: p.pitch * m * 0.88, to: p.pitch * m, glide: 0.03, dur: p.ring * len, peak, a: 0.002 });
  });
  T.noise(out, at, { filter: 'highpass', f: 6500, to: 9000, q: 0.7, dur: 0.03, peak: 0.012, a: 0.002 });
}

function (T, out, t, p) {
  T.osc(out, t, { f: p.pitch, to: p.pitch * 0.34, dur: 0.06, peak: 0.05, a: 0.002 });
  T.noise(out, t, { filter: 'highpass', f: 4500, to: 2800, q: 0.8, dur: 0.018, peak: 0.03, a: 0.001 });
  // the crumbs: three tiny glass tinks, each lower and quieter
  for (let k = 0; k < 3; k++) {
    T.bell(out, t + 0.04 + k * 0.045, {
      f: 3000 * Math.pow(0.8, k), partials: [[1, 1, 1], [2.32, 0.35, 0.5]], drift: 0.96, dur: 0.1,
      peak: (0.006 + 0.03 * p.crumbs) * (1 - 0.25 * k), a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.cost);
  const gap = 0.075;
  // ink paid: a small soft drip (a sine that bends up, with a glassy edge), one per point
  for (let k = 0; k < n; k++) {
    const at = t + k * gap;
    const f = 720 * T.rand(0.94, 1.06);
    T.osc(out, at, { f: f * 0.7, to: f * 1.5, glide: 0.03, dur: 0.07, peak: 0.04, a: 0.003 });
    T.bell(out, at, { f: f * 3.3, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.08, peak: 0.014, a: 0.002 });
  }
  // the card slides under: paper that darkens as it goes
  const s = t + n * gap + (n > 0 ? 0.03 : 0);
  const L = p.slide;
  T.noise(out, s, {
    filter: 'bandpass', f: 1500 + 2500 * p.tone, to: 700 + 700 * p.tone, q: 0.9, dur: L, peak: 0.105,
    a: L * 0.3, s: 0.6, d: L * 0.15, r: L * 0.45, lp: { f: 6000, to: 1100 },
  });
  // it settles
  T.tick(out, s + L * 0.9, { f: 1700 + 800 * p.tone, q: 1.3, dur: 0.014, peak: 0.07, blip: 140, blipTo: 100, blipPeak: 0.035, blipDur: 0.04 });
}

function (T, out, t, p) {
  const L = p.length;
  // the lock-on
  T.tick(out, t, { f: 4200, q: 3, dur: 0.008, peak: 0.04, blip: 2900, blipPeak: 0.02, blipDur: 0.03 });
  const d = t + 0.07;
  // the dissolve: airy noise drifting down and thinning
  T.noise(out, d, { filter: 'bandpass', f: p.pitch * 1.4, to: p.pitch * 0.5, q: 1.2, dur: L, peak: 0.085, a: 0.015, tail: 0.08, fade: 0.03 });
  // glints falling in pitch
  const g = 6;
  for (let k = 0; k < g; k++) {
    const u = k / g;
    const f = p.pitch * Math.pow(0.45, u) * T.rand(0.97, 1.03);
    T.osc(out, d + u * L * 0.85 + T.rand(0, 0.02), { f, to: f * 0.9, dur: 0.07, peak: 0.016 * (1 - 0.6 * u), a: 0.002 });
  }
  // dust specks
  if (p.grit > 0.02) {
    T.crackle(out, d, { dur: L, rate: 40 + 120 * p.grit, f: p.pitch * 1.3, to: p.pitch * 0.5, spread: 0.6, q: 2, len: 0.003, peak: 0.05 * p.grit, vary: 0.6 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.notes);
  const steps = [0, 4, 7, 12, 16, 19, 24];
  const glass = [[1, 1, 1], [2.32, 0.42, 0.6], [4.25, 0.2, 0.4], [6.63, 0.09, 0.25]];
  const room = T.reverb(out, t, { time: 1.2, mix: p.space, tone: 0.65 });
  const gap = 0.075;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    T.bell(room, t + k * gap, { f, partials: glass, dur: 0.8, peak: 0.05 * (1 - 0.04 * k), a: 0.002 });
  }
  // the burst: the chord rings together, with sparkle racing up and a warm swell below
  const at = t + n * gap + 0.03;
  for (const m of [1, 1.5, 2, 3]) {
    T.bell(room, at, { f: p.pitch * m * 2, partials: glass, dur: 1.0, peak: 0.033, a: 0.003 });
  }
  T.noise(room, at, { filter: 'highpass', f: 5000, to: 9500, q: 0.8, dur: 0.6, peak: 0.05 * p.sparkle, a: 0.03 });
  T.osc(room, at, { type: 'triangle', f: p.pitch / 2, dur: 1.0, peak: 0.04, a: 0.25, s: 0.5, d: 0.3, r: 0.4 });
  T.osc(room, at, { type: 'triangle', f: p.pitch * 0.75, dur: 1.0, peak: 0.024, a: 0.25, s: 0.5, d: 0.3, r: 0.4 });
}

function (T, out, t, p) {
  // the bubble: a glittery FM pip that bends up and settles
  T.fm(out, t, { f: p.pitch, to: p.pitch * 2.1, ratio: 1.5, index: 1.4, index1: 0, dur: 0.12, peak: 0.063, a: 0.004, glide: 0.07 });
  // the film of the bubble, wobbling
  T.osc(out, t + 0.01, { f: p.pitch * 3.2, to: p.pitch * 3.6, dur: 0.2, peak: 0.01, a: 0.02, trem: { rate: 26, depth: 0.7 } });
  // the glass rings (glass-like partial ratios, not struck metal)
  T.bell(out, t + 0.05, {
    f: p.pitch * 5, partials: [[1, 1, 1], [2.32, 0.5, 0.6], [4.17, 0.28, 0.4], [6.7, 0.14, 0.25]],
    dur: 0.12 + 0.24 * p.ring, peak: 0.014 + 0.022 * p.ring, a: 0.002,
  });
  // something bounces off: a tink, then it breaks into specks
  const hit = t + 0.19;
  T.bell(out, hit, { f: p.pitch * 7.5, partials: [[1, 1, 1], [2.76, 0.4, 0.5]], drift: 0.97, dur: 0.07, peak: 0.025, a: 0.001 });
  if (p.shatter > 0.02) {
    T.crackle(out, hit + 0.01, { dur: 0.09, rate: 260, f: 7500, to: 3800, spread: 0.5, q: 2.5, len: 0.003, peak: 0.07 * p.shatter, vary: 0.6 });
  }
}

function (T, out, t, p) {
  const f = p.pitch;
  const room = T.reverb(out, t, { time: 0.45, mix: 0.1 + 0.14 * p.pool, tone: 0.3, pre: 0.01 });
  // the bead meets the surface: a sine that bends up, the way a drip rings
  T.osc(room, t, { f: f * 0.7, to: f * 1.5, glide: 0.035, dur: 0.12, peak: 0.055, a: 0.003 });
  // the glassy edge: two thin partials that ring a moment longer than the plink
  T.bell(room, t, { f: f * 3.3, partials: [[1, 1, 1], [2.32, 0.4, 0.5]], dur: 0.15, peak: 0.032 * p.glass, a: 0.002 });
  // the dark pool: a low bubble that swoops up and a hush of noise closing over it
  const at = t + 0.04;
  T.osc(room, at, { f: f * 0.32, to: f * 0.5, glide: 0.1, dur: 0.22, peak: 0.012 + 0.06 * p.pool, a: 0.012 });
  T.noise(room, at, { filter: 'lowpass', f: 520, to: 220, q: 0.8, dur: 0.16, peak: 0.1 * p.pool, a: 0.015 });
  // two ripples, each smaller and a little higher than the last
  for (let k = 0; k < 2; k++) {
    const rf = f * (1.08 + 0.2 * k);
    T.osc(room, t + 0.17 + 0.1 * k, { f: rf, to: rf * 1.35, glide: 0.03, dur: 0.1, peak: (0.026 - 0.01 * k) * (0.25 + 0.75 * p.pool), a: 0.003 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.stars);
  // three characters tilt sideways: a hollow wooden knock with a short slide of air
  for (let k = 0; k < 3; k++) {
    const at = t + k * 0.085;
    T.noise(out, at, { filter: 'bandpass', f: 900 + 120 * k, to: 500, q: 1.6, dur: 0.05, peak: 0.07, a: 0.003 });
    T.osc(out, at, { type: 'triangle', f: 230 + 25 * k, to: 140, dur: 0.06, peak: 0.03, a: 0.003 });
  }
  // the leader lands beside them: a muted thump, not a slam
  const land = t + 0.36;
  T.osc(out, land, { f: 130, to: 52, dur: 0.24, peak: 0.055, a: 0.004 });
  T.noise(out, land, { filter: 'lowpass', f: 800, to: 180, q: 0.8, dur: 0.12, peak: 0.06, a: 0.003 });
  // the gold ribbon links the three: a thin rising shimmer, glassy grains over a faint glide
  const rb = t + 0.42;
  T.osc(out, rb, { f: 520, to: 1900, dur: 0.38, peak: 0.022, a: 0.14, trem: { rate: 14, depth: 0.4 } });
  T.crackle(out, rb, { dur: 0.36, rate: 70, f: 3200, to: 8000, spread: 0.3, q: 2, len: 0.005, peak: 0.04 });
  // the lore stars leap: stacked chimes, each a small glass bell with a warm low partner
  const room = T.reverb(out, t, { time: 0.7, mix: p.space, tone: 0.7 });
  const glass = [[1, 1, 1], [2.32, 0.38, 0.55], [4.1, 0.14, 0.3]];
  const rise = [0, 4, 7, 12];
  const first = t + 0.78;
  for (let k = 0; k < n; k++) {
    const at = first + k * p.gap;
    const f = p.pitch * Math.pow(2, rise[k] / 12);
    const top = k === n - 1;
    T.bell(room, at, { f, partials: glass, dur: top ? 0.85 : 0.65, peak: top ? 0.085 : 0.066, a: 0.003 });
    T.osc(room, at, { f: f / 2, dur: 0.3, peak: 0.024, a: 0.004 });
  }
  // a last glint over the top chime
  T.osc(room, first + (n - 1) * p.gap + 0.03, { f: p.pitch * 4 * Math.pow(2, rise[n - 1] / 12), dur: 0.35, peak: 0.016, a: 0.003 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.9, mix: p.space, tone: 0.7 });
  const L = p.length;
  // all three lines peak at the end of the climb, then stop short for the ping
  T.osc(room, t, { type: 'triangle', f: p.pitch, to: p.pitch * 3, dur: L, peak: 0.05, a: L * 0.92, glide: L, vib: { rate: 6, depth: 10 } });
  T.osc(room, t, { f: p.pitch * 1.5, to: p.pitch * 4.5, dur: L, peak: 0.022, a: L * 0.92, glide: L });
  T.osc(room, t, { f: p.pitch * 2, to: p.pitch * 6, dur: L, peak: 0.017, a: L * 0.92, glide: L, trem: { rate: 12, depth: 0.5 } });
  T.noise(room, t, { filter: 'highpass', f: 3000, to: 9000, q: 0.8, dur: L, peak: 0.01 + 0.04 * p.shimmer, a: L * 0.92, glide: L });
  T.bell(room, t + L, { f: p.pitch * 6, partials: [[1, 1, 1], [2, 0.4, 0.6], [3, 0.25, 0.4]], dur: 0.6, peak: 0.05 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.2, mix: p.space, tone: 0.25 });
  // the toll, and a bell a tritone above that sours it
  T.bell(room, t, { f: p.pitch * 2, partials: [[1, 1, 1], [2.76, 0.5, 0.7], [5.4, 0.3, 0.5]], drift: 0.96, dur: 1.3, peak: 0.056 });
  T.bell(room, t + 0.06, { f: p.pitch * 2 * 1.4142, partials: [[1, 1, 1], [2.76, 0.4, 0.6]], drift: 0.95, dur: 1.1, peak: 0.01 + 0.035 * p.dread });
  // the drone: two saws a few cents apart, filtered shut as it fades
  const dark = T.filter(room, t, { type: 'lowpass', f: 700, to: 150, dur: 1.2, q: 1.5 });
  T.osc(dark, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 0.9, dur: 1.3, peak: 0.035, a: 0.08, detune: -12, vib: { rate: 4.5, depth: 15 } });
  T.osc(dark, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 0.9, dur: 1.3, peak: 0.035, a: 0.08, detune: 12 });
  // whispers: short narrow bursts of breath, spaced unevenly
  let at = t + 0.12;
  for (let k = 0; k < 5; k++) {
    T.noise(room, at, { filter: 'bandpass', f: T.rand(1400, 3200), q: 6, dur: T.rand(0.1, 0.2), peak: 0.04 + 0.18 * p.whisper, a: 0.04 });
    at += T.rand(0.1, 0.22);
  }
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.1, mix: p.space, tone: 0.6 });
  const steps = [0, 2, 4, 7, 9, 12, 14, 16];
  const n = Math.round(p.notes);
  for (let k = 0; k < n; k++) {
    T.pluck(room, t + k * p.speed, { f: p.pitch * Math.pow(2, steps[k] / 12), dur: 0.8, bright: 0.6, peak: 0.07, a: 0.002 });
  }
  // the glow underneath: a fifth and an octave, slowly swelling
  const run = n * p.speed;
  T.osc(room, t, { f: p.pitch * 2, dur: run + 0.7, peak: 0.01 + 0.03 * p.glow, a: 0.15, vib: { rate: 5, depth: 6 } });
  T.osc(room, t, { f: p.pitch * 3, dur: run + 0.7, peak: 0.005 + 0.02 * p.glow, a: 0.2, vib: { rate: 5.5, depth: 6 } });
  // the closing bell, an octave above the last string
  T.bell(room, t + run, { f: p.pitch * Math.pow(2, (steps[n - 1] + 12) / 12), partials: [[1, 1, 1], [2.76, 0.4, 0.5]], dur: 0.8, peak: 0.04 });
}

function (T, out, t, p) {
  const len = p.length;
  // the roar: the cutoff opens with the heat, the level swells then falls
  T.noise(out, t, { filter: 'lowpass', f: 250, to: 900 + 2600 * p.heat, q: 0.8, dur: len, peak: 0.4, a: len * 0.22, glide: len * 0.5 });
  // the ignition: a short bright sizzle and a low thump
  T.noise(out, t, { filter: 'bandpass', f: 1200, to: 6000, q: 1.4, dur: 0.18, peak: 0.1, a: 0.01 });
  T.osc(out, t, { f: 130, to: 45, dur: 0.28, peak: 0.04 + 0.12 * p.weight, a: 0.004 });
  // the magic in it: a quick rising flare over the ignition
  T.osc(out, t, { type: 'triangle', f: 500, to: 2000, dur: 0.22, peak: 0.025, a: 0.01 });
  // embers popping at random moments, fewer and softer toward the end
  const n = Math.round(3 + 11 * p.crackle);
  for (let k = 0; k < n; k++) {
    const at = t + 0.05 + T.rand(0, len - 0.12);
    const fade = 1 - 0.6 * ((at - t) / len);
    T.noise(out, at, { filter: 'highpass', f: T.rand(2500, 6500), q: 0.8, dur: 0.014, peak: T.rand(0.03, 0.08) * fade, a: 0.001 });
  }
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.4, mix: p.space, tone: 0.6 });
  const chord = [0, 4, 7, 12, 14];
  for (let k = 0; k < chord.length; k++) {
    T.osc(room, t + k * 0.035, {
      type: k < 3 ? 'triangle' : 'sine', f: p.pitch * Math.pow(2, chord[k] / 12), dur: 1.3,
      peak: 0.024, a: p.swell, vib: { rate: 5 + k * 0.4, depth: 5 },
    });
  }
  // sparkles drift down from above the chord
  const steps = [19, 16, 14, 12, 9, 7, 4, 2];
  const n = Math.round(2 + 6 * p.sparkle);
  let at = t + p.swell * 0.7;
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, steps[k] / 12) * 2;
    T.osc(room, at, { f, dur: 0.38, peak: 0.028, a: 0.004 });
    T.osc(room, at, { f: f * 2.01, dur: 0.16, peak: 0.008, a: 0.004 });
    at += T.rand(0.05, 0.1);
  }
  T.noise(room, t, { filter: 'highpass', f: 6000, q: 0.8, dur: p.swell + 0.7, peak: 0.004 + 0.02 * p.sparkle, a: p.swell });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.0, mix: p.space, tone: 0.9 });
  // the freeze: frost breathes in while the glass rings
  T.noise(room, t, { filter: 'highpass', f: 6500, to: 4500, q: 0.8, dur: 0.55, peak: 0.01 + 0.07 * p.frost, a: 0.1 });
  T.bell(room, t, {
    f: p.pitch,
    partials: [[1, 1, 1], [2.32, 0.6, 0.6], [3.87, 0.4, 0.5], [5.9, 0.25, 0.35], [8.1, 0.12, 0.2]],
    dur: 1.0, peak: 0.055, a: 0.006,
  });
  // the shards: a pentatonic fall, each a tiny struck bell, loosely spaced
  const steps = [12, 9, 7, 4, 2, 0, -3, -5, -8];
  const n = Math.round(p.shards);
  let at = t + 0.12;
  for (let k = 0; k < n; k++) {
    T.bell(room, at, {
      f: p.pitch * Math.pow(2, steps[k] / 12), partials: [[1, 1, 1], [2.76, 0.4, 0.5]],
      dur: 0.32, peak: 0.04 - 0.002 * k,
    });
    at += T.rand(0.045, 0.09);
  }
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.6, mix: p.space, tone: 0.5 });
  // the strike
  T.noise(room, t, { filter: 'highpass', f: 6000, to: 2000, q: 0.8, dur: 0.09, peak: 0.08, a: 0.001 });
  T.osc(room, t, { type: 'sawtooth', f: p.bright, to: p.bright * 0.08, dur: 0.12, peak: 0.025, a: 0.001 });
  T.fm(room, t, { f: p.bright * 0.7, to: p.bright * 0.1, ratio: 1.41, index: 3, index1: 0.5, dur: 0.18, peak: 0.03, a: 0.001 });
  // the forks: bandpassed crackles that thin and soften as they go
  const n = Math.round(3 + 8 * p.crackle);
  let at = t + 0.04;
  for (let k = 0; k < n; k++) {
    const fade = 1 - k / (n + 2);
    T.noise(room, at, { filter: 'bandpass', f: T.rand(1500, 5000), q: 2, dur: T.rand(0.012, 0.035), peak: T.rand(0.035, 0.07) * fade, a: 0.001 });
    at += T.rand(0.02, 0.075);
  }
  // the thunder: a lowpass that closes as the roll fades
  T.noise(room, t + 0.03, { filter: 'lowpass', f: 700, to: 80, q: 0.9, dur: p.thunder, peak: 0.08 + 0.3 * p.rumble, a: 0.07 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.3, mix: p.space, tone: 0.6 });
  const s = p.size;
  // two narrow, resonant sweeps crossing: the vortex
  T.noise(room, t, { filter: 'bandpass', f: 180, to: 2400, q: 4, dur: s, peak: 0.2 + 0.16 * p.swirl, a: s * 0.8 });
  T.noise(room, t, { filter: 'bandpass', f: 2800, to: 300, q: 4, dur: s, peak: 0.11 + 0.1 * p.swirl, a: s * 0.8 });
  // the throb: two near-unison triangles beating, the swirl amount sets how hard they pulse
  T.osc(room, t, { type: 'triangle', f: p.pitch, to: p.pitch * 1.5, dur: s + 0.5, peak: 0.04, a: s * 0.8, trem: { rate: 3 + 6 * p.swirl, depth: 0.3 + 0.5 * p.swirl } });
  T.osc(room, t, { type: 'triangle', f: p.pitch * 1.007, to: p.pitch * 1.51, dur: s + 0.5, peak: 0.04, a: s * 0.8 });
  // it opens
  const at = t + s * 0.9;
  T.osc(room, at, { f: p.pitch * 2, to: p.pitch * 0.6, dur: 0.45, peak: 0.06, a: 0.01 });
  T.bell(room, at, {
    f: p.pitch * 4, partials: [[1, 1, 1], [1.5, 0.6, 0.9], [2, 0.5, 0.8], [3, 0.3, 0.6], [4.01, 0.15, 0.4]],
    dur: 1.1, peak: 0.035, a: 0.01,
  });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.5, mix: 0.15, tone: 0.6 });
  const n = Math.round(p.bubbles);
  for (let k = 0; k < n; k++) {
    const at = t + (k / n) * p.span + T.rand(0, 0.5 * p.span / n);
    const f = p.pitch * T.rand(0.7, 1.8);
    const len = T.rand(0.05, 0.11);
    T.osc(room, at, { f, to: f * 2.2, dur: len, peak: T.rand(0.05, 0.09), a: 0.004 });
    T.osc(room, at, { f: f * 3, to: f * 6.6, dur: len * 0.5, peak: 0.012, a: 0.004 });
  }
  // the gurgle bed
  T.noise(room, t, { filter: 'lowpass', f: 300, to: 220, q: 0.7, dur: p.span + 0.1, peak: 0.1, a: 0.1 });
  // glimmers: high pings above the bubbling
  const g = Math.round(1 + 3 * p.glimmer);
  for (let k = 0; k < g; k++) {
    T.osc(room, t + T.rand(0.05, p.span), { f: p.pitch * T.rand(8, 12), dur: 0.3, peak: 0.005 + 0.022 * p.glimmer, a: 0.004 });
  }
}

function (T, out, t, p) {
  const steps = [0, 4, 7, 12, 16, 19, 24];
  const n = Math.round(p.notes);
  const room = T.reverb(out, t, { time: 0.9, mix: p.space, tone: 0.7 });
  for (let k = 0; k < n; k++) {
    const f = p.pitch * Math.pow(2, steps[k] / 12);
    const at = t + k * p.gap;
    const l = 1 - 0.08 * k;
    T.osc(room, at, { type: 'triangle', f, dur: 0.22, peak: 0.06 * l, a: 0.004 });
    T.osc(room, at, { f: f * 2, to: f * 2.02, dur: 0.12, peak: 0.02 * l, a: 0.004 });
  }
  T.noise(room, t, { filter: 'highpass', f: 5000, to: 8000, q: 0.8, dur: n * p.gap + 0.25, peak: 0.06 * p.shimmer, a: 0.06 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.1, mix: p.space, tone: 0.7 });
  const g = p.gather;
  const b = p.bloom;
  // the swirl: a bandpassed breath opening upward over a rising triangle
  T.noise(room, t, { filter: 'bandpass', f: 600, to: 5200, q: 1.5, dur: g + 0.03, peak: 0.1, a: g * 0.85 });
  T.osc(room, t, { type: 'triangle', f: p.pitch * 0.5, to: p.pitch, dur: g + 0.03, peak: 0.05, a: g * 0.85 });
  // the bloom: a bell whose upper partials arrive with the bloom amount
  const at = t + g;
  T.bell(room, at, {
    f: p.pitch,
    partials: [[1, 1, 1], [2, 0.3 + 0.3 * b, 0.75], [3.01, 0.3 * b, 0.55], [4.2, 0.2 * b, 0.4], [5.43, 0.12 * b, 0.28]],
    dur: 1.0, peak: 0.065,
  });
  T.noise(room, at, { filter: 'highpass', f: 5000, to: 8000, q: 0.8, dur: 0.14, peak: 0.02 + 0.04 * b, a: 0.004 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.9, mix: p.space, tone: 0.7 });
  // vanish: a sine and a highpassed shimmer shooting upward
  T.osc(room, t, { f: p.pitch, to: p.pitch * 6, dur: 0.14, peak: 0.07, a: 0.01, trem: { rate: 40, depth: 0.5 } });
  T.noise(room, t, { filter: 'highpass', f: 3000, to: 9000, q: 0.8, dur: 0.14, peak: 0.07, a: 0.01 });
  // arrive: the rush comes back down, then a bell lands
  const at = t + 0.14 + p.gap;
  const f = p.pitch * p.reach;
  T.osc(room, at, { f: f * 5, to: f, dur: 0.12, peak: 0.05, a: 0.03, trem: { rate: 40, depth: 0.5 } });
  T.noise(room, at, { filter: 'highpass', f: 9000, to: 3000, q: 0.8, dur: 0.12, peak: 0.05, a: 0.03 });
  T.bell(room, at + 0.12, { f: f * 2, partials: [[1, 1, 1], [2.76, 0.4, 0.5], [5.4, 0.2, 0.3]], dur: 0.6, peak: 0.07 });
}

function (T, out, t, p) {
  const L = p.length;
  // the strike
  T.noise(out, t, { filter: 'highpass', f: 6000, to: 2500, q: 0.8, dur: 0.035, peak: 0.03 + 0.07 * p.snap, a: 0.001 });
  T.osc(out, t, { type: 'square', f: 3200, to: 700, glide: 0.05, dur: 0.06, peak: 0.008 + 0.02 * p.snap, a: 0.001 });
  // the buzz: saturate hard, then trim, flicker the level and take the top edge off
  const dc = T.dcblock(out);
  const lp = T.filter(dc, t, { type: 'lowpass', f: 3200, q: 0.7 });
  const trim = T.gain(lp, 0.28);
  T.lfo(trim, t, { rate: 41, to: 29, depth: 0.2, dur: L });
  const sat = T.drive(trim, t, { amount: 0.7, ref: 0.1 });
  const hold = { dur: L, a: 0.004, s: 1, d: 0.03, r: Math.min(0.12, L * 0.4) };
  T.osc(sat, t, Object.assign({ type: 'sawtooth', f: p.pitch }, hold, { peak: 0.06 }));
  T.osc(sat, t, Object.assign({ type: 'sawtooth', f: p.pitch * 1.5 }, hold, { peak: 0.03 }));
  // the spitting
  T.crackle(out, t, { dur: L, rate: 30 + 170 * p.crackle, f: 4500, to: 2500, spread: 0.8, q: 1.2, len: 0.005, peak: 0.045, vary: 0.8 });
}

function (T, out, t, p) {
  const legs = Math.round(p.turns) + 1;
  const leg = p.length / legs;
  for (let k = 0; k < legs; k++) {
    const at = t + k * leg;
    // the pulse travels left to right across the board, a stretch of it per run
    const lane = T.pan(out, at, { x: -0.9 + (1.8 * k) / legs, to: -0.9 + (1.8 * (k + 1)) / legs, dur: leg });
    const f = p.pitch * Math.pow(1.12, k);
    const run = { glide: leg, dur: leg, a: 0.003, s: 1, d: 0.01, r: 0.008 };
    T.pulse(lane, at, Object.assign({ duty: 0.2, f, to: f * 2.4, peak: 0.035, lp: 5000 }, run));
    T.osc(lane, at, Object.assign({ f: f * 2, to: f * 4.8, peak: 0.02 }, run));
    // the corner
    if (k < legs - 1) T.tick(lane, at + leg, { f: 4500, q: 2, dur: 0.01, peak: 0.05 });
  }
  // the node at the end of the trace lights up
  const end = t + p.length;
  T.bell(out, end, { f: p.pitch * 5, partials: [[1, 1, 1], [2.4, 0.4, 0.5]], dur: 0.25, peak: 0.015 + 0.05 * p.glow });
  T.tick(out, end, { f: 6000, q: 1.5, dur: 0.01, peak: 0.02 + 0.03 * p.glow });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.5, mix: 0.18, tone: 0.8 });
  const n = Math.round(p.pops);
  for (let k = 0; k < n; k++) {
    const at = t + k * 0.065;
    const f = p.pitch * (k % 2 === 0 ? 1 : 1.18);
    T.noise(room, at, { filter: 'bandpass', f: 950, to: 380, q: 0.9, dur: 0.07, peak: 0.2, a: 0.002 });
    T.osc(room, at, { f, to: f * 0.45, glide: 0.05, dur: 0.1, peak: 0.09, a: 0.002 });
    T.tick(room, at, { f: 5200, q: 1, dur: 0.01, peak: 0.07, jitter: 0.5 });
  }
  // the shower: paper flutter thinning out, one source under one slow envelope
  const span = p.length;
  const start = t + 0.05 + (n - 1) * 0.065;
  const shower = T.bus(room, start, { a: 0.03, dur: span, tail: 0.04 });
  T.crackle(shower, start, { dur: span, rate: 150, f: 5200, to: 3200, q: 0.9, spread: 0.7, len: 0.012, peak: 0.16, vary: 0.8 });
  T.crackle(shower, start, { dur: span, rate: 50, f: 2600, to: 1800, q: 0.7, spread: 0.6, len: 0.022, peak: 0.08, vary: 0.8 });
  // glints: high pentatonic pings, more of them early
  const glints = Math.round(3 + 9 * p.glitter);
  const notes = [0, 2, 4, 7, 9, 12];
  for (let k = 0; k < glints; k++) {
    const u = Math.pow(T.rand(0, 1), 1.5);
    const f = 1568 * Math.pow(2, notes[Math.floor(T.rand(0, notes.length))] / 12);
    T.bell(room, start + 0.02 + span * 0.9 * u, {
      f, partials: [[1, 1, 1], [2.76, 0.3, 0.4]], dur: 0.12, peak: 0.022 * (1 - 0.5 * u), a: 0.002,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const top = p.pitch;
  if (p.on >= 0.5) {
    // the degauss: a low thump and a ring that wobbles as it dies
    T.osc(out, t, { f: 68, to: 40, glide: 0.3, dur: 0.4, peak: 0.04 + 0.07 * p.thump, a: 0.004 });
    T.osc(out, t, { f: 125, to: 95, glide: 0.5, dur: 0.55, peak: 0.015 + 0.035 * p.thump, a: 0.004, trem: { rate: 13, depth: 0.9 } });
    T.noise(out, t, { filter: 'lowpass', f: 500, to: 120, q: 0.8, dur: 0.14, peak: 0.02 + 0.1 * p.thump, a: 0.002 });
    // the whine climbs while the picture warms, with static blooming under it
    T.osc(out, t + 0.06, { f: top * 0.2, to: top, glide: L, dur: L + 0.2, peak: 0.018, a: L * 0.7, s: 1, d: 0.02, r: 0.18 });
    T.noise(out, t + 0.06, { filter: 'highpass', f: 3500, q: 0.7, dur: L + 0.15, peak: 0.02, a: L * 0.8, s: 1, d: 0.02, r: 0.15 });
    T.tick(out, t + 0.06 + L, { f: 2500, q: 1, dur: 0.012, peak: 0.03 });
  } else {
    const C = L * 0.5;
    // the whine falls away and the picture collapses: a zoop down, a rush of noise, a soft thump
    T.osc(out, t, { f: top, to: top * 0.2, glide: C, dur: C + 0.05, peak: 0.018, a: 0.004, s: 1, d: 0.01, r: 0.04 });
    T.osc(out, t, { f: 1400, to: 90, glide: 0.22, dur: 0.26, peak: 0.06, a: 0.004 });
    T.noise(out, t, { filter: 'bandpass', f: 6000, to: 300, q: 1.2, dur: 0.25, peak: 0.1, a: 0.004 });
    T.osc(out, t + 0.02, { f: 70, to: 35, glide: 0.15, dur: 0.22, peak: 0.03 + 0.06 * p.thump, a: 0.004 });
    // the last dot: a tiny pip that rings for a moment
    T.bell(out, t + C, { f: top * 0.35, partials: [[1, 1, 1], [2, 0.3, 0.5]], dur: 0.32, peak: 0.03, a: 0.002 });
    T.tick(out, t + C, { f: 5000, q: 1.5, dur: 0.008, peak: 0.03 });
  }
}

function (T, out, t, p) {
  const D = p.distance;
  const f = p.pitch;
  const w = p.width;
  // the throw
  T.noise(out, t, { filter: 'bandpass', f: 1800, to: 5000, q: 1.2, dur: 0.09, peak: 0.16, a: 0.006 });
  T.osc(out, t, { f: 180, to: 110, glide: 0.06, dur: 0.08, peak: 0.04, a: 0.004 });
  // out: it recedes, so the pitch falls and the level dies away
  const away = T.pan(out, t, { x: -0.3 * w, to: 0.9 * w, dur: D });
  const outBus = T.bus(away, t, { peak: 1, a: 0.012, dur: D + 0.02, tail: 0.05, fade: 0.04 });
  const whir = { dur: D + 0.03, a: 0.004, s: 1, d: 0.01, r: 0.02 };
  T.osc(outBus, t, Object.assign({ type: 'sawtooth', f: f * 1.12, to: f * 0.78, glide: D, peak: 0.05, trem: { rate: p.spin, depth: 0.7 }, lp: { f: 2600, to: 900, glide: D } }, whir));
  T.noise(outBus, t, Object.assign({ filter: 'bandpass', f: f * 1.6, to: f * 1.1, q: 6, glide: D, peak: 0.3 }, whir));
  // back: it approaches, so the pitch and the level climb until it is in the hand
  const tb = t + D;
  const back = D * 0.95;
  const home = T.pan(out, tb, { x: 0.9 * w, to: 0, dur: back });
  const backBus = T.bus(home, tb, { peak: 1, a: back, dur: back + 0.06 });
  const ret = { dur: back + 0.07, a: 0.004, s: 1, d: 0.01, r: 0.03 };
  T.osc(backBus, tb, Object.assign({ type: 'sawtooth', f: f * 0.78, to: f * 1.3, glide: back, peak: 0.05, trem: { rate: p.spin, depth: 0.7 }, lp: { f: 900, to: 2800, glide: back } }, ret));
  T.noise(backBus, tb, Object.assign({ filter: 'bandpass', f: f * 1.1, to: f * 1.9, q: 6, glide: back, peak: 0.3 }, ret));
  // the catch
  const tc = tb + back;
  T.tick(out, tc, { f: 2600, q: 2.5, dur: 0.02, peak: 0.1, blip: 170, blipTo: 90, blipPeak: 0.07, blipDur: 0.07 });
  T.bell(out, tc + 0.004, { f: 1900, partials: [[1, 1, 1], [2.76, 0.4, 0.5]], dur: 0.2, peak: 0.02 });
}

function (T, out, t, p) {
  const H = p.height;
  const sky = T.reverb(out, t, { time: 0.9, mix: p.space, tone: 0.6 });
  // the climb: a thin rising whistle with a breathy hiss
  T.osc(out, t, { f: 650, to: 2700, dur: H, peak: 0.035, a: 0.05, s: 1, d: 0.01, r: 0.03, vib: { rate: 17, depth: 30 } });
  T.noise(out, t, { filter: 'bandpass', f: 2000, to: 4800, q: 6, dur: H, peak: 0.06, a: 0.08, s: 1, d: 0.01, r: 0.03 });
  // the burst
  const b = t + H;
  T.noise(sky, b, { filter: 'lowpass', f: 3500, to: 180, q: 0.7, dur: 0.45, peak: 0.07 + 0.07 * p.boom, a: 0.003 });
  T.osc(sky, b, { f: 150, to: 42, glide: 0.22, dur: 0.38, peak: 0.015 + 0.07 * p.boom, a: 0.004 });
  T.tick(sky, b, { f: 3600, q: 0.8, dur: 0.03, peak: 0.1, blip: 900, blipTo: 300, blipPeak: 0.06, blipDur: 0.05 });
  // embers: a hiss that blooms and falls, then the crackle
  T.noise(sky, b + 0.02, { filter: 'highpass', f: 3200, to: 6000, q: 0.8, dur: 0.55, peak: 0.05, a: 0.03 });
  if (p.crackle > 0.02) {
    const fall = T.bus(sky, b + 0.08, { a: 0.01, dur: 0.9, tail: 0.03 });
    T.crackle(fall, b + 0.08, { dur: 0.9, rate: 110, f: 4800, to: 2800, q: 0.9, spread: 0.8, len: 0.008, peak: 0.12 * p.crackle, vary: 0.9 });
    const glints = Math.round(3 + 6 * p.crackle);
    for (let k = 0; k < glints; k++) {
      const u = T.rand(0, 1);
      T.bell(sky, b + 0.1 + 0.8 * u, {
        f: T.rand(1800, 4800), partials: [[1, 1, 1], [2.76, 0.3, 0.4]], dur: 0.14, peak: 0.02 * (1 - 0.6 * u), a: 0.002,
      });
    }
  }
}

function (T, out, t, p) {
  const L = p.length;
  const swell = L * 0.45;
  // the comb: bands a major third apart glide up together, peaking at the middle of the sweep
  const ratios = [1, 1.26, 1.59];
  for (let i = 0; i < 3; i++) {
    T.noise(out, t, { filter: 'bandpass', f: p.pitch * ratios[i], to: p.pitch * ratios[i] * 1.6, q: 14, dur: L, peak: 0.2 / (1 + 0.25 * i), a: swell });
  }
  // the breath of air the light rides on
  T.noise(out, t, { filter: 'bandpass', f: 1800, to: 2600, q: 0.6, dur: L + 0.05, peak: 0.015 + 0.04 * p.breath, a: swell });
  // the glints
  const n = 2 + Math.round(4 * p.shine);
  for (let k = 0; k < n; k++) {
    const at = t + L * (0.2 + (0.6 * (k + T.rand(0.1, 0.9))) / n);
    T.osc(out, at, { f: T.rand(3500, 7500), dur: 0.07, peak: 0.02, a: 0.001 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const n = Math.round(p.teeth);
  // tick times: the spin speeds up and slows down (a hump), so ticks bunch in the middle
  const M = 200;
  const cum = [0];
  for (let i = 1; i <= M; i++) cum.push(cum[i - 1] + 0.35 + 0.65 * Math.sin((Math.PI * (i - 0.5)) / M));
  let at = 0;
  for (let k = 0; k < n; k++) {
    const goal = ((k + 0.5) / n) * cum[M];
    while (at < M - 1 && cum[at + 1] < goal) at++;
    const u = (at + (goal - cum[at]) / (cum[at + 1] - cum[at])) / M;
    const when = t + 0.02 + (L - 0.04) * u;
    const big = k % 2 === 1;
    T.tick(out, when, { f: big ? 3100 : 2200, q: 3, dur: 0.007, peak: 0.15, jitter: 0.4, blip: big ? 620 : 900, blipPeak: 0.012, blipDur: 0.012 });
    if (k % 3 === 2) T.tick(out, when, { f: 900, q: 1.4, dur: 0.012, peak: 0.08, blip: 160, blipTo: 110, blipPeak: 0.02, blipDur: 0.03 });
  }
  // engage and release
  T.tick(out, t, { f: 800, q: 1.2, dur: 0.02, peak: 0.06, blip: 150, blipTo: 100, blipPeak: 0.05, blipDur: 0.05 });
  T.tick(out, t + L - 0.03, { f: 700, q: 1.2, dur: 0.015, peak: 0.04, blip: 140, blipTo: 100, blipPeak: 0.03, blipDur: 0.04 });
  if (p.whine > 0.02) {
    const w = 0.03 * p.whine;
    T.pulse(out, t, {
      duty: 0.3, f: p.pitch, to: p.pitch * 4, glide: L * 0.46, dur: L * 0.56, peak: w, a: L * 0.2, s: 1, d: 0.01, r: L * 0.1, lp: 2600,
    });
    T.pulse(out, t + L * 0.46, {
      duty: 0.3, f: p.pitch * 4, to: p.pitch * 1.5, dur: L * 0.54, peak: w, a: L * 0.1, s: 1, d: 0.01, r: L * 0.3, lp: 2600,
    });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.slices);
  const slot = 0.09;
  const gap = 0.025;
  // one lane per colour: its own pan, its own crusher, its own waveform
  const lanes = [-1, 0, 1].map((x) => T.crush(T.pan(out, t, { x }), t, { bits: 8 - 4 * p.harsh, ref: 0.1 }));
  const types = ['sawtooth', 'square', 'triangle'];
  const peaks = [0.03, 0.026, 0.05];
  for (let k = 0; k < n; k++) {
    const at = t + k * (slot + gap);
    // the first slice sits on the pitch, later ones wander by up to an octave
    const f = k === 0 ? p.pitch : p.pitch * Math.pow(2, T.rand(-1, 1));
    const rise = T.rand() < 0.5 ? 1.5 : 0.67;
    const reps = 3 + Math.floor(T.rand(0, 3));
    const sl = slot / reps;
    for (let r = 0; r < reps; r++) {
      for (let c = 0; c < 3; c++) {
        const off = (c - 1) * p.split;
        T.osc(lanes[c], at + r * sl + Math.max(0, off) * 0.006, {
          type: types[c], f: f * Math.pow(2, (off * 90) / 1200), to: f * rise, glide: sl, dur: sl,
          peak: peaks[c], a: 0.002, s: 1, d: 0.002, r: 0.003,
        });
      }
    }
    // static where the picture tears between slices
    T.noise(lanes[1], at + slot, { filter: 'none', dur: gap, peak: 0.02 + 0.05 * p.harsh, a: 0.002, s: 1, d: 0.002, r: 0.004 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const n = Math.round(p.pulses);
  for (let k = 0; k < n; k++) {
    const at = t + (k / n) * L * 0.8;
    const lv = Math.pow(0.8, k);
    T.osc(out, at, { f: p.pitch * 1.6, to: p.pitch, glide: 0.08, dur: 0.3, peak: 0.08 * lv, a: 0.006 });
    // the second harmonic, so small speakers still hear the pulse
    T.osc(out, at, { type: 'triangle', f: p.pitch * 2, dur: 0.2, peak: 0.026 * lv, a: 0.006 });
  }
  // the wash: detuned saws and a square, opened by a resonant lowpass, then combed
  const comb = T.delay(out, t, { time: 0.0125, fb: 0.55, mix: 0.6, tone: 9000 });
  const lp = T.filter(comb, t, { type: 'lowpass', f: 250, to: 1500 + 5000 * p.bright, dur: L, q: 5 });
  const hold = { dur: L + 0.15, a: L * 0.5, s: 1, d: 0.05, r: 0.15 };
  T.osc(lp, t, Object.assign({ type: 'sawtooth', f: p.pitch * 4, peak: 0.024 }, hold));
  T.osc(lp, t, Object.assign({ type: 'sawtooth', f: p.pitch * 4 * 1.007, peak: 0.024 }, hold));
  T.osc(lp, t, Object.assign({ type: 'square', f: p.pitch * 2, peak: 0.012 }, hold));
  // a band of air riding the same sweep, so the wash has texture and not only pitch
  T.noise(comb, t, Object.assign({ filter: 'bandpass', f: 400, to: 2000 + 5000 * p.bright, q: 1.5, glide: L, peak: 0.05 }, hold));
  // the horizon
  T.bell(out, t + L * 0.9, { f: p.pitch * 28, partials: [[1, 1, 1], [2.76, 0.3, 0.4]], dur: 0.4, peak: 0.04 });
}

function (T, out, t, p) {
  const on = p.on >= 0.5;
  const L = p.length;
  const S = 1 + Math.round(5 * p.stutter);
  const slot = L / S;
  // off starts with the chord, so the shimmer waits for it
  const lead = on ? 0 : 0.18;
  const ladder = [1, 2, 3, 4, 5];
  // the shimmer's centre at x (0 start of the shimmer, 1 end): it always travels between 0.35 of the note and the note
  const centre = (x) => p.pitch * 0.35 * Math.pow(1 / 0.35, on ? x : 1 - x);
  for (let k = 0; k < S; k++) {
    const x0 = k / S;
    const x1 = (k + 1) / S;
    const solid = on ? k === S - 1 : k === 0;
    const len = solid ? slot : slot * T.rand(0.4, 0.8);
    const at = t + lead + k * slot;
    const level = on ? 0.35 + 0.65 * x1 : 1 - 0.8 * x0;
    const gate = T.bus(out, at, { peak: level, a: 0.003, dur: len, s: 1, d: 0.003, r: 0.004 });
    for (let i = 0; i < ladder.length; i++) {
      T.noise(gate, at, {
        filter: 'bandpass', f: centre(x0) * ladder[i], to: centre(x1) * ladder[i], q: 10, glide: len,
        dur: len + 0.01, peak: 0.4 / Math.sqrt(ladder[i]), a: 0.002, s: 1, d: 0.001, r: 0.005,
      });
    }
    if (!solid) T.tick(out, at, { f: 7000, q: 1, dur: 0.006, peak: 0.02 });
  }
  // the chord: it rings out on, and on off it is cut short as the shimmer takes over
  const at = on ? t + L : t;
  const hold = on ? 0.42 : lead + 0.05;
  const shape = on ? { a: 0.01, dur: hold } : { a: 0.01, dur: hold, s: 1, d: 0.02, r: 0.06 };
  T.osc(out, at, Object.assign({ f: p.pitch, peak: 0.05 }, shape));
  T.osc(out, at, Object.assign({ f: p.pitch * 1.004, peak: 0.03, trem: { rate: 7, depth: 0.5 } }, shape));
  T.osc(out, at, Object.assign({ type: 'triangle', f: p.pitch * 2, peak: 0.022 }, shape));
  T.osc(out, at, Object.assign({ f: p.pitch * 3, peak: 0.012 }, shape));
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.4, mix: p.space, tone: 0.6 });
  const th = p.thick;
  const f = p.pitch * (1 - 0.4 * th);
  // the drop: the pitch bends up as the bubble forms, a tick where the surface breaks
  T.osc(room, t, { f: f * (0.5 - 0.1 * th), to: f * 1.15, glide: 0.08 + 0.1 * th, dur: 0.14 + 0.1 * th, peak: 0.07, a: 0.003 });
  T.tick(room, t, { f: 3200, q: 1.5, dur: 0.008, peak: 0.02 * (1 - th) });
  // the rings: smaller plinks, lower and quieter, further apart each time
  const n = Math.round(p.rings);
  let at = t + 0.1 + 0.03 * th;
  for (let k = 0; k < n; k++) {
    const rf = f * (0.95 - 0.05 * k);
    T.osc(room, at, { f: rf, to: rf * 1.2, glide: 0.05, dur: 0.08 + 0.05 * th, peak: 0.04 * Math.pow(0.6, k), a: 0.003 });
    at += 0.05 + 0.02 * k + 0.04 * th;
  }
}

function (T, out, t, p) {
  const L = p.length;
  const up = p.up >= 0.5;
  const lo = p.pitch;
  const hi = p.pitch * 2.4;
  const a = up ? lo : hi;
  const b = up ? hi : lo;
  const i0 = 0.8;
  const i1 = 0.8 + 4.2 * p.goo;
  const ia = up ? i0 : i1;
  const ib = up ? i1 : i0;
  // the wobbling lowpass every voice plays through
  const clean = T.dcblock(out);
  const wah = T.filter(clean, t, { type: 'lowpass', f: up ? 500 : 2600, to: up ? 2600 : 500, dur: L, q: 3 });
  T.lfo(wah, t, { param: 'frequency', rate: p.wobble, to: p.wobble * 1.5, depth: 380, dur: L + 0.04, a: 0.05 });
  T.fm(wah, t, { f: a, to: b, ratio: 1, index: ia, index1: ib, dur: L, peak: 0.05, a: L * 0.25, tail: 0.15 });
  T.fm(wah, t, { f: a * 1.007, to: b * 1.007, ratio: 2, index: ia * 0.7, index1: ib * 0.7, dur: L, peak: 0.025, a: L * 0.25, tail: 0.15 });
  // membrane bloops: three small pops that follow the pitch up or down
  for (let k = 0; k < 3; k++) {
    const u = 0.2 + 0.6 * ((k + T.rand(0.1, 0.9)) / 3);
    const f = a * Math.pow(b / a, u) * 3;
    T.osc(out, t + L * u, { f, to: f * (up ? 1.5 : 0.7), dur: 0.07, peak: 0.014, a: 0.004 });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.flickers);
  // each strike gets longer and each gap shorter; scale the whole run to the length
  const ons = [];
  const gaps = [];
  let total = 0;
  for (let k = 0; k < n; k++) {
    const u = k / n;
    ons.push((0.02 + 0.07 * u) * T.rand(0.8, 1.2));
    gaps.push((0.07 * (1 - u) + 0.015) * T.rand(0.8, 1.2));
    total += ons[k] + gaps[k];
  }
  const sc = p.length / total;
  let at = t;
  for (let k = 0; k < n; k++) {
    const u = k / n;
    const on = ons[k] * sc;
    const f = p.pitch * T.rand(0.98, 1.02);
    const lp = T.filter(out, at, { type: 'lowpass', f: 500 + 700 * u, to: 1100 + 1300 * u, dur: on, q: 1.5 });
    T.tick(out, at, { f: 3600, q: 1.2, dur: 0.01, peak: 0.03 + 0.07 * p.buzz, jitter: 1 });
    T.osc(lp, at, { type: 'sawtooth', f, dur: on, peak: 0.055, a: 0.003, s: 1, d: 0.004, r: 0.006 });
    T.osc(lp, at, { type: 'square', f: f * 2, dur: on, peak: 0.02, a: 0.003, s: 1, d: 0.004, r: 0.006 });
    T.noise(out, at, { filter: 'bandpass', f: 2200, q: 1.5, dur: on, peak: 0.02 + 0.08 * p.buzz, a: 0.003, s: 1, d: 0.004, r: 0.006 });
    at += (ons[k] + gaps[k]) * sc;
  }
  // the tube holds: a steady hum with a sizzle on top, fading out after about half a second
  const hum = 0.55;
  const hp = T.filter(out, at, { type: 'lowpass', f: 700, to: 1100, dur: 0.1, q: 1.2 });
  T.osc(hp, at, { type: 'sawtooth', f: p.pitch, dur: hum, peak: 0.05, a: 0.01, s: 1, d: 0.05, r: 0.2 });
  T.osc(hp, at, { f: p.pitch * 2, dur: hum, peak: 0.03, a: 0.01, s: 1, d: 0.05, r: 0.2 });
  T.osc(out, at, { f: p.pitch * 0.5, dur: hum, peak: 0.02, a: 0.01, s: 1, d: 0.05, r: 0.2 });
  T.crackle(out, at, { dur: hum - 0.1, rate: 30 + 40 * p.buzz, f: 4500, spread: 0.5, q: 1.2, len: 0.004, peak: 0.01 + 0.025 * p.buzz });
}

function (T, out, t, p) {
  const L = p.length;
  const top = 1800 + 2600 * p.bright;
  const clean = T.dcblock(out);
  // ignition: a whump and a puff
  T.noise(clean, t, { filter: 'lowpass', f: 1100, to: 130, q: 0.8, dur: 0.3, peak: 0.16, a: 0.012 });
  T.osc(clean, t, { f: 95, to: 42, dur: 0.32, peak: 0.1, a: 0.01 });
  if (p.crackle > 0.02) {
    T.crackle(clean, t, { dur: 0.5, rate: 150, f: 2400, to: 1100, spread: 0.8, len: 0.007, q: 0.9, peak: 0.08 * p.crackle });
  }
  // the engine rumble: low noise and a growling saw beating at the shake rate
  T.noise(clean, t + 0.05, { filter: 'lowpass', f: 150, to: 250, q: 0.8, dur: L + 0.35, peak: 0.1 + 0.16 * p.power, a: 0.25, s: 1, d: 0.05, r: L * 0.4, tail: 0.01, fade: 0.1 });
  T.osc(clean, t + 0.05, {
    type: 'sawtooth', f: 52, to: 80, glide: L, dur: L + 0.3, peak: 0.01 + 0.05 * p.power, a: 0.25, s: 1, d: 0.05, r: L * 0.4, tail: 0.01, fade: 0.1,
    lp: 420, trem: { rate: 19, depth: 0.5 },
  });
  // the roar climbing, then receding
  T.noise(clean, t + 0.1, { filter: 'lowpass', f: 500, to: top, q: 0.9, glide: L * 0.65, dur: L * 0.7, peak: 0.19, a: L * 0.45, s: 1, d: 0.02, r: L * 0.15 });
  T.noise(clean, t + 0.1 + L * 0.55, { filter: 'lowpass', f: top, to: 260, q: 0.9, dur: L * 0.3 + 0.55, peak: 0.19, a: L * 0.15, tail: 0.01, fade: 0.1 });
  if (p.crackle > 0.02) {
    T.crackle(clean, t + 0.2, { dur: L * 0.9, rate: 200, f: 1000, to: 2800, spread: 1, len: 0.01, q: 0.8, peak: 0.1 * p.crackle });
  }
}

function (T, out, t, p) {
  const n = Math.round(p.chars);
  const step = p.length / n;
  const blip = Math.max(0.014, Math.min(0.03, step * 1.1));
  for (let k = 0; k < n; k++) {
    const u = k / n;
    // random semitones, pulled in toward the note as the letters resolve
    const semi = Math.round(T.rand(-14, 14) * Math.pow(1 - u, 1.4));
    const f = p.pitch * Math.pow(2, semi / 12);
    const at = t + k * step;
    T.pulse(out, at, { duty: 0.35, f, to: f * 1.06, dur: blip, peak: 0.035, a: 0.002, s: 1, d: 0.004, r: 0.01, lp: 4500 });
    if (k % 2 === 0) T.tick(out, at, { f: 6000, q: 1, dur: 0.005, peak: 0.015, jitter: 1 });
  }
  // the lock
  const at = t + p.length;
  const ring = 0.25 + 0.25 * p.lock;
  T.osc(out, at, { type: 'triangle', f: p.pitch, dur: ring, peak: 0.07, a: 0.004 });
  T.bell(out, at, { f: p.pitch * 2, partials: [[1, 1, 1], [3, 0.3, 0.6]], dur: ring + 0.05, peak: 0.03 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 0.5, mix: 0.2, tone: 0.85 });
  const glass = [[1, 1, 1], [2.32, 0.6, 0.5], [4.1, 0.3, 0.3]];
  // the impact
  T.tick(out, t, { f: 3800, q: 0.7, dur: 0.012, peak: 0.06 + 0.08 * p.crack, blip: 420, blipTo: 160, blipPeak: 0.02 + 0.06 * p.crack, blipDur: 0.04 });
  // the splinters: a cluster of short bright rings and a rush of hiss in the first 90 ms
  T.noise(room, t, { filter: 'highpass', f: 3500, to: 7000, q: 0.8, dur: 0.22, peak: 0.09, a: 0.003 });
  for (let k = 0; k < 12; k++) {
    T.bell(room, t + T.rand(0, 0.09), {
      f: T.rand(1800, 8500) * p.pitch, partials: glass, dur: T.rand(0.06, 0.2), peak: 0.023, a: 0.001,
    });
  }
  // the shards: they fall and land, bunched early and sparser later, each quieter than the last
  const n = Math.round(p.shards);
  for (let k = 0; k < n; k++) {
    const u = (k + T.rand(0.05, 0.95)) / n;
    T.bell(room, t + 0.1 + p.fall * Math.pow(u, 1.6), {
      f: T.rand(2200, 7500) * p.pitch, partials: [[1, 1, 1], [2.32, 0.5, 0.5]], dur: T.rand(0.08, 0.16), peak: 0.027 * (1 - 0.65 * u), a: 0.001,
    });
  }
  T.crackle(room, t + 0.1, { dur: p.fall, rate: 70, f: 7000, to: 5000, q: 1, spread: 0.5, len: 0.004, peak: 0.05, vary: 0.8 });
}

function (T, out, t, p) {
  const L = p.length;
  const sag = 1 - 0.55 * p.tear;
  const lp = T.filter(out, t, { type: 'lowpass', f: 2400, q: 0.7 });
  // the tone sags with a wow, then a second voice climbs from the bottom of the sag back to pitch
  T.osc(lp, t, { type: 'sawtooth', f: p.tone, to: p.tone * sag, glide: L * 0.5, dur: L * 0.75, peak: 0.04, a: 0.02, s: 1, d: 0.02, r: L * 0.2, vib: { rate: 6.5, depth: 30 + 110 * p.tear } });
  T.osc(lp, t + L * 0.55, { type: 'sawtooth', f: p.tone * sag, to: p.tone, glide: L * 0.35, dur: L * 0.5, peak: 0.04, a: L * 0.12, s: 1, d: 0.02, r: L * 0.2, vib: { rate: 5, depth: 25 } });
  T.osc(lp, t, { f: p.tone * 0.5, to: p.tone * 0.5 * sag, glide: L * 0.5, dur: L * 0.75, peak: 0.025, a: 0.02, s: 1, d: 0.02, r: L * 0.2 });
  // the tear lines: a narrow band of noise falls from the top of the spectrum to the bottom
  const bands = 2 + Math.round(2 * p.tear);
  for (let k = 0; k < bands; k++) {
    T.noise(out, t + L * (0.04 + 0.2 * k), { filter: 'bandpass', f: 7000 - 700 * k, to: 600, q: 2.5, dur: L * 0.4, peak: 0.07 + 0.08 * p.tear, a: L * 0.04 });
  }
  // snow and speckle
  T.noise(out, t, { filter: 'highpass', f: 3000, q: 0.7, dur: L + 0.08, peak: 0.004 + 0.02 * p.snow, a: 0.03, s: 1, d: 0.02, r: 0.1 });
  T.crackle(out, t, { dur: L, rate: 25 + 90 * p.snow, f: 4500, to: 2500, spread: 0.7, q: 1, len: 0.004, peak: 0.01 + 0.04 * p.snow });
  // the heads lock: a small tick as the tone settles
  T.tick(out, t + L * 0.85, { f: 2200, q: 1, dur: 0.015, peak: 0.04 });
}

function (T, out, t, p) {
  const L = p.length;
  const n = Math.round(p.turns);
  const up = p.up >= 0.5;
  const f0 = p.pitch;
  const f1 = p.pitch * 8;
  // pitch of the spiral a fraction u of the way through; the pull runs it backwards
  const pitchAt = (u) => f0 * Math.pow(f1 / f0, up ? u : 1 - u);
  // turn boundaries: the first turn is the longest, each one after it tighter
  const edge = (k) => 1 - Math.pow(1 - k / n, 1.5);
  const q = 2.5 + 7 * p.swirl;
  const lift = Math.sqrt(q / 4);
  // the swell shared by every turn: it builds toward the end of the spiral
  const swell = T.bus(out, t, { a: L * 0.55, s: 1, d: 0.01, r: 0.2, dur: L + 0.22 });
  for (let k = 0; k < n; k++) {
    const at = t + L * edge(k);
    const seg = L * (edge(k + 1) - edge(k));
    const side = k % 2 === 0 ? -1 : 1;
    const ring = T.pan(swell, at, { x: 0.8 * side, to: -0.8 * side, dur: seg * 1.25 });
    T.noise(ring, at, {
      filter: 'bandpass', f: pitchAt(edge(k)), to: pitchAt(Math.min(1, edge(k + 1) + 0.12)), q,
      dur: Math.min(seg * 2.2, L + 0.22 - L * edge(k)), a: seg * 0.5, peak: 0.3 * lift,
    });
  }
  // the whistle riding above the ring
  T.osc(swell, t, {
    type: 'triangle', f: up ? f0 * 2 : f1, to: up ? f1 * 1.2 : f0 * 2, dur: L, a: L * 0.6, peak: 0.035,
    vib: { rate: 5 + 2 * n, depth: 60 },
  });
  // the accent at the end
  if (up) {
    T.bell(out, t + L * 0.98, { f: 1760, partials: [[1, 1, 1], [2.7, 0.3, 0.4]], dur: 0.2, peak: 0.03, a: 0.003 });
  } else {
    T.osc(out, t + L * 0.98, { f: 190, to: 70, dur: 0.18, peak: 0.07, a: 0.008 });
  }
}

function (T, out, t, p) {
  const echo = T.delay(out, t, { time: 0.11, fb: 0.25, mix: 0.2, tone: 2500 });
  const lp = T.filter(echo, t, { type: 'lowpass', f: p.tone, q: 0.7 });
  const hi = p.pitch * Math.pow(2, Math.round(p.interval) / 12);
  const n = Math.round(p.cycles) * 2;
  for (let k = 0; k < n; k++) {
    const up = k % 2 === 0;
    const at = t + k * p.rate;
    const a = up ? p.pitch : hi;
    const b = up ? hi : p.pitch;
    // each swoop runs a hair past its slot so neighbours overlap and the line stays legato
    T.osc(lp, at, { type: 'triangle', f: a, to: b, glide: p.rate, dur: p.rate + 0.03, peak: 0.075, a: 0.03, s: 0.85, d: 0.04, r: 0.04 });
    T.osc(lp, at, { type: 'sawtooth', f: a, to: b, glide: p.rate, dur: p.rate + 0.03, peak: 0.02, a: 0.03, s: 0.85, d: 0.04, r: 0.04 });
  }
}

function (T, out, t, p) {
  const len = p.length;
  // a 40 Hz highpass keeps the falling low end from leaving a DC offset (the sweeps end mid-cycle)
  const body = T.filter(out, t, { type: 'highpass', f: 40, q: 0.7 });
  // drive's ref caps the snarl near 0.085 however hard it is pushed
  const dr = T.drive(body, t, { amount: 0.25 + 0.65 * p.grit, ref: 0.085 });
  T.osc(dr, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 0.1, dur: len, peak: 0.07, a: 0.002, glide: len * 0.8 });
  T.osc(dr, t, { type: 'square', f: p.pitch * 1.01, to: p.pitch * 0.1, dur: len, peak: 0.05, a: 0.002, glide: len * 0.8 });
  T.fm(body, t, { f: p.pitch * 2, to: p.pitch * 0.3, ratio: 1.41, index: 2, index1: 0.2, dur: len * 0.6, peak: 0.02, a: 0.002 });
  T.noise(out, t, { filter: 'highpass', f: 5000, to: 1500, q: 0.8, dur: 0.05, peak: 0.05, a: 0.001 });
  T.osc(body, t, { f: 180, to: 45, dur: 0.22, peak: 0.015 + 0.06 * p.weight, a: 0.002 });
}

function (T, out, t, p) {
  const cr = T.crush(out, t, { bits: 8 - 4 * p.grit, ref: 0.1 });
  const n = Math.round(p.ticks);
  const slot = p.length / n;
  for (let k = 0; k < n; k++) {
    const at = t + (k + T.rand(0, 0.8)) * slot;
    const f = p.pitch * Math.pow(2, T.rand(-1, 1) * p.spread * 1.5);
    const type = T.rand() < 0.5 ? 'square' : 'sawtooth';
    T.osc(cr, at, { type, f, to: f * 1.15, dur: 0.022, peak: 0.04, a: 0.002 });
  }
  T.noise(out, t, { filter: 'highpass', f: 5000, q: 0.8, dur: p.length, peak: 0.012, a: 0.05 });
}

function (T, out, t, p) {
  const n = Math.round(p.blasts), L = p.length, gap = 0.4;
  const span = n * L + (n - 1) * gap, rattle = p.pitch / 4;
  const room = T.reverb(out, t, { time: 1.6, mix: 0.08 + 0.32 * p.space, tone: 0.4, pre: 0.015 });
  const hp = T.filter(room, t, { type: 'highpass', f: 90, q: 0.7 });
  // a gentle slow swell across the whole alarm: level and brightness breathe together
  const swellGain = T.gain(hp, 1);
  T.lfo(swellGain, t, { param: 'gain', rate: 0.48, depth: 0.11, dur: span, a: 0.3 });
  const lp = T.filter(swellGain, t, { type: 'lowpass', f: 3000, q: 0.6 });
  T.lfo(lp, t, { param: 'frequency', rate: 0.48, depth: 750, dur: span, a: 0.3 });
  const presence = T.filter(lp, t, { type: 'peaking', f: 3300, q: 1.2, db: 4 });
  // ref sets the horn's loudness: the drive never passes more than about this, whatever the rasp
  const grit = T.drive(presence, t, { amount: 0.3 + 0.5 * p.rasp, ref: 0.05 });
  // the rasp path, rattled at the same rate as the tone for the whole alarm
  const raspGain = T.gain(grit, 1);
  T.lfo(raspGain, t, { param: 'gain', rate: rattle, depth: 0.5 + 0.4 * p.rasp, dur: span });
  const buzz = { rate: rattle, depth: 0.12 + 0.45 * p.rasp };
  for (let k = 0; k < n; k++) {
    const at = t + k * (L + gap);
    const env = { dur: L, a: 0.03, d: 0.06, s: 0.95, r: 0.08 };
    // the spin-up: each blast starts 3% flat and catches its note within 50 ms
    const spin = { f: p.pitch * 0.97, to: p.pitch, glide: 0.05 };
    // a strong sine on the note (the fundamental dominates a real horn), a saw and a square for
    // the harmonics, all rattled at f/4; the saw and square sit 2 cents apart so their slow beat
    // joins the swell instead of pulsing on its own
    T.osc(grit, at, { ...env, ...spin, type: 'sine', peak: 0.07, trem: buzz });
    T.osc(grit, at, { ...env, ...spin, type: 'sawtooth', detune: -1, peak: 0.03, trem: buzz });
    T.osc(grit, at, { ...env, ...spin, type: 'square', detune: 1, peak: 0.014, trem: buzz });
    T.noise(raspGain, at, { ...env, filter: 'bandpass', f: 2400, q: 0.45, peak: 0.012 + 0.05 * p.rasp });
  }
}

function (T, out, t, p) {
  const cr = T.crush(out, t, { bits: 9 - 5 * p.glitch, ref: 0.1 });
  const n = Math.round(p.flickers);
  const slot = p.length / n;
  for (let k = 0; k < n; k++) {
    const start = t + k * slot;
    const last = k === n - 1;
    const on = last ? 0.3 : slot * T.rand(0.35, 0.8);
    // the pitch wanders further as the glitch amount rises
    const f = p.pitch * (1 + p.glitch * T.rand(-0.35, 0.35));
    T.fm(cr, start, { f, ratio: 2.76, index: 1.2, index1: 0.4, dur: on, peak: 0.08, a: 0.004, s: 0.8, d: 0.01, r: last ? 0.2 : 0.01 });
    if (!last) {
      T.noise(out, start + on, { filter: 'highpass', f: 3500, q: 0.8, dur: Math.max(0.015, slot - on), peak: 0.012 + 0.05 * p.glitch, a: 0.002 });
    }
  }
}

function (T, out, t, p) {
  const lp = T.filter(out, t, { type: 'lowpass', f: 7000, q: 0.7 });
  const n = Math.round(p.shots);
  for (let k = 0; k < n; k++) {
    const at = t + k * p.rate;
    // each shot in a burst is a touch lower than the last
    const f = p.pitch * (1 - 0.04 * k);
    const to = f * (1 - p.drop);
    T.osc(lp, at, { type: 'square', f, to, dur: 0.17, peak: 0.012 + 0.045 * p.edge, a: 0.002, glide: 0.15 });
    T.osc(lp, at, { f, to, dur: 0.17, peak: 0.06, a: 0.002, glide: 0.15 });
    T.fm(lp, at, { f: f * 0.5, to: to * 0.5, ratio: 3.5, index: 2.5, index1: 0.3, dur: 0.12, peak: 0.02, a: 0.002 });
    T.noise(out, at, { filter: 'highpass', f: 6000, q: 0.8, dur: 0.015, peak: 0.04, a: 0.001 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const lp = T.filter(out, t, { type: 'lowpass', f: 1500 + 4500 * p.bright, to: 150, dur: L, q: 2 });
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch * 10, to: p.pitch * 0.8, dur: L, peak: 0.07, a: 0.02, glide: L, s: 0.6, d: 0.15, r: L * 0.4 });
  T.osc(lp, t, { type: 'square', f: p.pitch * 20, to: p.pitch * 1.6, dur: L, peak: 0.02, a: 0.02, glide: L, s: 0.6, d: 0.15, r: L * 0.4 });
  const n = Math.round(p.ticks);
  for (let k = 0; k < n; k++) {
    const u = k / n;
    // u^1.8 spreads the ticks further apart toward the end, and each sits lower than the last
    T.osc(out, t + L * Math.pow(u, 1.8), { type: 'square', f: p.pitch * 6 * Math.pow(2, -u * 1.5), dur: 0.03, peak: 0.035, a: 0.002 });
  }
  // the last of it: a soft thud and a dull click
  T.osc(out, t + L, { f: 90, to: 40, dur: 0.14, peak: 0.09, a: 0.003 });
  T.noise(out, t + L, { filter: 'lowpass', f: 500, q: 0.8, dur: 0.05, peak: 0.12, a: 0.002 });
}

function (T, out, t, p) {
  const L = p.length;
  const lp = T.filter(out, t, { type: 'lowpass', f: 300, to: 1500 + 4500 * p.bright, dur: L, q: 2 });
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 8, dur: L + 0.25, peak: 0.07, a: L * 0.9, glide: L });
  T.osc(lp, t, { type: 'square', f: p.pitch * 2, to: p.pitch * 16, dur: L + 0.25, peak: 0.02, a: L * 0.9, glide: L });
  const n = Math.round(p.ticks);
  for (let k = 0; k < n; k++) {
    const u = k / n;
    // 1 - (1 - u)^1.8 packs the ticks closer together toward the end
    T.osc(out, t + L * (1 - Math.pow(1 - u, 1.8)), { type: 'square', f: p.pitch * 4 * Math.pow(2, u * 1.5), dur: 0.03, peak: 0.035, a: 0.002 });
  }
  // the lock-on: the whine ends at pitch * 8, so the chime is that note and its fifth
  const soft = T.filter(out, t, { type: 'lowpass', f: 4000, q: 0.7 });
  T.osc(soft, t + L, { type: 'square', f: p.pitch * 8, dur: 0.22, peak: 0.04, a: 0.003, s: 0.5, d: 0.04, r: 0.08 });
  T.osc(soft, t + L, { type: 'square', f: p.pitch * 12, dur: 0.22, peak: 0.03, a: 0.003, s: 0.5, d: 0.04, r: 0.08 });
}

function (T, out, t, p) {
  const n = Math.round(p.chirps);
  const ratios = [2, 3, 1.5, 2.5];
  let f = p.pitch;
  let at = t;
  for (let k = 0; k < n; k++) {
    const len = p.speed * T.rand(0.8, 1.3);
    const up = T.rand() < p.mood;
    const to = Math.min(3200, f * (up ? T.rand(1.3, 2.2) : T.rand(0.5, 0.8)));
    T.fm(out, at, {
      f, to, ratio: ratios[Math.floor(T.rand() * ratios.length)], index: 1.5, index1: 0.5,
      dur: len, peak: 0.09, a: 0.004, s: 0.7, d: 0.02, r: 0.02,
    });
    // the next chirp starts near where this one ended, kept inside a comfortable band
    f = Math.min(p.pitch * 2, Math.max(p.pitch * 0.55, to * T.rand(0.8, 1.25)));
    at += len + 0.012;
  }
}

function (T, out, t, p) {
  const n = Math.round(p.sweeps);
  const L = p.length;
  for (let k = 0; k < n; k++) {
    const up = k % 2 === 0;
    const from = up ? p.pitch : p.pitch * 4;
    const to = up ? p.pitch * 4 : p.pitch;
    const at = t + k * L;
    const hold = { a: 0.04, s: 0.9, d: 0.05, r: 0.05, dur: L + 0.03 };
    T.osc(out, at, { type: 'triangle', f: from, to, glide: L, peak: 0.07, a: hold.a, s: hold.s, d: hold.d, r: hold.r, dur: hold.dur, trem: { rate: 14, depth: 0.7 * p.wobble } });
    T.osc(out, at, { f: from * 2, to: to * 2, glide: L, peak: 0.025, a: hold.a, s: hold.s, d: hold.d, r: hold.r, dur: hold.dur });
    T.noise(out, at, { filter: 'bandpass', f: from * 1.5, to: to * 1.5, q: 14, glide: L, peak: 0.4, a: hold.a, s: hold.s, d: hold.d, r: hold.r, dur: hold.dur });
  }
  const end = t + n * L;
  T.osc(out, end, { type: 'square', f: p.pitch * 4, dur: 0.05, peak: 0.045, a: 0.002 });
  T.osc(out, end + 0.08, { type: 'square', f: p.pitch * 6, dur: 0.07, peak: 0.045, a: 0.002 });
}

function (T, out, t, p) {
  const L = p.length;
  const lp = T.filter(out, t, { type: 'lowpass', f: 150, to: 500 + 2500 * p.bright, dur: 0.35, q: 3 });
  const pulse = { rate: p.pulse, depth: 0.55 };
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch, dur: L, peak: 0.04, a: 0.25, s: 0.85, d: 0.12, r: 0.3, trem: pulse });
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch * 1.006, dur: L, peak: 0.04, a: 0.25, s: 0.85, d: 0.12, r: 0.3, trem: pulse });
  T.osc(lp, t, { type: 'square', f: p.pitch * 0.5, dur: L, peak: 0.03, a: 0.25, s: 0.85, d: 0.12, r: 0.3, trem: pulse });
  // a thin whine on top that brightens with the filter
  T.osc(out, t, { f: p.pitch * 12, dur: L, peak: 0.004 + 0.012 * p.bright, a: 0.3, s: 0.8, d: 0.1, r: 0.3, trem: pulse });
}

function (T, out, t, p) {
  const cr = T.crush(out, t, { bits: 8 - 5 * p.grit, ref: 0.1 });
  const scale = [1, 1.2599, 1.4983, 1.7818, 2, 1.3348];
  const n = Math.round(p.count);
  for (let k = 0; k < n; k++) {
    // the first beep is always the base pitch, so the run always starts from the same place
    const r = k === 0 ? 1 : scale[Math.floor(T.rand() * scale.length)];
    T.osc(cr, t + k * p.speed, { type: 'square', f: p.pitch * r, dur: 0.04, peak: 0.09, a: 0.002 });
  }
}

function (T, out, t, p) {
  const C = p.charge;
  const lp = T.filter(out, t, { type: 'lowpass', f: 250, to: 7000, dur: C, q: 3 });
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 8, dur: C + 0.05, peak: 0.04, a: C * 0.9, glide: C });
  T.osc(lp, t, { type: 'sawtooth', f: p.pitch, to: p.pitch * 8, detune: 14, dur: C + 0.05, peak: 0.03, a: C * 0.9, glide: C });
  T.fm(out, t, { f: p.pitch * 6, to: p.pitch * 40, ratio: 2, index: 0.8, dur: C + 0.05, peak: 0.02, a: C * 0.9, glide: C });
  // the jump
  const j = t + C;
  T.noise(out, j, { filter: 'bandpass', f: 7000, to: 300, q: 1.2, dur: p.tail, peak: 0.12, a: 0.01 });
  T.osc(out, j, { f: p.pitch * 40, to: p.pitch * 3, dur: 0.25, peak: 0.04, a: 0.004 });
  T.osc(out, j, { f: 150, to: 30, dur: 0.5, peak: 0.02 + 0.09 * p.boom, a: 0.004 });
}

function (T, out, t, p) {
  const r = Math.pow(2, p.key / 12);
  const v = [['oo', 'ah'], ['mm', 'oo'], ['ah', 'ah'], ['oh', 'oh']][Math.round(p.vowel)];
  const room = T.reverb(out, t, { time: 3.2, mix: p.space, tone: 0.3, pre: 0.03 });
  T.choir(room, t, {
    notes: [T.note('D3') * r, T.note('F3') * r, T.note('A3') * r, T.note('D4') * r],
    voices: Math.round(p.singers), vowel: v[0], to: v[1], dur: 4.2, a: 1.4, r: 1.6, spread: 16,
    breath: 0.1, peak: 0.13, room: { time: 0.6, mix: 0.2 },
  });
}

function (T, out, t, p) {
  const f = T.note('D2') * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 2.2, mix: 0.3, tone: 0.35 });
  const trem = p.shiver > 0.5 ? 13 : 0;
  const common = { players: Math.round(p.players), pressure: p.grit, bright: 0.3, vib: trem ? 4 : 9, trem };
  T.bow(room, t, Object.assign({ f, dur: 4.2, a: 1.4, r: 1.4, peak: 0.058 }, common));
  T.bow(room, t + 0.9, Object.assign({ f: f * 1.5, dur: 3.3, a: 1.2, r: 1.3, peak: 0.04 }, common));
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 2.4, mix: p.space, tone: 0.3 });
  T.membrane(room, t, { kind: 'taiko', f: p.pitch, dur: 1.5, peak: 0.18, stick: p.mallet, boom: 0.9 });
  T.membrane(room, t + 0.012, { kind: 'timpani', f: p.pitch * 0.667, dur: 1.1, peak: 0.072, stick: 0.2, boom: 0 });
}

function (T, out, t, p) {
  const room = T.reverb(out, t, { time: 1.4, mix: 0.25, tone: 0.3 });
  const rate = (p.rise > 0.5 ? 1 : -1) * p.speed;
  T.shepard(room, t, { rate, center: 300, width: 1.3, edge: p.edge, dur: p.length - 0.4, a: 0.8, r: 0.9, peak: 0.085 });
  T.osc(room, t, { f: 55, dur: p.length - 0.4, peak: 0.016, a: 1, s: 1, d: 0.02, r: 1 });
}

function (T, out, t, p) {
  const r = Math.pow(2, p.key / 12);
  const stops = ['flute', 'principal', 'full'][Math.round(p.stops)];
  const room = T.reverb(out, t, { time: 3, mix: p.space, tone: 0.35, pre: 0.02 });
  const shape = { dur: 2.9, a: 0.35, r: 0.6, stops, celeste: 5, chiff: 0.5, trem: 0.15 * p.tremulant, tremRate: 5.5 };
  T.organ(room, t, Object.assign({ notes: [T.note('D4') * r, T.note('F4') * r, T.note('A4') * r], peak: 0.06 }, shape));
  T.organ(room, t, Object.assign({ notes: [T.note('D2') * r], peak: 0.05 }, shape, { stops: 'flute' }));
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.8, L * 0.3);
  const f0 = p.pitch;
  const d = p.drift;
  // voices stop 1 s early so the room has rung out by dur
  const room = T.reverb(out, t, { time: 1.4, mix: 0.45, tone: 0.6 });
  const body = L - 1;
  // semitones above the root, the level of each note, and how much glow it needs to sound
  const notes = [
    [0, 1, 0, 'triangle'], [7, 0.8, 0, 'triangle'], [14, 0.6, 0, 'sine'],
    [18, 0.4, 0.35, 'sine'], [23, 0.35, 0.5, 'sine'], [26, 0.3, 0.7, 'sine'],
  ];
  notes.forEach((nt, k) => {
    const lift = nt[2] > 0 ? Math.max(0, Math.min(1, (p.glow - nt[2] * 0.6) / 0.4)) : 1;
    if (lift <= 0) return;
    const f = f0 * Math.pow(2, nt[0] / 12);
    const rate = 0.08 + 0.045 * k;
    const beat = 0.3 + 0.08 * k;
    [-1, 1].forEach((s) => {
      const x = s * (0.55 + 0.4 * ((k % 3) / 2));
      const place = T.pan(room, t, { x, to: x - s * 0.8 * d, dur: body });
      T.osc(place, t + 0.2 * k, {
        type: nt[3], f: f + (s * beat) / 2, dur: body - 0.2 * k, peak: 0.015 * nt[1] * lift,
        a: fade, s: 1, d: 0.02, r: fade, trem: { rate, depth: 0.15 + 0.6 * d },
      });
    });
  });
  // the glitter: slow trembling high sines that lie on chord tones
  [4, 6, 9].forEach((m, k) => {
    const place = T.pan(room, t, { x: k === 1 ? 0.6 : -0.6, to: k === 1 ? -0.6 : 0.6, dur: body });
    T.osc(place, t, {
      f: f0 * m, dur: body, peak: 0.008 * p.glow, a: fade, s: 1, d: 0.02, r: fade * 0.8,
      trem: { rate: 0.17 + 0.09 * k, depth: 0.9 }, vib: { rate: 0.4, depth: 7 },
    });
  });
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const cave = T.reverb(out, t, { time: 1 + 1 * p.cave, mix: 0.35 + 0.45 * p.cave, tone: 0.4, pre: 0.02 });
  T.noise(out, t, {
    filter: 'bandpass', f: 200, q: 1, dur: L, peak: 0.07, a: fade, s: 1, d: 0.02, r: fade,
  });
  const n = Math.round(p.drips);
  const span = Math.max(0.5, L - 0.3 - 1.7);
  for (let k = 0; k < n; k++) {
    const at = 0.3 + ((k + T.rand(0.1, 0.9)) * span) / n;
    const f = T.rand(900, 1500) * p.pitch;
    const pk = 0.055 * T.rand(0.6, 1);
    T.osc(cave, t + at, { f, to: f * T.rand(1.6, 2.2), glide: 0.04, dur: 0.16, peak: pk, a: 0.003 });
    if (T.rand() < 0.3) {
      T.osc(cave, t + at + 0.13, { f: f * 1.1, to: f * 1.9, glide: 0.04, dur: 0.12, peak: pk * 0.4, a: 0.003 });
    }
  }
}

function (T, out, t, p) {
  const L = p.length;
  const far = p.distance;
  const dark = 1 - 0.55 * far;
  // a lower cutoff passes less noise: lift the peak so a far storm is not just quieter
  const lift = 1 / Math.sqrt(dark);
  T.noise(out, t, {
    filter: 'lowpass', f: 260 * dark, to: 55, q: 0.8, dur: L, peak: 0.2 * lift, a: 0.45, curve: 'lin',
  });
  const n = Math.round(p.rolls);
  for (let k = 1; k <= n; k++) {
    const at = Math.min(L - 1.2, L * 0.14 * k + T.rand(0.2, 0.7));
    T.noise(out, t + at, {
      filter: 'lowpass', f: T.rand(190, 260) * dark, to: 50, q: 0.8,
      dur: Math.min(2.6, L - at), peak: 0.16 * lift * (1 - 0.22 * k), a: 0.5,
    });
  }
  // the crack: a muffled burst and a handful of ticks, fading with distance
  const crack = 1 - far;
  T.noise(out, t, { filter: 'bandpass', f: 900, to: 250, q: 0.9, dur: 0.55, peak: 0.12 * crack, a: 0.004 });
  for (let k = 0; k < 5; k++) {
    T.noise(out, t + T.rand(0.02, 0.4), {
      filter: 'bandpass', f: T.rand(500, 1400), q: 1.5, dur: T.rand(0.03, 0.07), peak: 0.1 * crack * T.rand(0.4, 1), a: 0.003,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1, L * 0.25);
  const win = (x) => Math.min(1, x / 0.6, (L - x) / 0.8);
  const bright = 0.6 + 1.4 * p.tone;
  // the roar, and a few flicker swells riding on it
  T.noise(out, t, {
    filter: 'bandpass', f: 300, q: 0.6, dur: L, peak: 0.01 + 0.07 * p.roar, a: fade, s: 1, d: 0.02, r: fade,
  });
  const fl = Math.max(2, Math.round(L / 1.6));
  for (let k = 0; k < fl; k++) {
    const at = T.rand(0, L - 1.2);
    T.noise(out, t + at, {
      filter: 'lowpass', f: T.rand(500, 900), to: 250, q: 0.7,
      dur: Math.min(T.rand(1.2, 2), L - at), peak: 0.07 * p.roar * T.rand(0.5, 1), a: 0.5,
    });
  }
  // crackle
  const n = Math.round(L * (3 + 13 * p.crackle));
  for (let k = 0; k < n; k++) {
    const at = T.rand(0.1, L - 0.15);
    const pk = 0.03 * Math.pow(6, T.rand()) * win(at);
    const f = T.rand(1400, 5500) * bright;
    T.noise(out, t + at, { filter: 'bandpass', f, to: f * 0.6, q: T.rand(2, 5), dur: T.rand(0.012, 0.045), peak: pk, a: 0.002 });
    if (T.rand() < 0.25) {
      T.noise(out, t + at + T.rand(0.02, 0.06), { filter: 'bandpass', f: f * 0.8, q: 3, dur: 0.025, peak: pk * 0.5, a: 0.002 });
    }
  }
  // logs settling
  const m = Math.round(L * (0.1 + 0.3 * p.crackle));
  for (let k = 0; k < m; k++) {
    const at = T.rand(0.3, L - 0.4);
    T.osc(out, t + at, { f: T.rand(130, 190), to: 70, dur: 0.08, peak: 0.05 * win(at), a: 0.003 });
    T.noise(out, t + at, { filter: 'lowpass', f: 500, q: 0.8, dur: 0.06, peak: 0.12 * win(at), a: 0.003 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1, L * 0.25);
  const room = T.reverb(out, t, { time: 1.1, mix: 0.22, tone: 0.8 });
  // one chirp: a sine gliding f0 -> f1 with a rounded envelope
  const tw = (at, f0, f1, d, pk) => T.osc(room, t + at, {
    f: f0 * p.pitch, to: f1 * p.pitch, dur: d, peak: pk, a: Math.min(0.012, d * 0.3),
    s: 0.8, d: 0.015, r: d * 0.45, glideCurve: 'lin',
  });
  // the breeze in the leaves
  T.noise(out, t, {
    filter: 'bandpass', f: 700, q: 0.5, dur: L, peak: 0.03, a: fade, s: 1, d: 0.02, r: fade,
  });
  // phrases stop 1.6 s before the end so the room's tail is gone by the last sample
  const n = Math.max(1, Math.round(L * (0.5 + 1.1 * p.activity)));
  for (let k = 0; k < n; k++) {
    const at = T.rand(0.15, L - 1.6);
    const kind = T.rand();
    const base = T.rand(2600, 4200);
    const far = T.rand() < 0.35;
    const lv = (far ? 0.018 : 0.04) * T.rand(0.8, 1);
    if (kind < 0.1 + 0.55 * p.trill) {
      const m = Math.round(T.rand(6, 12));
      for (let j = 0; j < m; j++) {
        const up = j % 2 === 0;
        tw(at + j * 0.055, base * (up ? 1 : 1.12), base * (up ? 1.12 : 0.97), 0.04, lv * 0.8);
      }
    } else if (kind < 0.7) {
      const m = Math.round(T.rand(2, 3));
      for (let j = 0; j < m; j++) tw(at + j * 0.14, base * 0.9, base * 1.25, 0.09, lv);
    } else {
      tw(at, base * 0.75, base * 1.05, 0.2, lv);
      tw(at + 0.2, base * 1.05, base * 0.7, 0.22, lv * 0.9);
    }
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const win = (x) => Math.min(1, x / 0.6, (L - x) / 0.8);
  const f = p.pitch;
  // the hum: harmonic sines, the higher ones wider apart and quieter
  [[1, 1, 0.1], [2, 0.5, 0.35], [3, 0.35, 0.5], [4, 0.22, 0.65], [6, 0.12, 0.8]].forEach((h, k) => {
    [-1, 1].forEach((s) => {
      T.osc(T.pan(out, t, { x: s * h[2] }), t, {
        f: f * h[0] + s * (0.12 + 0.07 * k), dur: L, peak: 0.015 * h[1], a: fade, s: 1, d: 0.02, r: fade,
        trem: { rate: 0.2 + 0.06 * k, depth: 0.2 },
      });
    });
  });
  // the sheen: a very narrow band of noise, swept in opposite directions in the two ears
  [-1, 1].forEach((s) => {
    T.noise(T.pan(out, t, { x: s * 0.85 }), t, {
      filter: 'bandpass', f: s < 0 ? 2300 : 4600, to: s < 0 ? 4600 : 2300, q: 14, dur: L, peak: 0.2 * p.sheen,
      a: fade, s: 1, d: 0.02, r: fade,
    });
  });
  // traffic: tiny ticks with a pitched blip, each one crossing from one side to the other
  const n = Math.round(L * 7 * p.traffic);
  for (let k = 0; k < n; k++) {
    const at = T.rand(0.3, L - 0.5);
    const dir = T.rand() < 0.5 ? 1 : -1;
    const w = win(at);
    const lane = T.pan(out, t + at, { x: -0.8 * dir, to: 0.8 * dir, dur: 0.3 });
    T.tick(lane, t + at, {
      f: T.rand(5000, 9000), q: 5, dur: 0.012, peak: 0.006 * w, blip: T.rand(1400, 3200), blipPeak: 0.003 * w, blipDur: 0.045, jitter: 0.5,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const win = (x) => Math.min(1, x / 0.7, (L - x) / 1.3);
  // the warm breath of heat, one independent noise per side, each swelling at its own slow pace
  [-0.8, 0.8].forEach((x, k) => {
    const lp = T.filter(T.pan(out, t, { x }), t, { type: 'lowpass', f: 230, q: 0.8, dur: 0.1 });
    T.lfo(lp, t, { rate: 0.1 + 0.06 * k, depth: 60, dur: L, a: fade });
    T.noise(lp, t, {
      filter: 'none', dur: L, peak: 0.025 + 0.18 * p.heat, a: fade, s: 1, d: 0.02, r: fade,
    });
  });
  // the simmer: tiny low bursts, as one source
  const simmer = T.bus(T.pan(out, t, { x: 0.3 }), t, { dur: L, a: fade, s: 1, d: 0.02, r: fade });
  T.crackle(simmer, t, {
    dur: L, rate: 11, f: 360, spread: 0.7, q: 3, len: 0.035, peak: 0.06 * (0.3 + 0.7 * p.heat), vary: 0.8,
  });
  // big bubbles: a sine rising as it swells, a quiet octave for the wet edge, then a soft pop
  const n = Math.round(p.bubbles);
  const span = Math.max(0.5, L - 0.4 - 1.3);
  for (let k = 0; k < n; k++) {
    const at = 0.4 + ((k + T.rand(0.1, 0.9)) * span) / n;
    const f = T.rand(115, 270) * p.depth;
    const len = T.rand(0.28, 0.5);
    const w = win(at);
    const side = T.pan(out, t + at, { x: T.rand(-0.75, 0.75) });
    T.osc(side, t + at, { f, to: f * T.rand(1.6, 2.2), dur: len, peak: 0.031 * T.rand(0.6, 1) * w, a: 0.06, lp: 700 });
    T.osc(side, t + at, { f: f * 2, to: f * 3.4, dur: len * 0.8, peak: 0.009 * w, a: 0.08, lp: 900 });
    T.noise(side, t + at + len * 0.8, { filter: 'lowpass', f: 340, q: 0.8, dur: 0.09, peak: 0.045 * w, a: 0.012 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const win = (x) => Math.min(1, x / 0.8, (L - x) / 1);
  // the night air: a low breath and a faint rustle, one independent noise per ear
  [-0.9, 0.9].forEach((x) => {
    const ear = T.pan(out, t, { x });
    T.noise(ear, t, { filter: 'lowpass', f: 320, q: 0.7, dur: L, peak: 0.07, a: fade, s: 1, d: 0.02, r: fade });
    T.noise(ear, t, { filter: 'bandpass', f: 1800, q: 0.5, dur: L, peak: 0.004, a: fade, s: 1, d: 0.02, r: fade });
  });
  // chirps ring a little in a small room, so the last must stop before the end
  const room = T.reverb(out, t, { time: 0.5, mix: 0.2, tone: 0.7 });
  const n = Math.round(p.crickets);
  for (let c = 0; c < n; c++) {
    const x = n === 1 ? T.rand(-0.5, 0.5) : -0.85 + (1.7 * c) / (n - 1) + T.rand(-0.1, 0.1);
    const f = T.rand(3700, 4800) * p.pitch;
    const beat = T.rand(0.36, 0.52) / p.pace;
    const lane = T.pan(room, t, { x });
    // runs of chirps at a steady beat, then a rest
    let at = T.rand(0.1, beat * 2);
    let runEnd = at + T.rand(1.4, 3);
    while (at < L - 0.4) {
      if (at > runEnd) {
        at += T.rand(0.5, 1.2);
        runEnd = at + T.rand(1.4, 3);
        continue;
      }
      const w = win(at) * T.rand(0.8, 1);
      for (let j = 0; j < 3; j++) {
        T.osc(lane, t + at + j * 0.034, {
          f, dur: 0.026, peak: 0.02 * w * (1 - 0.15 * j), a: 0.006, s: 1, d: 0.002, r: 0.008,
        });
      }
      at += beat;
    }
  }
}

function (T, out, t, p) {
  const L = p.length;
  const P = p.period;
  const fade = Math.min(1.2, L * 0.3);
  T.noise(out, t, {
    filter: 'lowpass', f: 130, q: 0.7, dur: L, peak: 0.18 * p.depth + 0.01, a: fade, s: 1, d: 0.02, r: fade,
  });
  const n = Math.max(1, Math.ceil((L - 0.4) / P));
  for (let k = 0; k < n; k++) {
    const at = k === 0 ? 0 : k * P + T.rand(-0.15, 0.15) * P;
    if (L - at < 0.8) continue;
    const len = Math.min(P * 1.3, L - at);
    const a = Math.min(P * 0.38, len * 0.5);
    const big = T.rand(0.75, 1);
    T.noise(out, t + at, {
      filter: 'lowpass', f: 250, to: 1300, q: 0.6, glide: a, dur: len, peak: 0.075 * big, a,
    });
    T.noise(out, t + at + a * 0.8, {
      filter: 'bandpass', f: 4200, to: 2600, q: 0.6,
      dur: Math.min(P * 0.9, L - at - a * 0.8), peak: 0.05 * p.foam * big, a: a * 0.35,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1, L * 0.25);
  const win = (x) => Math.min(1, x / fade, (L - x) / fade);
  const hi = 2200 + 3300 * p.tone;
  // the wash
  T.noise(out, t, {
    filter: 'bandpass', f: hi, q: 0.5, dur: L, peak: 0.011 + 0.026 * p.rate, a: fade, s: 1, d: 0.02, r: fade,
  });
  // single drops, thinning out at both ends
  const n = Math.round(L * (4 + 22 * p.rate));
  for (let k = 0; k < n; k++) {
    const at = T.rand(0.05, L - 0.1);
    T.noise(out, t + at, {
      filter: 'bandpass', f: hi * T.rand(0.7, 1.6), q: 2.5, dur: T.rand(0.015, 0.04),
      peak: 0.07 * T.rand(0.3, 1) * win(at), a: 0.002,
    });
  }
  // puddle plinks
  const m = Math.round(L * (1 + 5 * p.rate));
  for (let k = 0; k < m; k++) {
    const at = T.rand(0.1, L - 0.2);
    const f = T.rand(700, 1900) * (0.8 + 0.5 * p.tone);
    T.osc(out, t + at, { f, to: f * 1.6, glide: 0.04, dur: 0.08, peak: 0.016 * T.rand(0.5, 1) * win(at), a: 0.003 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1, L * 0.25);
  const body = T.filter(out, t, { type: 'lowpass', f: 250 + 1400 * p.buzz, q: 0.7, dur: 0.1 });
  T.osc(body, t, {
    type: 'sawtooth', f: p.pitch, detune: -4, dur: L, peak: 0.022, a: fade, s: 1, d: 0.02, r: fade,
    trem: { rate: 0.35, depth: 0.25 },
  });
  T.osc(body, t, { type: 'sawtooth', f: p.pitch, detune: 5, dur: L, peak: 0.014, a: fade, s: 1, d: 0.02, r: fade });
  T.osc(out, t, { f: p.pitch * 2, dur: L, peak: 0.01, a: fade, s: 1, d: 0.02, r: fade });
  T.noise(out, t, {
    filter: 'lowpass', f: 900, q: 0.7, dur: L, peak: 0.07 * p.air, a: fade, s: 1, d: 0.02, r: fade,
  });
}

function (T, out, t, p) {
  const L = p.length;
  const end = L - 0.55;
  const fade = Math.min(1.1, L * 0.22);
  const rel = Math.min(1.4, L * 0.3);
  const bed = T.bus(out, t, { dur: end, a: fade, s: 1, d: 0.02, r: rel, tail: 0.04, fade: 0.3 });
  // a slow waver in the flow, as the stream is never quite steady
  const flow = T.gain(bed, 0.85);
  T.lfo(flow, t, { param: 'gain', rate: 0.37, depth: 0.15, dur: end, a: 0.5 });
  const dull = T.filter(flow, t, { type: 'lowpass', f: 4800 - 1600 * p.grain, q: 0.6, dur: 0.05 });
  const fc = 3000 - 1200 * p.grain;
  T.noise(dull, t, { filter: 'bandpass', f: fc, q: 0.5, hp: 600, dur: end, peak: 0.022 + 0.022 * p.flow, a: 0.01, s: 1, d: 0.01, r: 0.01 });
  T.noise(dull, t, { filter: 'bandpass', f: 800, q: 0.9, dur: end, peak: 0.012 + 0.016 * p.flow, a: 0.01, s: 1, d: 0.01, r: 0.01 });
  T.crackle(dull, t, {
    dur: end, rate: 150 + 450 * p.flow, f: fc * 1.3, spread: 0.6, q: 1, len: 0.003 + 0.004 * p.grain, peak: 0.04, vary: 0.8,
  });
  // the last stray grains, then the settle
  T.crackle(out, t + end - 0.6, { dur: 1, rate: 14, f: 2800, spread: 0.7, q: 1.2, len: 0.004, peak: 0.06, vary: 0.6 });
  T.noise(out, t + end + 0.03, { filter: 'lowpass', f: 900, to: 260, q: 0.7, dur: 0.5, peak: 0.13 * p.settle, a: 0.12 });
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const win = (x) => Math.min(1, x / 0.6, (L - x) / 0.8);
  // the blanket: one independent lowpassed noise per ear, each cutoff drifting at its own pace
  [-0.9, 0.9].forEach((x, k) => {
    const ear = T.pan(out, t, { x });
    const lp = T.filter(ear, t, { type: 'lowpass', f: 560, q: 0.7, dur: 0.1 });
    T.lfo(lp, t, { rate: 0.12 + 0.05 * k, depth: 170, dur: L, a: fade });
    T.noise(lp, t, {
      filter: 'none', dur: L, peak: 0.045 + 0.085 * p.hush * p.hush, a: fade, s: 1, d: 0.02, r: fade,
    });
    // the cold sizzle of the air, far under the blanket
    T.noise(ear, t, {
      filter: 'bandpass', f: 5200, q: 0.5, dur: L, peak: 0.001 + 0.006 * p.hush, a: fade, s: 1, d: 0.02, r: fade,
    });
  });
  // snow sliding off a branch: a padded thump and a puff of fine grains
  const n = Math.round(p.slides);
  const span = Math.max(0.5, L - 2);
  for (let k = 0; k < n; k++) {
    const at = 0.6 + ((k + T.rand(0.15, 0.85)) * span) / n;
    const side = T.pan(out, t + at, { x: T.rand(-0.8, 0.8) });
    const w = win(at);
    T.osc(side, t + at, { f: T.rand(95, 130), to: 55, dur: 0.3, peak: 0.01 * w, a: 0.04 });
    T.noise(side, t + at, { filter: 'lowpass', f: 380, to: 160, q: 0.7, dur: 0.4, peak: 0.055 * w, a: 0.07 });
    T.noise(side, t + at + 0.04, { filter: 'bandpass', f: 2600, q: 0.8, dur: 0.3, peak: 0.008 * w, a: 0.08 });
  }
  // ice glints: soft sines that ring out in a large cold room, so the last must land early
  const room = T.reverb(out, t, { time: 1.5, mix: 0.5, tone: 0.75 });
  const g = Math.round(p.glints);
  const gspan = Math.max(0.5, L - 2.6);
  for (let k = 0; k < g; k++) {
    const at = 0.5 + ((k + T.rand(0.1, 0.9)) * gspan) / g;
    const f = T.rand(2100, 4300);
    T.osc(T.pan(room, t + at, { x: T.rand(-0.85, 0.85) }), t + at, {
      f, dur: 0.5, peak: 0.016 * T.rand(0.5, 1) * win(at), a: 0.006,
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const f = p.pitch;
  const fade = Math.min(1.8, L * 0.3);
  const lp = T.filter(out, t, { type: 'lowpass', f: 160 + 500 * p.tone, to: 380 + 1500 * p.tone, dur: L * 0.8, q: 1.1 });
  T.osc(lp, t, { type: 'sawtooth', f, detune: -9, dur: L, peak: 0.014, a: fade, s: 1, d: 0.02, r: fade });
  T.osc(lp, t, { type: 'sawtooth', f, detune: 9, dur: L, peak: 0.014, a: fade, s: 1, d: 0.02, r: fade });
  T.osc(lp, t, { type: 'sawtooth', f: f * 1.5, detune: 4, dur: L, peak: 0.008, a: fade, s: 1, d: 0.02, r: fade });
  T.osc(out, t, { f: f * 2, dur: L, peak: 0.012, a: fade, s: 1, d: 0.02, r: fade, trem: { rate: 0.11, depth: 0.5 } });
  T.osc(out, t, { f: f * 3, dur: L, peak: 0.007, a: fade, s: 1, d: 0.02, r: fade });
  // the shimmer ends 1.2 s early so the room's tail is finished by dur
  const room = T.reverb(out, t, { time: 1.6, mix: 0.5, tone: 0.3 });
  const ratios = [8, 12, 16];
  for (let k = 0; k < 3; k++) {
    T.osc(room, t, {
      f: f * ratios[k], dur: L - 1.2, peak: 0.012 * p.shimmer, a: fade, s: 1, d: 0.02, r: fade * 0.8,
      trem: { rate: 0.2 + 0.15 * k, depth: 0.9 }, vib: { rate: 0.3, depth: 8 },
    });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.5, L * 0.3);
  const win = (x) => Math.min(1, x / 0.6, (L - x) / 0.8);
  const root = 220 * p.pitch;
  // voices stop 1 s early so the room has rung out by dur
  const room = T.reverb(out, t, { time: 1.8, mix: 0.55, tone: 0.7 });
  const body = L - 1;
  // the pad: notes at 2x, 3x and 4.5x the root, each pair beating very slowly
  [[2, 1], [3, 0.8], [4.5, 0.5]].forEach((nt, k) => {
    [-1, 1].forEach((s) => {
      const place = T.pan(room, t, { x: s * 0.75, to: s * 0.25, dur: body });
      T.osc(place, t, {
        f: root * nt[0] + s * (0.15 + 0.05 * k), dur: body, peak: (0.006 + 0.009 * p.glow) * nt[1],
        a: fade, s: 1, d: 0.02, r: fade, trem: { rate: 0.07 + 0.04 * k, depth: 0.6 },
      });
    });
  });
  // far air: two independent bands, one in each ear, breathing slowly
  [-0.9, 0.9].forEach((x, k) => {
    const band = T.filter(T.pan(out, t, { x }), t, { type: 'bandpass', f: 3600, q: 0.6, dur: 0.1 });
    T.lfo(band, t, { rate: 0.1 + 0.05 * k, depth: 900, dur: L, a: fade });
    T.noise(band, t, {
      filter: 'none', dur: L, peak: 0.004 + 0.008 * p.glow, a: fade, s: 1, d: 0.02, r: fade,
    });
  });
  // the stars: a pentatonic scale from 8x the root, each ringing and flickering
  const scale = [1, 1.125, 1.25, 1.5, 1.667, 2, 2.25];
  const n = Math.round(p.stars);
  const span = Math.max(0.5, L - 0.4 - 2.4);
  for (let k = 0; k < n; k++) {
    const at = 0.4 + ((k + T.rand(0.1, 0.9)) * span) / n;
    const f = root * 8 * scale[Math.floor(T.rand(0, scale.length))];
    const pk = 0.016 * T.rand(0.5, 1) * win(at);
    const place = T.pan(room, t + at, { x: T.rand(-0.9, 0.9) });
    T.osc(place, t + at, { f, dur: 1.1, peak: pk, a: 0.012, trem: { rate: T.rand(4, 8), depth: 0.5 } });
    T.osc(place, t + at, { f: f * 2.01, dur: 0.45, peak: pk * 0.25, a: 0.012 });
  }
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const f = p.fury;
  // a bigger storm is louder as well as wider: the level slope keeps the whole range in one band
  const k = 1 + 0.6 * f;
  [-0.85, 0.85].forEach((x, i) => {
    // every layer of this ear rides one slow swell, each ear on its own pace
    const swell = T.gain(T.pan(out, t, { x }), 0.78);
    T.lfo(swell, t, { param: 'gain', rate: 0.13 + 0.06 * i, depth: 0.22, dur: L, a: fade });
    // the weight underneath, and the roar above it
    T.noise(swell, t, {
      filter: 'lowpass', f: 170 + 190 * f, q: 0.7, dur: L, peak: 0.1 * k, a: fade, s: 1, d: 0.02, r: fade,
    });
    T.noise(swell, t, {
      filter: 'lowpass', f: 650 + 650 * f, q: 0.6, dur: L, peak: 0.045 * k, a: fade, s: 1, d: 0.02, r: fade,
    });
    // the sheet of rain
    T.noise(swell, t, {
      filter: 'bandpass', f: 3800, q: 0.4, dur: L, peak: 0.002 + 0.02 * p.rain, a: fade, s: 1, d: 0.02, r: fade,
    });
  });
  // wide slow gusts, each sweeping across the field as it passes
  const n = Math.max(1, Math.round(L / 2.2));
  const gap = L / n;
  for (let j = 0; j < n; j++) {
    const at = j * gap + T.rand(0, gap * 0.3);
    const len = Math.min(gap * T.rand(1.3, 1.7), L - at);
    const up = T.rand() < 0.5;
    const lane = j % 2 === 0 ? 1 : -1;
    const lap = T.pan(out, t + at, { x: -0.7 * lane, to: 0.7 * lane, dur: len });
    T.noise(lap, t + at, {
      filter: 'bandpass', f: up ? 240 : 650, to: up ? 650 : 240, q: 0.9,
      dur: len, peak: 0.04 * k * T.rand(0.7, 1), a: len * 0.45,
    });
  }
  // the wail: two narrow bands drifting apart, a thin tone on top of the roar
  const wl = T.pan(out, t, { x: -0.5, to: 0.5, dur: L });
  T.noise(wl, t + L * 0.1, {
    filter: 'bandpass', f: 330 + 140 * f, to: 480 + 200 * f, q: 9,
    dur: L * 0.8, peak: 0.55 * p.howl, a: L * 0.3,
  });
  const wr = T.pan(out, t, { x: 0.5, to: -0.5, dur: L });
  T.noise(wr, t + L * 0.2, {
    filter: 'bandpass', f: 520 + 200 * f, to: 400 + 140 * f, q: 9,
    dur: L * 0.65, peak: 0.4 * p.howl, a: L * 0.3,
  });
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.2, L * 0.3);
  const win = (x) => Math.max(0, Math.min(1, x / 0.8, (L - 1.2 - x) / 1.4));
  const f = p.pitch;
  const step = 1 / p.pulse;
  // the pulse echoes a dotted step later; its last notes stop early so the echo dies by dur
  const echo = T.delay(out, t, { time: step * 1.5, fb: 0.35, mix: 0.3, tone: 2200 });
  const n = Math.max(1, Math.floor((L - 1.3) / step));
  for (let k = 0; k < n; k++) {
    const at = k * step + 0.1;
    const w = win(at);
    const pl = T.pan(echo, t + at, { x: k % 2 === 0 ? -0.2 : 0.2 });
    T.osc(pl, t + at, { type: 'sawtooth', f, dur: step * 0.85, peak: 0.03 * w, a: 0.008, lp: { f: 560, to: 200, q: 2.5 } });
    T.osc(pl, t + at, { f, dur: step * 0.85, peak: 0.024 * w, a: 0.008 });
  }
  // the held chord: a minor chord built on the root, its filter opening slowly and swaying
  const lp = T.filter(T.reverb(out, t, { time: 1, mix: 0.25, tone: 0.5 }), t, {
    type: 'lowpass', f: 380 + 700 * p.glow, to: 700 + 1900 * p.glow, dur: L * 0.8, q: 1.2,
  });
  T.lfo(lp, t, { rate: 0.22, depth: 120 + 260 * p.glow, dur: L - 1, a: fade });
  [4, 4.8, 6, 8].forEach((m, k) => {
    [-1, 1].forEach((s) => {
      T.osc(T.pan(lp, t, { x: s * (0.3 + 0.15 * k) }), t, {
        type: 'sawtooth', f: f * m, detune: s * 7, dur: L - 1, peak: (0.006 + 0.01 * p.glow) * (k === 3 ? 0.7 : 1),
        a: fade, s: 1, d: 0.02, r: fade,
      });
    });
  });
  // the road: air rushing past, one independent band per side, sweeping a little
  [-0.9, 0.9].forEach((x, k) => {
    T.noise(T.pan(out, t, { x }), t, {
      filter: 'bandpass', f: 1500 + 300 * k, to: 900 + 500 * k, q: 0.5, dur: L, peak: 0.002 + 0.03 * p.road,
      a: fade, s: 1, d: 0.02, r: fade,
    });
  });
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.3, L * 0.3);
  // a higher band passes more of the noise: trim it so the level holds as pitch moves
  const comp = 1 / Math.sqrt(p.pitch);
  T.noise(out, t, {
    filter: 'bandpass', f: 380 * p.pitch, q: 0.9, dur: L, peak: 0.055 * comp, a: fade, s: 1, d: 0.02, r: fade,
  });
  // gusts: one swell per two seconds, each rising or falling in pitch as it passes
  const n = Math.max(1, Math.round(L / 2));
  const span = L / n;
  for (let k = 0; k < n; k++) {
    const at = k * span + T.rand(0, span * 0.3);
    const len = Math.min(span * T.rand(1.3, 1.7), L - at);
    const up = T.rand() < 0.5;
    T.noise(out, t + at, {
      filter: 'bandpass', f: (up ? 260 : 700) * p.pitch, to: (up ? 700 : 260) * p.pitch, q: 1.4,
      dur: len, peak: 0.17 * p.gust * comp * T.rand(0.7, 1), a: len * 0.4,
    });
  }
  // the whistle: a narrow band is a nearly pure tone, so it needs a much higher peak to be heard
  T.noise(out, t + L * 0.2, {
    filter: 'bandpass', f: 1150 * p.pitch, to: 1500 * p.pitch, q: 22,
    dur: L * 0.65, peak: 0.16 * p.whistle * comp, a: L * 0.25,
  });
}

function (T, out, t, p) {
  const L = p.length;
  const fade = Math.min(1.5, L * 0.3);
  const f = p.pitch;
  // the bowl: [ratio, level, beat in Hz], each pair split to both sides and detuned by its beat
  [[1, 1, 0.45], [2.71, 0.3, 0.8], [5.15, 0.1, 1.3]].forEach((b) => {
    [-1, 1].forEach((s) => {
      T.osc(T.pan(out, t, { x: s * 0.5 }), t, {
        f: f * b[0] + s * b[2] * 0.5, dur: L, peak: 0.013 * b[1], a: fade, s: 1, d: 0.02, r: fade,
      });
    });
  });
  T.osc(out, t, { f: f / 2, dur: L, peak: 0.007, a: fade, s: 1, d: 0.02, r: fade, trem: { rate: 0.12, depth: 0.4 } });
  // the breath: an inhale that brightens and an exhale that darkens, each a crossfading pair.
  // Whole breaths only, centred in the bed so the fades never cut one off.
  const C = Math.min(p.cycle, L - 0.6);
  const inh = C * 0.42;
  const n = Math.max(1, Math.floor((L - 0.4) / C));
  const first = (L - n * C) / 2;
  for (let k = 0; k < n; k++) {
    const at = first + k * C;
    T.noise(out, t + at, {
      filter: 'bandpass', f: 420, to: 1100, q: 1.2, glide: inh, dur: inh * 1.45, peak: 0.11 * p.breath,
      a: inh, curve: 'lin',
    });
    T.noise(out, t + at + inh, {
      filter: 'bandpass', f: 1100, to: 380, q: 1.2, glide: C - inh, dur: C - inh, peak: 0.095 * p.breath,
      a: (C - inh) * 0.2, curve: 'lin',
    });
  }
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const chip = T.crush(out, t, { bits: 8 - 3 * p.edge });
  const m = Math.round(p.stabs);
  const am = ['A4', 'C5', 'E5'];
  for (let k = 0; k < m; k++) {
    for (let j = 0; j < 3; j++) {
      T.osc(chip, t + k * 0.14 * s, { type: 'square', f: n(am[j]), dur: 0.09 * s, peak: 0.026, a: 0.003, s: 0.8, d: 0.02, r: 0.02 });
    }
  }
  // the long chord: A C Eb F# (diminished seventh) with a vibrato that tightens the tension
  const at = t + m * 0.14 * s;
  const dim = ['A4', 'C5', 'D#5', 'F#5'];
  for (let j = 0; j < 4; j++) {
    T.osc(chip, at, {
      type: 'square', f: n(dim[j]), dur: 0.5 * s, peak: 0.022, a: 0.003, s: 0.8, d: 0.05, r: 0.1, vib: { rate: 8, depth: 14 },
    });
  }
  T.osc(chip, at, { type: 'sine', f: n('A2'), to: n('A2') / 2, dur: 0.4 * s, peak: 0.06, a: 0.004 });
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 0.6, mix: 0.15, tone: 0.5 });
  const steps = [['G4', 0, 0.3], ['F#4', 0.34, 0.3], ['F4', 0.68, 0.3], ['E4', 1.02, 1.1]];
  for (let k = 0; k < 4; k++) {
    const at = t + steps[k][1] * s;
    const len = steps[k][2] * s;
    const last = k === 3;
    const f = n(steps[k][0]);
    const open = 500 + 1600 * p.tone;
    // each note opens its filter, then closes it again: the "wah"
    const lp = T.filter(room, at, { type: 'lowpass', f: open * 0.45, to: open, dur: len * 0.25, q: 0.9 });
    const o = {
      dur: len, peak: 0.05, a: 0.03, s: 0.7, d: 0.1, r: Math.min(0.2, len * 0.4),
      to: f * (last ? 1 - 0.2 * p.droop : 0.985),
    };
    T.osc(lp, at, { ...o, type: 'sawtooth', f, detune: -8, vib: last ? { rate: 5.5, depth: 20 * p.droop } : null });
    T.osc(lp, at, { ...o, type: 'sawtooth', f, detune: 8, peak: 0.04, vib: last ? { rate: 5.5, depth: 20 * p.droop } : null });
  }
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 0.8, mix: 0.18, tone: 0.6 });
  const hit = (at, names, len, pk) => {
    for (let k = 0; k < names.length; k++) {
      const lp = T.filter(room, t + at, { type: 'lowpass', f: 500 + 400 * p.brass, to: 1800 + 2600 * p.brass, dur: 0.09, q: 0.9 });
      const o = { type: 'sawtooth', f: n(names[k]), dur: len, peak: pk, a: 0.02, s: 0.85, d: 0.08, r: Math.min(0.2, len * 0.4) };
      T.osc(lp, t + at, { ...o, detune: -6 });
      T.osc(lp, t + at, { ...o, detune: 6 });
    }
  };
  hit(0, ['G4', 'C5'], 0.13 * s, 0.028);
  hit(0.17 * s, ['G4', 'C5'], 0.13 * s, 0.028);
  hit(0.34 * s, ['G4', 'C5', 'E5'], 0.13 * s, 0.025);
  const end = 0.52 * s;
  hit(end, ['C5', 'E5', 'G5'], 0.9 * s, 0.03);
  // weight: the root an octave down, and a cymbal wash on the last chord
  hit(end, ['C4'], 0.9 * s, 0.04 * p.weight + 0.004);
  T.noise(room, t + end, { filter: 'highpass', f: 5000, q: 0.7, dur: 0.9, peak: 0.03 * p.weight, a: 0.005 });
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 2, mix: p.space, tone: 0.5 });
  const land = 0.75 * s;
  // the sweep peaks as the chord arrives
  T.noise(room, t, { filter: 'bandpass', f: 400, to: 5000, q: 1.2, dur: land + 0.05, peak: 0.05, a: land });
  // the chord: four FM tones whose brightness settles as they ring
  const names = ['C4', 'E4', 'G4', 'B4'];
  for (let k = 0; k < 4; k++) {
    T.fm(room, t + land, { f: n(names[k]), ratio: 2, index: 1.4, index1: 0.1, dur: 1.8, peak: 0.028, a: 0.012 });
  }
  // the swell: a low octave that blooms under the chord
  T.osc(room, t + land - 0.1, { f: n('C3'), dur: 2, peak: 0.04, a: 0.4, s: 0.7, d: 0.4, r: 0.9 });
  // the glint
  T.bell(room, t + land + 0.12, { f: n('C7'), dur: 1.4, peak: 0.012 + 0.016 * p.shine });
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 1.4, mix: p.space, tone: 0.6 });
  const arp = ['C5', 'E5', 'G5', 'C6', 'E6', 'G6'];
  for (let k = 0; k < 6; k++) {
    T.pluck(room, t + k * 0.085 * s, { f: n(arp[k]), dur: 0.55, bright: 0.65, peak: 0.07 });
  }
  // the landing: bell on top, triangle triad under it, a breath of air above
  const at = t + 0.6 * s;
  T.bell(room, at, { f: n('C6'), dur: 1.5, peak: 0.03 + 0.012 * p.sparkle });
  const triad = ['C5', 'E5', 'G5'];
  for (let k = 0; k < 3; k++) {
    T.osc(room, at, { type: 'triangle', f: n(triad[k]), dur: 1.2, peak: 0.025, a: 0.01, s: 0.6, d: 0.3, r: 0.5 });
  }
  T.noise(room, at, { filter: 'highpass', f: 6000, to: 9000, q: 0.8, dur: 0.5, peak: 0.04 * p.sparkle, a: 0.03 });
}

function (T, out, t, p) {
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const eco = T.delay(out, t, { time: 0.11, fb: 0.2 + 0.3 * p.echo, mix: 0.5 * p.echo, tone: 2500 });
  const gap = 0.075 / p.speed;
  const m = Math.round(p.notes);
  // always end on the tonic: the last m of C E G C
  const run = ['C5', 'E5', 'G5', 'C6'].slice(4 - m);
  for (let k = 0; k < m; k++) {
    const last = k === m - 1;
    const len = last ? 0.26 : gap * 1.3;
    T.osc(eco, t + k * gap, { type: 'square', f: n(run[k]), dur: len, peak: last ? 0.042 : 0.036, a: 0.004, s: 0.7, d: 0.03, r: 0.05 });
    T.osc(eco, t + k * gap, { type: 'triangle', f: n(run[k]) / 2, dur: len, peak: 0.03, a: 0.004, s: 0.7, d: 0.03, r: 0.05 });
  }
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 2.2, mix: p.space, tone: 0.35 });
  const idx = 1.5 + 3 * p.eerie;
  T.fm(room, t, { f: n('D4'), ratio: 1.41, index: idx, index1: 0.3, dur: 1.6, peak: 0.04, a: 0.01 });
  T.fm(room, t + 0.55 * s, { f: n('G#4'), ratio: 1.41, index: idx, index1: 0.3, dur: 1.6, peak: 0.04, a: 0.01 });
  // the pad: a low sine that swells under the second bell
  T.osc(room, t, {
    f: n('D3'), dur: 2.2, peak: 0.035, a: 0.5 * s, s: 0.7, d: 0.5, r: 1,
    trem: { rate: 5.5, depth: 0.5 * p.eerie }, vib: { rate: 4.5, depth: 12 * p.eerie },
  });
  T.noise(room, t + 0.4 * s, { filter: 'highpass', f: 6500, q: 0.8, dur: 1.5, peak: 0.02 * p.eerie, a: 0.6 });
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const room = T.reverb(out, t, { time: 0.9, mix: 0.2, tone: 0.6 });
  // "ta": a short dyad
  const ta = ['G4', 'C5'];
  for (let k = 0; k < 2; k++) {
    T.osc(room, t, { type: 'triangle', f: n(ta[k]), dur: 0.11, peak: 0.035, a: 0.004, s: 0.6, d: 0.03, r: 0.04 });
  }
  // "daa": the chord, with the bass as the weight
  const at = t + 0.17 * s;
  const chord = ['C5', 'E5', 'G5', 'C6'];
  for (let k = 0; k < 4; k++) {
    T.osc(room, at, { type: 'triangle', f: n(chord[k]), dur: 1, peak: 0.024, a: 0.006, s: 0.6, d: 0.2, r: 0.4 });
    T.pluck(room, at, { f: n(chord[k]), dur: 0.8, bright: 0.6, peak: 0.03 });
  }
  T.osc(room, at, { f: n('C3'), dur: 1, peak: 0.01 + 0.045 * p.weight, a: 0.006, s: 0.6, d: 0.2, r: 0.4 });
  // the sparkle: a quick glissando up into a bell and a shimmer
  T.osc(room, t + 0.1 * s, { f: n('C6'), to: n('C8'), dur: 0.18 * s + 0.05, peak: 0.012 * p.sparkle + 0.002, a: 0.01 });
  T.bell(room, at, { f: n('C7'), dur: 1, peak: 0.01 + 0.015 * p.sparkle });
}

function (T, out, t, p) {
  const s = 1 / p.tempo;
  const n = (name) => T.note(name) * Math.pow(2, p.key / 12);
  const chip = T.crush(out, t, { bits: 8 - 3 * p.crunch });
  const b = 0.1 * s;
  const run = ['G4', 'C5', 'E5', 'G5'];
  for (let k = 0; k < 4; k++) {
    T.osc(chip, t + k * b, { type: 'square', f: n(run[k]), dur: b * 1.05, peak: 0.048, a: 0.004, s: 0.8, d: 0.01, r: 0.015 });
  }
  // the held chord: a square lead with a little vibrato, a triangle triad, and the bass
  const at = 4 * b;
  const hold = 0.6 * s;
  T.osc(chip, at + t, {
    type: 'square', f: n('C6'), dur: hold, peak: 0.048, a: 0.004, s: 0.75, d: 0.08, r: 0.12, vib: { rate: 7, depth: 10 },
  });
  const triad = ['C5', 'E5', 'G5'];
  for (let k = 0; k < 3; k++) {
    T.osc(chip, at + t, { type: 'triangle', f: n(triad[k]), dur: hold, peak: 0.034, a: 0.004, s: 0.8, d: 0.08, r: 0.12 });
  }
  T.osc(chip, at + t, { type: 'triangle', f: n('C3'), dur: hold, peak: 0.04 * p.bass + 0.004, a: 0.004, s: 0.85, d: 0.08, r: 0.1 });
}

function (T, out, t, p) {
