babble.src:
function babble(out, t, o) {
  o = o || {};
  const all = babbleVoices();
  const v = o.voice && typeof o.voice === 'object' ? o.voice : all[o.voice] || all.cute;
  return chatter(out, t, Object.assign({}, o, { voice: v }));
}

